function imgDB(){return new Promise((res,rej)=>{const r=indexedDB.open('yibeiImg',1);r.onupgradeneeded=e=>{try{e.target.result.createObjectStore('img');}catch(_){}};r.onsuccess=e=>res(e.target.result);r.onerror=()=>rej();});}
