function svgIc(name,size,color,sw){const p=ICONS[name];if(!p)return '';size=size||22;
  return '<svg viewBox="0 0 24 24" width="'+size+'" height="'+size+'" fill="none" stroke="'+(color||'currentColor')+'" stroke-width="'+(sw||1.9)+'" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:middle">'+p+'</svg>';}
const HOMEAPPS=[['wechat','💬','微信'],['settings','⚙️','设置'],['aiaccount','AI','AI账户'],['worldbook','📖','世界书'],['browser','🌐','浏览器'],['moments','🌸','朋友圈'],['spy','🔍','查他手机'],['shop','🛒','购物'],['calendar','📅','日历'],['x','𝕏','X'],['food','🍔','外卖'],['couple','💞','情侣空间'],['tasks','📋','任务便签'],['games','🎮','游戏大厅'],['mail','','信箱'],['offline','🌹','线下约会'],['music','🎵','音乐'],['roleplay','','角色扮演'],['travel','✈','云程'],['contacts','👤','通讯录'],['me','🐱','我']];
function appIconEditor(){S.me.appIcons=S.me.appIcons||{};
  openModal(`<h3>App 图标</h3><div class="hint">给主屏图标换成你喜欢的图片，留空恢复默认。</div>
   ${HOMEAPPS.map(a=>`<div class="it"><span>${S.me.appIcons[a[0]]?'':a[1]} ${a[2]}</span><span class="v">${S.me.appIcons[a[0]]?`<img src="${S.me.appIcons[a[0]]}" style="width:26px;height:26px;border-radius:6px;object-fit:cover;vertical-align:middle">`:''}<button class="minibtn" style="margin-left:6px" onclick="setAppIcon('${a[0]}')">${S.me.appIcons[a[0]]?'换':'上传'}</button>${S.me.appIcons[a[0]]?`<button class="minibtn" style="margin-left:4px" onclick="delete S.me.appIcons['${a[0]}'];save();appIconEditor();render()">复位</button>`:''}</span></div>`).join('')}
   <button class="btn g" style="margin-top:8px" onclick="closeModal()">关闭</button>`);}
function setAppIcon(key){pickFile('image/*',async f=>{S.me.appIcons=S.me.appIcons||{};S.me.appIcons[key]=await compress(f,200,.8);save();appIconEditor();render();toast('图标已换 🎨');});}
const LOCKABLE={browser:'浏览器',moments:'朋友圈',spy:'查他手机',shop:'购物',calendar:'日历',x:'X',douyin:'抖音',food:'外卖',games:'游戏大厅',mail:'信箱',offline:'线下约会',roleplay:'角色扮演',tale:'规则怪谈',dread:'惊悚抉择',music:'音乐',travel:'云程'};
function appLocked(key){return !!(S.couple&&S.couple.locks&&S.couple.locks[key]);}
function appLk(key){return appLocked(key)?'🔒':'';}
function openApp(key){if(S.jail&&S.jail.active){toast('你被关在禁闭室里…出不去');go('jail');return;}if(appLocked(key)){toast('「'+(LOCKABLE[key]||key)+'」被ta锁了，去情侣空间求他解开');go('couple');return;}if(key==='mail'){if(lockClearTarget({type:'mail'},true))save(500);}else if(key==='x'){if(lockClearTarget({type:'x'},true))save(500);}
  ({browser:()=>go('browser'),moments:()=>openWeChat('moments'),spy:openSpy,shop:()=>go('shop'),calendar:()=>go('calendar'),x:openX,douyin:openDouyin,food:()=>go('food'),games:openGames,mail:()=>go('mail'),offline:openOfflineMenu,roleplay:()=>go('rphub'),tale:taleStart,dread:dreadStart,music:()=>{musicInit();go('music');},travel:()=>{tvInit();go('travel');}}[key]||(()=>{}))();}

/* ---------- 软件使用时长 / 限额倒计时（只对授权的软件生效） ---------- */
// 把当前所在页面映射到 LOCKABLE 的 appKey；不在任何受控软件里返回 null
function curAppKey(){const p=cur().p;
  const map={browser:'browser',spy:'spy',shop:'shop',shopcs:'shop',calendar:'calendar',food:'food',mail:'mail',gs:'games',uc:'games',off:'offline',rphub:'roleplay',rpset:'roleplay',rp:'roleplay',tale:'tale',dread:'dread',music:'music',x:'x',xtweet:'x',xdm:'x',xuser:'x',dy:'douyin',dydm:'douyin'};
  if(map[p])return map[p];
  if(p==='wechat'&&wxTab==='moments')return 'moments';
  return null;}
// 今日额度（分钟）+ 今日加时（秒），仅授权软件
function limitSecOf(key){if(!(S.couple&&S.couple.cid))return 0;const g=S.couple.grant||{};const tl=S.couple.timeLimit||{};
  if(!g[key]||!tl[key])return 0;const au=ensureUsage();return tl[key]*60+(au.bonus[key]||0);}
function ensureUsage(){const today=todayStr();if(!S.me.appUsage||S.me.appUsage.date!==today){S.me.appUsage={date:today,used:{},bonus:{}};}
  S.me.appUsage.used=S.me.appUsage.used||{};S.me.appUsage.bonus=S.me.appUsage.bonus||{};return S.me.appUsage;}
function usedSecOf(key){const au=ensureUsage();return au.used[key]||0;}
let _useSaveT=0;
function usageTick(){const el=$('#useBadge');const hide=()=>{if(el)el.style.display='none';};
  if(document.hidden||!(S.couple&&S.couple.cid))return hide();
  const key=curAppKey();const g=S.couple.grant||{};
  // 只有「授权」的软件才记录时长、才有倒计时
  if(!key||!g[key])return hide();
  if(appLocked(key))return hide();
  const au=ensureUsage();au.used[key]=(au.used[key]||0)+1;          // 授权软件：统计已用时长（后台/查手机都看得到）
  const limit=limitSecOf(key);                                      // 设了上限才倒计时+自动锁
  if(limit>0){const remain=limit-au.used[key];
    if(remain<=0){S.couple.locks=S.couple.locks||{};if(!S.couple.locks[key])S.couple.locks[key]={pwd:0,time:Date.now(),auto:true};
      behaviorRecord('app','「'+(LOCKABLE[key]||key)+'」今天用满 '+Math.floor(limit/60)+' 分钟限额，被自动锁上', 'app-limit',{gapMs:2*3600000});save();hide();toast('「'+(LOCKABLE[key]||key)+'」今天的时间用完啦，被自动锁上了，去求ta解开~');home();return;}
    if(el){const m=Math.floor(remain/60),s=remain%60;el.style.display='block';
      el.textContent='⏳ '+(LOCKABLE[key]||'')+' '+m+':'+String(s).padStart(2,'0');
      el.className='usebadge'+(remain<=60?' warn':'');}}
  else hide();
  if(Date.now()-_useSaveT>5000){_useSaveT=Date.now();save();}}
setInterval(usageTick,1000);
// 睡眠计时
const SLEEP_AUTO_END_MIN_MS=60000;
function sleepStart(){if(!S.me.sleep)S.me.sleep={active:null,records:[]};S.me.sleep.active=Date.now();S.me.sleep.autoEndOnOpen=true;S.me.sleep.awayAfterStart=false;S.me.sleep.awayAt=0;save();render();toast('开始睡眠计时，好梦~');}
function sleepMarkAway(){const sl=S.me&&S.me.sleep;if(!sl||!sl.active)return;sl.awayAfterStart=true;sl.awayAt=Date.now();save(0);}
function sleepAutoEndOnOpen(){const sl=S.me&&S.me.sleep;if(!sl||!sl.active||!sl.autoEndOnOpen||!sl.awayAfterStart)return false;
  if(Date.now()-sl.active<SLEEP_AUTO_END_MIN_MS)return false;sleepEnd(true);return true;}
function reportNotify(note){if(!(S.couple&&S.couple.cid))return;const c=getC(S.couple.cid);if(c&&!c.blocked)scheduleReply(c.id,note);}
function reportStart(type){type=(''+(type||'')).trim().slice(0,16);if(!type)return;if(!S.me.report)S.me.report={active:null,log:[]};if(S.me.report.active)reportEnd(true);
  S.me.report.active={type,start:Date.now()};save();render();toast('已报备：'+type);}
  // 报备只默默计时、不主动给角色发消息；他查岗/聊天时会从上下文知道你在干嘛（更真实）
function reportCustom(){const t=prompt('报备你要去干嘛：','');if(t==null)return;reportStart(t);}
function reportEnd(silent){const rp=S.me.report;if(!rp||!rp.active)return;const a=rp.active,end=Date.now();rp.log=rp.log||[];rp.log.unshift({type:a.type,start:a.start,end});if(rp.log.length>40)rp.log=rp.log.slice(0,40);rp.active=null;save();if(!silent)render();}
  // 报备结束也不主动发消息，只记进报备记录；他查的时候自己看时长合不合理
function reportDel(i){if(!S.me.report||!S.me.report.log)return;S.me.report.log.splice(i,1);save();render();}
function sleepEnd(auto){const sl=S.me.sleep;if(!sl||!sl.active)return;const automatic=auto===true||auto==='auto',st=sl.active,en=Date.now();sl.records=sl.records||[];sl.records.unshift({start:st,end:en});if(sl.records.length>60)sl.records=sl.records.slice(0,60);
  {const h=new Date(st).getHours();if(h>=1&&h<5)behaviorRecord('late','睡眠记录显示 '+hm(st)+' 才开始睡，睡到 '+hm(en), 'sleep',{gapMs:8*3600000,force:true});}
  sl.active=null;sl.autoEndOnOpen=false;sl.awayAfterStart=false;sl.awayAt=0;save();render();toast(automatic?'已自动结束睡眠，记录好啦':'醒啦，已记录这次睡眠');}
async function sleepDel(i){if(!S.me.sleep||!S.me.sleep.records)return;if(!await uiConfirm('删掉这条睡眠记录？'))return;S.me.sleep.records.splice(i,1);save();render();}
function sleepDurTxt(ms){const mins=Math.max(0,Math.round(ms/60000));const h=Math.floor(mins/60),m=mins%60;return (h?h+'小时':'')+(m||!h?m+'分钟':'');}
function ymd(t){const d=new Date(t);return (d.getMonth()+1)+'月'+d.getDate()+'日';}
function ymdFull(t){const d=new Date(t||Date.now());return d.getFullYear()+'年'+(d.getMonth()+1)+'月'+d.getDate()+'日';}
function fmtDT(t){return ymdFull(t)+' '+hm(t);}
function dayStartMs(t){const d=new Date(t||Date.now());d.setHours(0,0,0,0);return d.getTime();}
function dayGap(a,b){return Math.max(0,Math.floor((dayStartMs(b||Date.now())-dayStartMs(a||Date.now()))/86400000));}
function openWeChat(tab){wxTab=tab||'chats';go('wechat');scanProactive();}
function scanProactive(){S.contacts.forEach(c=>{if(!c.deleted&&c.proactive&&c.proactive.enabled)maybeProactive(c.id);});}
function saveAuto(id){const c=getC(id);c.autoMoment=Math.max(0,+$('#ap_m').value||0);c.autoTweet=Math.max(0,+$('#ap_t').value||0);save();toast('已保存');}
function scanAutoPost(){if(!S._autoPost)S._autoPost={};const today=new Date().toDateString();
  S.contacts.forEach(c=>{if(c.deleted||c.blocked)return;const pc=S._autoPost[c.id]||{date:today,m:0,t:0,last:0};if(pc.date!==today){pc.date=today;pc.m=0;pc.t=0;}S._autoPost[c.id]=pc;
    if(Date.now()-pc.last<2400000)return;
    if((c.autoMoment||0)>pc.m&&Math.random()<0.5){pc.m++;pc.last=Date.now();save();doAutoMoment(c.id);return;}
    if((c.autoTweet||0)>pc.t&&Math.random()<0.5){pc.t++;pc.last=Date.now();save();doAutoTweet(c.id);}
  });}
async function doAutoMoment(id){const c=getC(id);try{const r=await chatAPI([{role:'system',content:buildSystem(c)},{role:'user',content:'现在你想发条朋友圈（结合此刻心情/日常/和'+S.me.name+'的关系都行），只输出动态内容本身，一两句，别带方括号。'}]);
  S.moments.unshift({id:uid(),authorId:id,text:cleanReply(r).slice(0,120),images:[],time:Date.now(),likes:[],comments:[],acct:actId()});save();if(cur().p==='wechat'&&wxTab==='moments')render();toast(''+(c.remark||c.name)+'发了朋友圈');}catch(e){}}
function publishRoleTweet(c,text,opt){opt=opt||{};text=(''+(text||'')).trim();if(!c||!text)return false;const now=Date.now(),norm=text.toLowerCase().replace(/\s+/g,'').replace(/[^\u4e00-\u9fa5a-z0-9]/g,'');
  const recent=(S.x&&S.x.tweets||[]).filter(t=>t.who===c.id&&now-(t.time||0)<10*60000);if((c._lastTweetAt&&now-c._lastTweetAt<30000)||recent.some(t=>(''+(t.text||'')).toLowerCase().replace(/\s+/g,'').replace(/[^\u4e00-\u9fa5a-z0-9]/g,'')===norm))return false;
  const nm=c.name;xUser(nm,{handle:'@'+c.name.replace(/\s/g,''),avatar:c.avatar,cid:c.id});S.x.tweets.unshift({id:uid(),who:c.id,name:nm,handle:'@'+c.name.replace(/\s/g,''),avatar:c.avatar,text,time:now,likes:[],lk:Math.floor(Math.random()*(opt.auto?80:60)),comments:[],rt:0});c._lastTweetAt=now;save();if(cur().p==='x')render();if(opt.notify)notifyX(c,text);if(opt.toast)toast('𝕏 '+nm+'发了推');return true;}
async function doAutoTweet(id){const c=getC(id);try{const _co=(typeof circleObj==='function')?circleObj(id):{};const note=_co.desc?'，贴合你的圈子定位「'+_co.desc+'」':'';
  const r=await chatAPI([{role:'system',content:buildSystem(c)},{role:'user',content:'现在你想发条推特'+note+'，一两句，只输出推文内容，别带方括号。'}],{aux:true});
  publishRoleTweet(c,cleanReply(r),{auto:true,notify:true});}catch(e){}}
function notifyX(c,text){if(c.muted)return;playDing();lockNotify((c.remark||c.name)+' 发了新动态',text,{icon:'note',target:{type:'x'}});appNotify((c.remark||c.name)+' 发了新动态',text,{tag:'x-'+c.id,data:{type:'open',target:'x'}});if(lockVisible())return;const b=$('#msgBanner');if(!b)return;
  b.innerHTML=`<div style="width:34px;height:34px;border-radius:9px;background:#000;border:1px solid #333;color:#fff;display:flex;align-items:center;justify-content:center;font-size:16px">𝕏</div><div style="flex:1;min-width:0"><div class="bn">${esc(c.remark||c.name)} 发了新动态</div><div class="bm">${esc(text)}</div></div>`;
  b.className='msgbanner show';b.onclick=()=>{b.className='msgbanner';openX();};
  clearTimeout(_bannerT);_bannerT=setTimeout(()=>{b.className='msgbanner';},4500);}
setInterval(scanAutoPost,240000);setTimeout(scanAutoPost,8000);

/* ---------- 设置 ---------- */
let _setTab=1;
function setTab(n){_setTab=n;const p1=$('#setpage1'),p2=$('#setpage2'),t1=$('#settab1'),t2=$('#settab2');if(!p1||!p2)return;
  p1.style.display=n===2?'none':'block';p2.style.display=n===2?'block':'none';
  if(t1){t1.style.background=n===2?'#2c2c2e':'#07c160';t1.style.color=n===2?'#ccc':'#fff';}
  if(t2){t2.style.background=n===2?'#07c160':'#2c2c2e';t2.style.color=n===2?'#fff':'#ccc';}}
function jumpToSection(id){const el=document.getElementById(id);if(!el)return;try{el.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){el.scrollIntoView(true);}}
function settingsJump(tab,id){setTab(tab);setTimeout(()=>jumpToSection(id),60);}
function coupleJump(tab,id){couTab(tab);setTimeout(()=>jumpToSection(id),60);}
function quickJumpBar(items){return `<div class="section" style="margin:0 0 10px;border-radius:12px;overflow:hidden"><div style="padding:10px 12px"><div style="font-size:12px;color:#888;margin-bottom:7px">快捷入口</div><div style="display:flex;flex-wrap:wrap;gap:6px">${items.map(x=>`<button class="minibtn" style="background:#24242a;color:#ddd;border:1px solid rgba(255,255,255,.08)" onclick="${x[1]}">${x[0]}</button>`).join('')}</div></div></div>`;}
function renderSettings(){const a=S.settings.chat,v=S.settings.vision;
  return `<div class="nav"><span class="l" onclick="back()">‹</span><span class="t">设置</span><span class="r"></span></div>
  <div class="scroll" id="settingsscroll" style="padding:12px;background:#000">
    <div class="section" style="border:1px solid rgba(255,143,171,.5);background:linear-gradient(135deg,rgba(255,143,171,.18),rgba(108,92,231,.14));margin-bottom:10px" onclick="showManual()"><div class="it" style="background:transparent"><span><b style="color:#ffd0df;font-size:15px">📖 使用说明书 · 常见报错</b><br><small style="color:#aaa">404、501、密钥、模型、安卓黑屏等问题都在这里</small></span><span class="v" style="color:#ff8fab">随时查看 ›</span></div></div>
    <div style="display:flex;gap:8px;margin-bottom:10px">
      <button class="minibtn" id="settab1" style="flex:1;${_setTab===2?'background:#2c2c2e;color:#ccc':'background:#07c160;color:#fff'}" onclick="setTab(1)">接口·模型</button>
      <button class="minibtn" id="settab2" style="flex:1;${_setTab===2?'background:#07c160;color:#fff':'background:#2c2c2e;color:#ccc'}" onclick="setTab(2)">偏好·工具</button></div>
    ${quickJumpBar([['聊天',"settingsJump(1,'set_chat')"],['辅助',"settingsJump(1,'set_aux')"],['联网',"settingsJump(1,'set_search')"],['识图',"settingsJump(1,'set_vision')"],['语音',"settingsJump(1,'set_tts')"],['偏好',"settingsJump(2,'set_prefs')"],['外观',"settingsJump(2,'set_look')"],['表情/语音',"settingsJump(2,'set_media')"],['AI真图',"settingsJump(2,'set_image')"],['桌面布局',"settingsJump(2,'set_layout')"],['备份',"settingsJump(2,'set_backup')"],['存储',"settingsJump(2,'set_storage')"]])}
    <div id="setpage1" style="display:${_setTab===2?'none':'block'}">
    <div class="hint">聊天和识图可以用不同模型。地址已经预填好了，填上 Key 就能用。</div>
    <div class="section" id="set_chat"><div style="padding:12px 14px;font-weight:600;color:#07c160">聊天模型</div>
      <div class="field" style="padding:0 14px"><label>接口地址</label><input id="s_cbase" value="${esc(a.base)}"></div>
      <div class="field" style="padding:0 14px"><label>API Key</label><input id="s_ckey" type="password" value="${esc(a.key)}" placeholder="sk-…"></div>
      <div class="field" style="padding:0 14px"><label>模型名</label><div style="display:flex;gap:6px"><input id="s_cmodel" value="${esc(a.model)}" style="flex:1"><button class="minibtn" onclick="fetchModels('s_cbase','s_ckey','s_cmodel')">拉取</button></div></div>
      <div class="two" style="padding:0 14px 10px"><div class="field"><label>随机度</label><input id="s_ctemp" type="number" step="0.1" value="${a.temp}"></div>
        <div class="field"><label>回复长度</label><input id="s_cmax" type="number" value="${a.maxTokens}"></div></div>
      <div class="btns" style="padding:0 14px 6px"><button class="btn g" onclick="testMain()">测试主模型</button></div><div id="testC" style="font-size:12px;text-align:center;min-height:14px;padding-bottom:8px"></div>
    </div>
    <div class="section" id="set_aux"><div style="padding:12px 14px;font-weight:600;color:#6c5ce7">辅助模型（省钱·给次要功能用）</div>
      <div class="hint" style="padding:0 14px">只有【微信聊天 · 朋友圈 · 信箱】用主模型；其余全用这个便宜的辅助模型：游戏、购物刷新、外卖、X的所有内容、查他手机、联网搜索等。只填「模型名」就行，地址/Key留空会自动复用上面的聊天模型。不填模型名=全部都用主模型。</div>
      <div class="field" style="padding:0 14px"><label>模型名（如 gpt-4o-mini / 更便宜的）</label><div style="display:flex;gap:6px"><input id="s_xmodel" value="${esc((S.settings.aux||{}).model||'')}" placeholder="留空=全部都用主模型" style="flex:1"><button class="minibtn" onclick="fetchModels('s_xbase','s_xkey','s_xmodel')">拉取</button></div></div>
      <div class="two" style="padding:0 14px 10px"><div class="field"><label>接口地址(可选)</label><input id="s_xbase" value="${esc((S.settings.aux||{}).base||'')}" placeholder="留空=同聊天"></div>
        <div class="field"><label>API Key(可选)</label><input id="s_xkey" type="password" value="${esc((S.settings.aux||{}).key||'')}" placeholder="留空=同聊天"></div></div>
      <div class="btns" style="padding:0 14px 6px"><button class="btn g" onclick="testAux()">测试副模型</button></div><div id="testX" style="font-size:12px;text-align:center;min-height:14px;padding-bottom:8px"></div>
    </div>
    <div class="section" id="set_search"><div style="padding:12px 14px;font-weight:600;color:#3a7bd5">联网搜索（浏览器/[联网]用）</div>
      <div class="it"><span>联网方式</span><span class="v">${[["jina","jina搜索"],["model","用模型"]].map(m=>`<span onclick="S.settings.search=Object.assign({base:\'https://s.jina.ai\',key:\'\',model:\'\'},S.settings.search,{mode:\'${m[0]}\'});save();render()" style="cursor:pointer;padding:3px 9px;border-radius:8px;${((S.settings.search||{}).mode||'jina')===m[0]?'background:#3a7bd5;color:#fff':'color:#888'}">${m[1]}</span>`).join('')}</span></div>
      ${((S.settings.search||{}).mode||'jina')==='model'?`<div class="hint" style="padding:0 14px">用你的兼容API搜索。<b>普通模型不能真联网</b>(只会凭记忆答)；要真联网请填<b>带联网能力的模型</b>(如 -online / sonar / gpt-4o-search-preview)。地址/Key留空=用上面的聊天模型。</div>
      <div class="field" style="padding:0 14px"><label>联网模型名</label><input id="s_semodel" value="${esc((S.settings.search||{}).model||'')}" placeholder="留空=用聊天模型(可能不实时)"></div>
      <div class="two" style="padding:0 14px 10px"><div class="field"><label>地址(可选)</label><input id="s_sebase" value="${esc((S.settings.search||{}).base||'')}" placeholder="留空=同聊天"></div><div class="field"><label>Key(可选)</label><input id="s_sekey" type="password" value="${esc((S.settings.search||{}).key||'')}" placeholder="留空=同聊天"></div></div>`:`<div class="hint" style="padding:0 14px">用 jina 真实搜索：去 jina.ai 免费拿 key 填下面。</div>
      <div class="field" style="padding:0 14px"><label>jina接口地址</label><input id="s_sebase" value="${esc((S.settings.search||{}).base||'https://s.jina.ai')}" placeholder="https://s.jina.ai"></div>
      <div class="field" style="padding:0 14px 10px"><label>API Key</label><input id="s_sekey" type="password" value="${esc((S.settings.search||{}).key||'')}" placeholder="jina_xxx"></div>`}
      <div class="btns" style="padding:4px 14px 6px"><button class="btn g" onclick="testSE()">测试联网</button></div><div id="testSE" style="font-size:12px;text-align:center;min-height:14px;padding-bottom:8px"></div>
    </div>
    <div class="section" id="set_vision"><div style="padding:12px 14px;font-weight:600;color:#54a0ff">识图模型（发照片时用）</div>
      <div class="hint" style="padding:0 14px">Claude 会优先走真正的原生图片协议；若中转未开放该协议，会透明改用备用视觉模型看图，角色聊天仍由原来的 Claude 完成。</div>
      <div class="field" style="padding:0 14px"><label>接口地址</label><input id="s_vbase" value="${esc(v.base)}"></div>
      <div class="field" style="padding:0 14px"><label>API Key</label><input id="s_vkey" type="password" value="${esc(v.key)}" placeholder="不填则用聊天的Key"></div>
      <div class="field" style="padding:0 14px 4px"><label>首选识图模型</label><div style="display:flex;gap:6px"><input id="s_vmodel" value="${esc(v.model)}" placeholder="如 claude-opus-4-6" style="flex:1"><button class="minibtn" onclick="fetchModels('s_vbase','s_vkey','s_vmodel')">拉取</button></div></div>
      <div class="field" style="padding:0 14px 10px"><label>备用识图模型（可不填，会从模型列表自动找）</label><div style="display:flex;gap:6px"><input id="s_vfallback" value="${esc(v.fallbackModel||'')}" placeholder="推荐 gemini-2.5-pro" style="flex:1"><button class="minibtn" onclick="fetchModels('s_vbase','s_vkey','s_vfallback')">拉取</button></div></div>
      <div class="btns" style="padding:0 14px 6px"><button class="btn g" onclick="testVision()">测试识图</button></div><div id="testV" style="font-size:12px;text-align:center;min-height:14px;padding-bottom:8px"></div>
    </div>
    <div class="section" id="set_tts"><div style="padding:12px 14px;font-weight:600;color:#b8a4e3">语音API（可选·克隆/更真）</div>
      <div class="hint" style="padding:0 14px">不填=用手机自带音色(免费)。想要克隆/更真，把角色「语音音色」引擎切成 API：<br>· <b>MiniMax 海螺（推荐·国内·便宜·克隆很真）</b>：只用内置AI时模型固定 speech-02-turbo；每个角色可填不同 voice_id。<br>· <b>Speech 2.8 直连</b>：填写下面的 MiniMax 地址和Key后，会明确优先使用这里选择的 2.8 模型，不会再被内置语音覆盖。</div>
      <div class="it"><span>启用语音API<br><small style="color:#888">开：角色语音条和电话使用内置或外置API音色；关：使用手机系统音。</small></span><span class="sw ${ttsEnabled(S.settings.tts||{})?'on':''}" onclick="S.settings.tts=S.settings.tts||{};S.settings.tts.enabled=!ttsEnabled(S.settings.tts);save();render()"></span></div>
      <div class="field" style="padding:0 14px"><label>接口地址</label><input id="s_tbase" value="${esc((S.settings.tts||{}).base||'')}" placeholder="https://api.minimaxi.com 或 api.elevenlabs.io"></div>
      <div class="field" style="padding:0 14px"><label>API Key</label><input id="s_tkey" type="password" value="${esc((S.settings.tts||{}).key||'')}"></div>
      <div class="two" style="padding:0 14px 2px"><div class="field"><label>模型</label><input id="s_tmodel" value="${esc((S.settings.tts||{}).model||'')}" placeholder="speech-02-turbo / eleven_flash_v2_5"></div><div class="field"><label>默认音色</label><input id="s_tvoice" value="${esc((S.settings.tts||{}).voice||'')}" placeholder="male-qn-qingse / voice id / 克隆ID"></div></div>
      <div class="field" style="padding:2px 14px 2px"><label>GroupId（海螺·选填）</label><input id="s_tgroup" value="${esc((S.settings.tts||{}).group||'')}" placeholder="新版sk-api留空即可；若报「token not match group」就把团队ID填这里"></div>
      <div style="padding:2px 14px 4px;font-size:12px;color:#9aa">语音服务与模型（点一下同时填接口和模型）：</div>
      <div style="padding:0 14px 8px">${[['https://api.minimax.io','speech-02-turbo','海螺·省钱'],['https://api.minimax.io','speech-02-hd','海螺·高清'],['https://api.minimax.io','speech-2.8-turbo','海螺2.8·快速'],['https://api.minimax.io','speech-2.8-hd','海螺2.8·表演'],['https://api.elevenlabs.io','eleven_flash_v2_5','Eleven·省额度'],['https://api.elevenlabs.io','eleven_multilingual_v2','Eleven·稳定'],['https://api.elevenlabs.io','eleven_v3','Eleven v3·情绪'],['https://api.fish.audio','s2.1-pro-free','Fish S2.1·免费'],['https://api.hume.ai','octave-2','Hume Octave 2']].map(m=>`<span onclick="pickTtsProvider('${m[0]}','${m[1]}')" style="display:inline-block;margin:0 5px 5px 0;padding:4px 10px;background:#2c2c2e;border-radius:13px;font-size:12px;color:#cdd;cursor:pointer">${m[2]}</span>`).join('')}</div>
      <div style="padding:0 14px 4px;font-size:12px;color:#9aa">海螺常用音色（点一下填入"默认音色"）：</div>
      <div style="padding:0 14px 8px">${[['male-qn-qingse','青涩青年'],['male-qn-jingying','精英青年'],['male-qn-badao','霸道青年'],['presenter_male','男主持'],['audiobook_male_1','有声书男'],['female-shaonv','少女'],['female-yujie','御姐'],['presenter_female','女主持']].map(v=>`<span onclick="pickVoice('${v[0]}')" style="display:inline-block;margin:0 5px 5px 0;padding:4px 10px;background:#2c2c2e;border-radius:13px;font-size:12px;color:#cdd;cursor:pointer">${v[1]}</span>`).join('')}</div>
      <div class="btns" style="padding:0 14px 6px"><button class="btn g" onclick="pullVoices()">拉取我的全部音色（含克隆）</button></div>
      <div class="btns" style="padding:0 14px 6px"><button class="btn g" onclick="testTTS()">测试语音（会响一声）</button></div><div id="testT" style="font-size:12px;text-align:center;min-height:14px;padding-bottom:6px"></div>
      <div style="padding:6px 14px;font-weight:600;color:#7bd38d;font-size:13px">语音转文字（让角色听懂你录的语音·可选）</div>
      <div class="field" style="padding:0 14px"><label>接口地址</label><input id="s_sbase" value="${esc((S.settings.stt||{}).base||'')}" placeholder="https://…/v1（留空用手机识别）"></div>
      <div class="two" style="padding:0 14px 10px"><div class="field"><label>API Key</label><input id="s_skey" type="password" value="${esc((S.settings.stt||{}).key||'')}"></div><div class="field"><label>模型</label><input id="s_smodel" value="${esc((S.settings.stt||{}).model||'')}" placeholder="whisper-1"></div></div>
    </div>
    </div>
    <div id="setpage2" style="display:${_setTab===2?'block':'none'}">
    <div class="section" id="set_prefs">
      <div class="it"><span>带几个回合<br><small style="color:#888">你1句+他的回复=1回合，记得越多越久但越慢</small></span><input id="s_hist" type="number" min="2" max="40" value="${S.settings.hist}" style="width:70px;text-align:right;border:1px solid #38383a;border-radius:8px;padding:5px;background:#2c2c2e;color:#eee"></div>
      <div class="it"><span>通话自动出声<br><small style="color:#888">通话时ta的话自动念出来；聊天里的语音条改成点一下才播</small></span><span class="sw ${S.settings.voiceAuto?'on':''}" onclick="S.settings.voiceAuto=!S.settings.voiceAuto;save();render()"></span></div>
      <div class="it"><span>发消息后手动点回复<br><small style="color:#888">开：发完点「让ta回复」他才回；他主动找你不受影响</small></span><span class="sw ${S.settings.manualReply?'on':''}" onclick="S.settings.manualReply=!S.settings.manualReply;save();render()"></span></div>
      <div class="it"><span>通用活人感增强<br><small style="color:#888">理解上下文、按性格决定策略和消息节奏，并减少复述与重复模板</small></span><span class="sw ${S.settings.humanLike!==false?'on':''}" onclick="S.settings.humanLike=(S.settings.humanLike===false);save();render()"></span></div>
      <div class="it"><span>低频主动与自然回访<br><small style="color:#888">按角色主动度、当前状态和近期话题决定是否主动，不会到点机械催消息</small></span><span class="sw ${S.settings.initiative!==false?'on':''}" onclick="S.settings.initiative=(S.settings.initiative===false);save();render()"></span></div>
      <div class="it"><span>角色当前活动状态<br><small style="color:#888">让ta持续知道自己此刻在工作、通勤、吃饭或休息，避免前后说乱</small></span><span class="sw ${S.settings.currentActivity!==false?'on':''}" onclick="S.settings.currentActivity=(S.settings.currentActivity===false);save();render()"></span></div>
      <div class="it"><span>角色差异化防护<br><small style="color:#888">让不同角色选择不同回应方式，并拦截跨角色重复的安慰、甜宠和固定开头</small></span><span class="sw ${S.settings.personaGuard!==false?'on':''}" onclick="S.settings.personaGuard=(S.settings.personaGuard===false);save();render()"></span></div>
      <div class="it"><span>聊天引用功能<br><small style="color:#888">开：长按一句话可以引用它来问；他也会挑你最在意的那句回你（只聊天，电话不引用）</small></span><span class="sw ${S.settings.quoteOn!==false?'on':''}" onclick="S.settings.quoteOn=(S.settings.quoteOn===false);save();render()"></span></div>
      <div class="it"><span>查他手机·刷新用副模型<br><small style="color:#888">开：用便宜的副模型生成ta手机内容（省钱）；关：用主模型（更稳更贴人设）。哪个刷得出、刷得好就用哪个</small></span><span class="sw ${S.settings.spyAux?'on':''}" onclick="S.settings.spyAux=!S.settings.spyAux;save();render()"></span></div>
      <div class="it">延迟几秒回复<input id="s_delay" type="number" min="0" value="${S.settings.replyDelay}" style="width:70px;text-align:right;border:1px solid #38383a;border-radius:8px;padding:5px;background:#2c2c2e;color:#eee"></div>
      <div class="it">超过几回合自动总结<input id="s_sum" type="number" min="0" value="${S.settings.summaryRounds||0}" style="width:70px;text-align:right;border:1px solid #38383a;border-radius:8px;padding:5px;background:#2c2c2e;color:#eee"></div>
      <div class="it">主动消息间隔(分钟)<input id="s_pidle" type="number" min="1" value="${S.settings.proactiveIdleMin||20}" style="width:70px;text-align:right;border:1px solid #38383a;border-radius:8px;padding:5px;background:#2c2c2e;color:#eee"></div>
      <div class="it"><span>主动找你时打电话几率<br><small style="color:#888">0=只发消息；越高他越爱直接打来(语音/视频)</small></span><input id="s_callprob" type="number" min="0" max="100" value="${S.settings.callProb==null?35:S.settings.callProb}" style="width:70px;text-align:right;border:1px solid #38383a;border-radius:8px;padding:5px;background:#2c2c2e;color:#eee"></div>
      <div class="it"><span>通话静默多久他来问你(分钟)<br><small style="color:#888">通话中你没出声，过这么久他会轻声问你在不在；填 0 = 关闭，全程不打扰</small></span><input id="s_callsilent" type="number" min="0" max="60" value="${S.settings.callSilentMin==null?3:S.settings.callSilentMin}" style="width:70px;text-align:right;border:1px solid #38383a;border-radius:8px;padding:5px;background:#2c2c2e;color:#eee"></div>
      <div class="it">时间感知<span class="sw ${S.settings.timeAware?'on':''}" onclick="S.settings.timeAware=!S.settings.timeAware;save();render()"></span></div>
      <div class="it">联网搜索<span class="sw ${S.settings.web&&S.settings.web.enabled?'on':''}" onclick="S.settings.web={enabled:!(S.settings.web&&S.settings.web.enabled)};save();render()"></span></div>
      <div class="it">提示音<span class="sw ${S.settings.sound?'on':''}" onclick="S.settings.sound=!S.settings.sound;save();render()"></span></div>
      <div class="it" style="flex-wrap:wrap"><span>${svgIc('volume',15,'#bbb')} 音量 <b style="color:#07c160">${Math.round(((S.settings.volume!=null?S.settings.volume:1))*100)}%</b><small style="color:#999;display:block">后台听歌听不清ta讲话，可调到100%以上加大</small></span><input type="range" min="0" max="300" step="10" value="${Math.round(((S.settings.volume!=null?S.settings.volume:1))*100)}" style="width:100%;margin-top:6px" oninput="S.settings.volume=(+this.value)/100;save();this.previousElementSibling.querySelector('b').textContent=this.value+'%'" onchange="playDing()"></div>
      <div class="it">后台通知（点开授权）<span class="v" onclick="reqNotify()">允许 ›</span></div>
    </div>
    <div class="section" id="set_look">
      <div class="it" onclick="alarmManager()"><span>${svgIc('clock',15,'#bbb')} 闹钟</span><span class="v">${S.alarms.length}个 ›</span></div>
      <div class="it"><span>${svgIc('image',15,'#bbb')} 主屏壁纸</span><span class="v"><button class="minibtn" onclick="setHomeBg()">${S.me.homeBg?'换':'上传'}</button>${S.me.homeBg?'<button class="minibtn" style="margin-left:6px" onclick="S.me.homeBg=\'\';save();toast(\'已恢复默认\')">恢复默认</button>':''}</span></div>
      <div class="it"><span>${svgIc('lock',15,'#bbb')} 锁屏壁纸</span><span class="v"><button class="minibtn" onclick="setLockBg()">${S.me.lockBg?'换':'上传'}</button>${S.me.lockBg?'<button class="minibtn" style="margin-left:6px" onclick="S.me.lockBg=\'\';save();renderLockScreen(true);render();toast(\'已恢复默认\')">恢复默认</button>':''}</span></div>
      <div class="it" onclick="appIconEditor()"><span>${svgIc('image',15,'#bbb')} App 图标美化</span><span class="v">自定义主屏图标 ›</span></div>
      <div class="it" onclick="widgetManager()"><span>${svgIc('star',15,'#bbb')} 主屏组件</span><span class="v">${(()=>{widInit();return S.me.widgets.length;})()}个 · 排序/开关 ›</span></div>
      <div class="it"><span>${svgIc('heart',15,'#bbb')} 主屏主题</span><span class="v"><button class="minibtn" style="${(!S.me.theme)?'background:#ff8fab;color:#fff':''}" onclick="S.me.theme='';save();render()">暗黑</button><button class="minibtn" style="margin-left:6px;${S.me.theme==='pink'?'background:#ff8fab;color:#fff':''}" onclick="S.me.theme='pink';save();render();toast('换成淡粉色啦 🌸')">淡粉</button><button class="minibtn" style="margin-left:6px;${S.me.theme==='white'?'background:#ff8fab;color:#fff':''}" onclick="S.me.theme='white';save();render();toast('换成白色啦 🤍')">白色</button></span></div>
      <div class="it"><span>${svgIc('chat',15,'#bbb')} 微信主题</span><span class="v"><button class="minibtn" style="${S.me.wxTheme!=='white'?'background:#ff8fab;color:#fff':''}" onclick="S.me.wxTheme='';save();render();toast('微信换成黑色')">黑色</button><button class="minibtn" style="margin-left:6px;${S.me.wxTheme==='white'?'background:#ff8fab;color:#fff':''}" onclick="S.me.wxTheme='white';save();render();toast('微信换成白色 🤍')">白色</button></span></div>
      <div class="it"><span>${svgIc('phone',15,'#bbb')} 通话背景</span><span class="v"><button class="minibtn" onclick="setCallBg()">${S.me.callBg?'换':'上传'}</button>${S.me.callBg?'<button class="minibtn" style="margin-left:6px" onclick="S.me.callBg=\'\';save();render();toast(\'已恢复默认\')">恢复默认</button>':''}</span></div>
      <div class="it" onclick="fetchWeather(true)"><span>${svgIc('weather',15,'#bbb')} 定位天气</span><span class="v">${S.weather?esc(S.weather.place+' '+S.weather.desc+' '+S.weather.temp+'°'):'点击获取 ›'}</span></div>
    </div>
    <div class="section" id="set_media">
      <div class="it" onclick="aiStkManager()"><span>${svgIc('smile',15,'#bbb')} 角色的表情包</span><span class="v">${(S.aiStickers||[]).length}个 ›</span></div>
      <div class="it"><span>角色发表情频率</span><span class="v"><select id="s_stkfreq" onchange="S.settings.stkFreq=+this.value;save()" style="background:#2c2c2e;border:1px solid #38383a;color:#eee;border-radius:6px;padding:5px">${[[0,'关闭'],[1,'偶尔'],[2,'适中'],[3,'经常']].map(o=>`<option value="${o[0]}" ${(S.settings.stkFreq==null?2:S.settings.stkFreq)===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></span></div>
      <div class="it"><span>角色发语音频率</span><span class="v"><select id="s_voicefreq" onchange="S.settings.voiceFreq=+this.value;save()" style="background:#2c2c2e;border:1px solid #38383a;color:#eee;border-radius:6px;padding:5px">${[[0,'关闭'],[1,'偶尔'],[2,'经常'],[3,'总是']].map(o=>`<option value="${o[0]}" ${(S.settings.voiceFreq==null?1:S.settings.voiceFreq)===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></span></div>
    </div>
    <div class="section" id="set_image">
      <div style="padding:11px 14px 2px;font-weight:600;color:#e58fb0;font-size:13px">${svgIc('image',15,'#e58fb0')} AI 真图（角色发真实照片）</div>
      <div class="it"><span>让角色发真照片<br><small style="color:#888">开：他发照片时真生成一张图（不露脸·贴合人设身形），每张耗几分钱token、约半分钟；关：只显示 [图片] 文字占位</small></span><span class="sw ${S.settings.imgGen?'on':''}" onclick="S.settings.imgGen=!S.settings.imgGen;save();render()"></span></div>
      <div class="field" style="padding:0 14px"><label>接口地址（留空=用上面聊天模型的）</label><input id="s_ibase" value="${esc(S.settings.imgBase||'')}" placeholder="${esc((S.settings.chat&&S.settings.chat.base)||'https://vg.v1api.cc/v1')}"></div>
      <div class="field" style="padding:0 14px"><label>API Key（留空=用聊天模型的）</label><input id="s_ikey" type="password" value="${esc(S.settings.imgKey||'')}" placeholder="留空则用聊天的Key"></div>
      <div class="field" style="padding:0 14px 4px"><label>绘图模型名（默认推荐 gpt-image-2：更像日常照片）</label><div style="display:flex;gap:6px"><input id="s_imgmodel" value="${esc(S.settings.imgModel||'gpt-image-2')}" placeholder="gpt-image-2" style="flex:1"><button class="minibtn" onclick="fetchModels('s_ibase','s_ikey','s_imgmodel')">拉取</button></div></div>
      <div style="padding:0 14px 6px">${[['gpt-image-2','image-2·推荐(日常感更强)'],['gpt-4o-image','4o图·兼容备选']].map(m=>`<span onclick="S.settings.imgModel='${m[0]}';$('#s_imgmodel').value='${m[0]}';save();toast('已选 ${m[0]}')" style="display:inline-block;margin:0 5px 5px 0;padding:4px 10px;background:#2c2c2e;border-radius:13px;font-size:12px;color:#cdd;cursor:pointer">${m[1]}</span>`).join('')}</div>
      <div class="btns" style="padding:0 14px 4px"><button class="btn g" onclick="testImg()">测试出图（真生成一张·约半分钟）</button></div><div id="testImgO" style="font-size:12px;text-align:center;min-height:14px;padding-bottom:6px"></div>
      <div class="hint" style="padding:0 14px 12px">走 <b>/images/generations</b> 接口。现在会默认按更像手机随手拍的方式出图，并给每个角色固定一组视觉锚点，尽量别每次都像换了个人。<b>先点「测试出图」</b>确认模型能用；若你的转发接口不支持新参数，系统会自动回退到兼容模式。</div>
    </div>
    </div>
    <div id="testOut" style="display:none"></div>
    <button class="btn p" onclick="saveSettings()">保存设置</button>
    ${storageMeter()}
    <div class="btns" id="set_layout" style="margin-top:10px"><button class="btn g" onclick="appLayoutEditor()">桌面应用布局（排到第几页·调顺序）</button></div>
    <div id="set_backup">
    <div class="btns" style="margin-top:10px"><button class="btn p" style="background:linear-gradient(135deg,#5bc0de,#8f8fe0)" onclick="cloudSyncModal()">☁️ 云同步（换设备不丢·推荐）</button></div>
    <div class="btns" style="margin-top:8px"><button class="btn g" onclick="exportData()">导出备份(文件)</button><button class="btn g" onclick="importData()">导入</button></div>
    </div>
    <div class="btns" style="margin-top:18px"><button class="btn d" onclick="clearAllData()">一键清空所有数据</button></div>
    <div class="hint" style="text-align:center;padding:2px 14px">只清聊天/记忆/朋友圈/动态/钱包/约会等全部痕迹；<b>保留</b>你和角色的人设·头像、API设置、主屏布局。清空后无法恢复，建议先导出备份。</div>
    <div style="text-align:center;color:#666;font-size:12px;padding:14px">版本 ${APP_VER}</div>
    <div style="height:20px"></div>
  </div>`;
}
function saveSettings(){const g=id=>$('#'+id).value.trim();
  S.settings.chat={base:g('s_cbase')||'https://vg.v1api.cc/v1',key:g('s_ckey'),model:g('s_cmodel')||'gpt-4o-mini',temp:$('#s_ctemp').value||0.8,maxTokens:$('#s_cmax').value||900};
  S.settings.aux={base:g('s_xbase'),key:g('s_xkey'),model:g('s_xmodel')};
  S.settings.search={mode:(S.settings.search&&S.settings.search.mode)||'jina',base:($('#s_sebase')?$('#s_sebase').value.trim():''),key:($('#s_sekey')?$('#s_sekey').value.trim():''),model:($('#s_semodel')?$('#s_semodel').value.trim():((S.settings.search||{}).model||''))};
  {const ov=S.settings.vision||{};S.settings.vision={base:g('s_vbase')||S.settings.chat.base,key:g('s_vkey')||S.settings.chat.key,model:g('s_vmodel'),fallbackModel:g('s_vfallback'),protocols:ov.protocols||{},lastGoodModel:ov.lastGoodModel||''};}
  const oldTts=S.settings.tts||{},tbase=g('s_tbase'),tkey=g('s_tkey'),explicitTts=oldTts.enabled===true||oldTts.enabled===false;
  S.settings.tts={base:tbase,key:tkey,model:g('s_tmodel'),voice:g('s_tvoice'),group:($('#s_tgroup')?$('#s_tgroup').value.trim():(oldTts.group||'')),enabled:explicitTts?!!oldTts.enabled:!!(tbase&&tkey),relay:!!oldTts.relay};
  S.settings.stt={base:g('s_sbase'),key:g('s_skey'),model:g('s_smodel')};
  if($('#s_imgmodel'))S.settings.imgModel=g('s_imgmodel')||'gpt-image-2';
  if($('#s_ibase'))S.settings.imgBase=g('s_ibase');if($('#s_ikey'))S.settings.imgKey=g('s_ikey');
  S.settings.hist=Math.max(2,Math.min(40,+$('#s_hist').value||12));S.settings.histUnit='rounds';S.settings.replyDelay=$('#s_delay').value||0;S.settings.summaryRounds=+$('#s_sum').value||0;S.settings.proactiveIdleMin=+$('#s_pidle').value||20;S.settings.callProb=Math.max(0,Math.min(100,+$('#s_callprob').value||0));S.settings.callSilentMin=Math.max(0,Math.min(60,parseInt($('#s_callsilent').value,10)||0));save();toast('已保存 ✅');}
// 一键清空所有数据：清掉全部聊天/活动痕迹，但保留 你和角色的人设·头像、API设置、主屏布局
async function clearAllData(){
  if(!await uiConfirm('确定清空所有数据吗？\n\n会清掉：所有聊天、记忆、朋友圈、X/抖音、查手机、线下约会、钱包账单、日历、任务、心情、信箱等全部记录。\n会保留：你和角色的人设·头像、API设置、主屏布局。\n\n清空后无法恢复！建议先「导出备份」。'))return;
  if(!await uiConfirm('最后确认：真的现在清空吗？\n点确定立刻开始，不可撤销。'))return;
  const old=S,fresh=defState();
  fresh.settings=old.settings;// 保留 API 设置
  const m=old.me||{};
  ['name','wxid','avatar','signature','persona','city'].forEach(k=>{if(m[k]!=null)fresh.me[k]=m[k];});// 我的人设·头像
  ['widgets','theme','appLayout','appIcons','momentCover'].forEach(k=>{if(m[k]!=null)fresh.me[k]=m[k];});// 主屏布局/外观
  const KEEP=['id','name','avatar','relation','wxid','signature','persona','city','greeting','msgMin','msgMax','noSticker','gender','callme','selfcall','catchphrase','traits','power','voice','model','taskN','pinned','proactive','chatBg','bubbleStyle'];
  fresh.contacts=(old.contacts||[]).filter(c=>c&&!c.deleted).map(c=>{const n={};KEEP.forEach(k=>{if(c[k]!=null)n[k]=c[k];});if(!n.proactive)n.proactive={enabled:false,start:9,end:23,times:2};return n;});
  fresh.worldbook=old.worldbook||[];// 保留世界书（你写的设定，不是聊天痕迹）
  S=fresh;
  try{imgDel('__messages');}catch(_){}
  save();try{imgGC();}catch(_){}
  try{closeModal();}catch(_){}
  try{home();}catch(_){render();}
  toast('已清空，只留下了人设和头像～');
}
