/* ---------- 世界书 ---------- */
function renderWorldbook(){
  return `<div class="nav"><span class="l" onclick="back()">‹</span><span class="t">世界书</span><span class="r" onclick="editWorld()">＋</span></div>
  <div class="scroll" style="padding:12px;background:#000">
    <div class="hint">世界书 = 给所有角色共享的设定/常识。"常驻"的每次都生效；否则当聊天里出现关键词时才注入。</div>
    ${S.worldbook.length?S.worldbook.map(w=>`<div class="section"><div class="it" onclick="editWorld('${w.id}')">
      <div><div style="font-weight:600">${esc(w.name)} ${w.always?'<span class=tag>常驻</span>':''}${w.contacts&&w.contacts.length?'<span class=tag>'+w.contacts.map(cid=>{const cc=getC(cid);return cc?esc(cc.remark||cc.name):'';}).filter(Boolean).join('/')+'</span>':''}</div>
      <div style="font-size:12px;color:#999;margin-top:3px;max-width:230px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(w.content)}</div></div>
      <span class="sw ${w.enabled?'on':''}" onclick="event.stopPropagation();toggleWorld('${w.id}')"></span></div></div>`).join(''):'<div class="empty">还没有世界书，点右上角 ＋ 添加</div>'}
    <div style="height:20px"></div>
  </div>`;
}
function toggleWorld(id){const w=S.worldbook.find(x=>x.id===id);w.enabled=!w.enabled;save();render();}
function editWorld(id){const w=id?S.worldbook.find(x=>x.id===id):{id:uid(),name:'',keys:'',content:'',enabled:true,always:false,contacts:[],_new:true};
  const wc=w.contacts||[];const cs=S.contacts.filter(c=>!c.deleted);
  openModal(`<h3>${id?'编辑':'新建'}世界书</h3>
    <div class="field"><label>名称</label><input id="w_name" value="${esc(w.name)}" placeholder="比如：世界观/某个地点"></div>
    <div class="field"><label>触发关键词（逗号分隔，常驻可不填）</label><input id="w_keys" value="${esc(w.keys)}" placeholder="苏州,公司"></div>
    <div class="field"><label>内容</label><textarea id="w_content" rows="4">${esc(w.content)}</textarea></div>
    <div class="field"><label class="avline">常驻（每次都生效）<span class="sw ${w.always?'on':''}" id="w_always" onclick="this.classList.toggle('on')"></span></label></div>
    <div class="field"><label>对谁生效（都不选=所有角色共享）</label>
      ${cs.length?cs.map(c=>`<label class="avline" style="font-weight:400">${esc(c.remark||c.name)}<span class="sw ${wc.indexOf(c.id)>=0?'on':''}" data-ct="${c.id}" onclick="this.classList.toggle('on')"></span></label>`).join(''):'<div style="font-size:12px;color:#999">还没有角色</div>'}</div>
    <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="saveWorld('${w.id}',${!!w._new})">保存</button></div>
    ${id?'<button class="btn d" style="margin-top:10px" onclick="delWorld(\''+w.id+'\')">删除</button>':''}`);}
function saveWorld(id,isNew){const contacts=[...document.querySelectorAll('[data-ct].on')].map(e=>e.getAttribute('data-ct'));
  const w={id,name:$('#w_name').value.trim()||'未命名',keys:$('#w_keys').value.trim(),content:$('#w_content').value.trim(),enabled:true,always:$('#w_always').classList.contains('on'),contacts};
  if(isNew)S.worldbook.push(w);else{const i=S.worldbook.findIndex(x=>x.id===id);w.enabled=S.worldbook[i].enabled;S.worldbook[i]=w;}
  save();closeModal();render();}
function delWorld(id){S.worldbook=S.worldbook.filter(x=>x.id!==id);save();closeModal();render();}

