function cleanupOld(){const DAY=86400000,now=Date.now();let ch=false;
  if(S.moments){const n=S.moments.length;S.moments=S.moments.filter(p=>now-(p.time||0)<DAY);if(S.moments.length!==n)ch=true;}
  if(S.x&&S.x.tweets){const n=S.x.tweets.length;S.x.tweets=S.x.tweets.filter(t=>now-(t.time||0)<DAY);if(S.x.tweets.length!==n)ch=true;}
  if(S.x&&S.x.dms){S.x.dms.forEach(d=>{d.msgs=(d.msgs||[]).filter(m=>!m.time||now-m.time<DAY);});const n=S.x.dms.length;S.x.dms=S.x.dms.filter(d=>(d.msgs||[]).length);if(S.x.dms.length!==n)ch=true;}
  (S.me.accounts||[]).forEach(a=>{if(a.bills){const n=a.bills.length;a.bills=a.bills.filter(b=>!b.ts||now-b.ts<DAY);if(a.bills.length!==n)ch=true;}});
  const act=(S.me.accounts||[]).find(a=>a.id===actId());if(act)S.me.bills=act.bills;
  if(S.visitors){const n=S.visitors.length;S.visitors=S.visitors.filter(v=>now-(v.time||0)<DAY);if(S.visitors.length!==n)ch=true;}// 查岗/查看记录一天后自动清
  if(ch){save();const c=cur();if(c&&(c.p==='wechat'||c.p==='x'))render();}}
setInterval(cleanupOld,600000);setTimeout(cleanupOld,5000);
function xUser(name,info){if(!S.x.users[name])S.x.users[name]=Object.assign({name,handle:'@user',avatar:letterAv(name),bio:'',fans:Math.floor(Math.random()*9000),following:Math.floor(Math.random()*500),cid:null},info||{});else if(info)Object.assign(S.x.users[name],info);return S.x.users[name];}
function renderX(){let body;
  if(xTab==='feed')body=xFeed();else if(xTab==='search')body=xSearch();else if(xTab==='dm')body=xDMList();else body=xProfile();
  return `<div class="xnav"><span class="l" onclick="home()">‹</span><span class="t">𝕏</span><span class="r" onclick="xRefresh()">${svgIc('refresh',19,'#fff')}</span></div>
    <div class="xtabs">${xtb('feed','主页')}${xtb('search','搜索')}${xtb('dm','私信')}${xtb('me','我')}</div>
    <div class="xscroll" id="xscroll">${body}</div>
    ${xTab==='feed'?'<div class="xfab" onclick="xFab()">＋</div>':''}`;}
function xFab(){openModal(`<h3>发布</h3>
  <button class="btn p" style="margin-bottom:8px" onclick="closeModal();xCompose()">我发一条推</button>
  <button class="btn g" style="margin-bottom:8px" onclick="closeModal();genContactTweet()">让角色发一条推</button>
  <button class="btn g" onclick="closeModal();genNetTweets('')">刷新网友动态</button>
  <button class="btn g" style="margin-top:8px" onclick="closeModal()">取消</button>`);}
function xtb(k,t){return `<div class="xt ${xTab===k?'on':''}" onclick="xTab='${k}';render()">${t}</div>`;}
let _feedTab='follow';
function xFeed(){let ts=[...S.x.tweets].filter(t=>!S.x.blocked.includes(t.name)).sort((a,b)=>b.time-a.time);
  const isFollow=t=>t.who==='me'||(t.who&&t.who!=='net')||S.x.following.includes(t.name);
  const shown=_feedTab==='follow'?ts.filter(isFollow):ts.filter(t=>!isFollow(t));
  const tabs=`<div class="xtabs" style="flex:0 0 auto"><div class="xt ${_feedTab==='follow'?'on':''}" onclick="_feedTab='follow';render()">关注</div><div class="xt ${_feedTab==='discover'?'on':''}" onclick="_feedTab='discover';render()">发现</div>${_feedTab==='discover'?'<span onclick="clearDiscover()" style="position:absolute;right:12px;line-height:46px;color:#71767b;font-size:12px;cursor:pointer">清空</span>':''}</div>`;
  const body=shown.length?shown.map(tweetCard).join(''):`<div class="empty" style="padding:46px 20px;line-height:2">${_feedTab==='follow'?'关注的人还没发推～<br>点 ＋ 发一条，或「让角色发一条推」':'点右上角刷新看看网友动态'}<br><br>${_feedTab==='follow'?'<button class="xbtn" onclick="genContactTweet()">让角色发一条推</button>':'<button class="xbtn" onclick="genNetTweets(\'\')">刷新网友</button>'}</div>`;
  return tabs+body;}
function tweetCard(t){const liked=(t.likes||[]).includes(S.me.name);const lc=(t.lk||0)+(t.likes||[]).length;
  return `<div class="tweet" onclick="go('xtweet',{id:'${t.id}'})"><span onclick="event.stopPropagation();xAuthor(${jq(t.name)})">${av(t.avatar,'sm')}</span>
    <div class="body"><div class="head"><span class="nm" onclick="event.stopPropagation();xAuthor(${jq(t.name)})">${esc(t.name)}</span><span class="hd">${esc(t.handle||'')} · ${ago(t.time)}</span></div>
    <div class="tx">${esc(t.text)}</div>
    ${t.images&&t.images.length?`<div class="imgs" style="grid-template-columns:repeat(${Math.min(t.images.length,2)},1fr);display:grid;gap:4px;margin:4px 0;border-radius:10px;overflow:hidden">${t.images.map(im=>`<img src="${im}" style="width:100%;border-radius:8px" onclick="event.stopPropagation();viewImg('${im}')">`).join('')}</div>`:''}
    <div class="acts"><span onclick="event.stopPropagation();go('xtweet',{id:'${t.id}'})">${svgIc('chat',15,'currentColor')} ${(t.comments||[]).length}</span>
      <span onclick="event.stopPropagation();xRepost('${t.id}')">${svgIc('refresh',15,'currentColor')} ${t.rt||0}</span>
      <span class="${liked?'liked':''}" onclick="event.stopPropagation();xLike('${t.id}')">${svgIc('heart',15,liked?'#f4245e':'currentColor')} ${lc}</span>
      <span onclick="event.stopPropagation();xUserMenu('${t.id}')">⋯</span></div></div></div>`;}
function xLike(id){const t=tw(id);if(!t)return;t.likes=t.likes||[];const i=t.likes.indexOf(S.me.name);if(i<0){t.likes.push(S.me.name);xlog('在X上点赞了'+t.name+'的推文「'+t.text.slice(0,14)+'」');}else t.likes.splice(i,1);save();render();}
function xRepost(id){const t=tw(id);if(!t)return;t.rt=(t.rt||0)+1;save();render();toast('已转推');}
function xUserMenu(id){const t=tw(id);if(!t)return;const f=S.x.following.includes(t.name),b=S.x.blocked.includes(t.name);
  openModal(`<h3>${esc(t.name)} ${esc(t.handle||'')}</h3>
    <button class="btn g" style="margin-bottom:8px" onclick="closeModal();go('xuser',{name:${jq(t.name)}})">查看主页</button>
    <button class="btn g" style="margin-bottom:8px" onclick="xFollow('${id}')">${f?'✓ 已关注（点击取消）':'+ 关注'}</button>
    <button class="btn g" style="margin-bottom:8px" onclick="fwdTweet('${id}')">↗️ 转发到微信</button>
    <button class="btn d" style="margin-bottom:8px" onclick="xBlock('${id}')">${b?'解除拉黑':'拉黑 '+esc(t.name)}</button>
    <button class="btn d" onclick="S.x.tweets=S.x.tweets.filter(z=>z.id!=='${id}');save();closeModal();render();toast('已删除')">🗑️ 删除这条推文</button>
    <button class="btn g" style="margin-top:8px" onclick="closeModal()">关闭</button>`);}
function xFollow(id){const t=tw(id);xFollowName(t.name);}
function xFollowName(name){const i=S.x.following.indexOf(name);if(i<0){S.x.following.push(name);S.x.profile.following++;xUser(name,{follower:true});}else{S.x.following.splice(i,1);S.x.profile.following=Math.max(0,S.x.profile.following-1);}save();closeModal();render();}
function xBlock(id){const t=tw(id);const i=S.x.blocked.indexOf(t.name);if(i<0)S.x.blocked.push(t.name);else S.x.blocked.splice(i,1);save();closeModal();render();}
function xBlockName(name){const i=S.x.blocked.indexOf(name);if(i<0){S.x.blocked.push(name);const fi=S.x.following.indexOf(name);if(fi>=0){S.x.following.splice(fi,1);S.x.profile.following=Math.max(0,S.x.profile.following-1);}toast('已拉黑 '+name);}else{S.x.blocked.splice(i,1);toast('已解除拉黑');}save();render();}
function xUnfollow(name){const i=S.x.following.indexOf(name);if(i>=0){S.x.following.splice(i,1);S.x.profile.following=Math.max(0,S.x.profile.following-1);save();xFollowingList();}}
function xFollowingList(){const list=S.x.following.slice();
  openModal(`<h3>正在关注（${list.length}）</h3><div style="max-height:60vh;overflow:auto">${list.length?list.map(n=>{const u=xUser(n);return `<div class="section"><div class="it">${av(u.avatar,'sm')}<div class="meta" style="flex:1" onclick="closeModal();go('xuser',{name:${jq(n)}})"><div class="n">${esc(n)}</div><div class="s">${esc(u.handle||u.bio||'')}</div></div><button class="minibtn" onclick="xUnfollow(${jq(n)})">取关</button></div></div>`;}).join(''):'<div class="empty">还没关注谁～去刷推/搜博主关注</div>'}</div><button class="btn g" style="margin-top:8px" onclick="closeModal()">关闭</button>`);}
function fwdTweet(id){const t=tw(id);const cs=S.contacts.filter(c=>!c.deleted);if(!cs.length){toast('先创建角色');return;}
  window._fwT=t;if(cs.length===1)return doFwdTweet(cs[0].id);
  openModal(`<h3>转发到微信</h3>${cs.map(c=>`<div class="section"><div class="it" onclick="doFwdTweet('${c.id}')">${esc(c.remark||c.name)}<span class="v">›</span></div></div>`).join('')}<button class="btn g" style="margin-top:8px" onclick="closeModal()">取消</button>`);}
function doFwdTweet(cid){const t=window._fwT;if(!t)return;pushMsg(cid,{role:'user',type:'tweetcard',tname:t.name,thandle:t.handle||'',ttext:t.text,id:uid()});closeModal();toast('已转发到微信');scheduleReply(cid);}
function xCompose(){window._xcImgs=[];openModal(`<h3>发推</h3><div class="hint">可以 @某个角色名，ta会来互动</div><div class="field"><textarea id="xc_t" rows="4" placeholder="有什么新鲜事？"></textarea></div>
  <div class="field"><button class="minibtn" onclick="addXcImg()">加图片</button> <span id="xc_ic"></span></div>
  <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="doXPost()">发布</button></div>`);}
function addXcImg(){pickFile('image/*',async f=>{window._xcImgs.push(await compress(f,800,.65));$('#xc_ic').textContent='已加'+window._xcImgs.length+'张';});}
function doXPost(){const t=$('#xc_t').value.trim();if(!t&&!(window._xcImgs||[]).length)return;const pop=Math.floor((S.x.profile.fans||0)*(0.02+Math.random()*0.12));const tweet={id:uid(),who:'me',name:S.me.name,handle:S.x.profile.handle,avatar:S.me.avatar,text:t,images:window._xcImgs||[],time:Date.now(),likes:[],lk:pop,comments:[],rt:Math.floor(pop*Math.random()*0.3),views:Math.floor((S.x.profile.fans||0)*(1+Math.random()*4)+50),time:Date.now()};
  S.x.tweets.unshift(tweet);xlog('在X发推：「'+t.slice(0,20)+'」');save();closeModal();render();toast('已发布');reactToTweet(tweet);}
function fanCount(min,max){const f=(S.x.profile.fans||0);return Math.max(min,Math.min(max,Math.round(f/250)+min));}
async function reactToTweet(tweet){
  const n=fanCount(3,9);
  const authorCid=(tweet.who&&tweet.who!=='me'&&tweet.who!=='net')?tweet.who:null;
  const rolePool=tweet.who==='me'?S.contacts.filter(c=>!c.deleted&&!c.blocked).slice(0,1):[];
  for(const c of rolePool){try{const r=await chatAPI([{role:'system',content:buildSystem(c)},{role:'user',content:'"'+tweet.name+'"在X发了条推："'+tweet.text+'"。你是最先刷到的人，以你自己的身份和视角第一个评论一句（口语、像真人留言；别带方括号）。'}],{aux:true});
    tweet.comments.push({name:c.name,avatar:c.avatar,cid:c.id,text:cleanReply(r).slice(0,50)});save();if(cur().p==='x'||cur().p==='xtweet')render();}catch(e){}}
  try{const r=await chatAPI([{role:'system',content:'你是X网友评论生成器。针对"'+tweet.name+'"发的推，生成'+n+'条不同网友的简短评论（吃瓜、调侃、共鸣、抬杠黑子都行；其中1-2条可以@楼上某个网友名跟着接话，形成楼层互动）。每行一条，严格用格式：昵称:::@英文id:::评论内容。不要别的话。'},{role:'user',content:'推文："'+tweet.text+'"'}],{max:900,aux:true});
    looseLines(r).forEach(p=>{const nm=clean(p[0]);if(!nm)return;tweet.comments.push({name:nm,avatar:letterAv(p[1]||nm),text:p[2]||p[1]||''});xUser(nm,{handle:p[1]});});save();if(cur().p==='x'||cur().p==='xtweet')render();}catch(e){}
  // 发帖影响粉丝
  if(tweet.who==='me'){const d=Math.floor(Math.random()*40)-8;S.x.profile.fans=Math.max(0,(S.x.profile.fans||0)+d);save();if(d>0)toast('涨粉 +'+d);else if(d<0)toast('掉粉 '+d);}
  const ats=S.contacts.filter(c=>!c.deleted&&!c.blocked&&c.id!==authorCid&&tweet.text.includes(c.name));
  const pool=tweet.who==='me'?[]:(ats.length?ats:S.contacts.filter(c=>!c.deleted&&!c.blocked&&c.id!==authorCid).slice(0,1));
  for(const c of pool){try{const r=await chatAPI([{role:'system',content:buildSystem(c)},{role:'user',content:'"'+tweet.name+'"在X发了条推："'+tweet.text+'"'+(tweet.text.includes(c.name)?'（@了你）':'')+'。你刷到了，以你自己的身份和视角评论一句（这不是你发的推；口语；别带方括号）。'}],{aux:true});
    tweet.comments.push({name:c.name,avatar:c.avatar,cid:c.id,text:cleanReply(r).slice(0,50)});save();if(cur().p==='x'||cur().p==='xtweet')render();}catch(e){}}}
function genContactTweet(){const cs=S.contacts.filter(c=>!c.deleted);if(!cs.length){toast('先创建角色');return;}
  if(cs.length===1)return doGenContactTweet(cs[0].id);
  openModal(`<h3>谁来发推</h3>${cs.map(c=>`<div class="section"><div class="it" onclick="closeModal();doGenContactTweet('${c.id}')">${esc(c.remark||c.name)}<span class="v">›</span></div></div>`).join('')}<button class="btn g" style="margin-top:8px" onclick="closeModal()">取消</button>`);}
async function doGenContactTweet(cid){const c=getC(cid);aiLoad('正在生成…');
  try{const _co=circleObj(cid);const note=_co.desc?'。你在X的圈子'+(_co.name?'「'+_co.name+'」':'')+'定位是：'+_co.desc+'，推文风格要贴合它':'';
    const txt=await aiGen([{role:'system',content:buildSystem(c)},{role:'user',content:'以你的身份发一条推特(X)'+note+'，一两句，符合你的性格，只输出推文内容，别带方括号。'}],{aux:true},r=>{const t=cleanReply(r);return t&&t.trim()?t:null;});
    if(!txt){toast('生成失败了，再点一次');return;}
    const nm=c.name;xUser(nm,{handle:'@'+c.name.replace(/\s/g,''),avatar:c.avatar,cid:cid,bio:c.signature||''});
    S.x.tweets.unshift({id:uid(),who:cid,name:nm,handle:'@'+c.name.replace(/\s/g,''),avatar:c.avatar,text:txt,time:Date.now(),likes:[],lk:Math.floor(Math.random()*80),comments:[],rt:Math.floor(Math.random()*40)});save();render();
  }finally{aiDone();}}
async function xRefresh(){if(xTab==='dm')return genNetDM();if(xTab==='search')return toast('在搜索框里点搜索按钮');return genNetTweets('');}
async function genNetTweets(topic){aiLoad('正在刷新…');
  try{const rows=await aiGen([{role:'system',content:'你是X(推特)内容生成器，每行一条，严格用格式：昵称:::@英文id:::推文内容。不要序号、不要别的话。'},{role:'user',content:'生成5条不同网友的【原创推文】'+(topic?'，都围绕主题"'+topic+'"（是各自独立发的帖子，不是评论、不是回复别人、不要以@或"回复"开头）':'（日常/搞笑/情感/热点都行）')+'。'}],{max:800,aux:true},looseLines);
    if(!rows){toast('刷新失败了，再点一次刷新');return;}
    const made=[];rows.forEach(p=>{const nm=clean(p[0]);if(!nm)return;xUser(nm,{handle:p[1]});const t={id:uid(),who:'net',name:nm,handle:p[1]||'@user',avatar:letterAv(p[1]||nm),text:p[2]||p[1]||'',time:Date.now()-Math.floor(Math.random()*5400000),likes:[],lk:Math.floor(Math.random()*2000),comments:[],rt:Math.floor(Math.random()*400)};S.x.tweets.unshift(t);made.push(t);});
    save();if(topic)S.x._results=made.map(t=>t.id);render();
  }finally{aiDone();}}
let _xsMode='content';
function xSearch(){const list=(S.x._results||[]).map(id=>tw(id)).filter(Boolean);const bl=S.x._bloggers||[];
  return `<div style="padding:10px 14px;background:#000;border-bottom:.5px solid #2f3336">
    <div style="display:flex;gap:8px;margin-bottom:8px"><span class="xbtn ${_xsMode==='content'?'':'out'}" onclick="_xsMode='content';render()" style="font-size:12px;padding:5px 12px">搜内容</span><span class="xbtn ${_xsMode==='blogger'?'':'out'}" onclick="_xsMode='blogger';render()" style="font-size:12px;padding:5px 12px">搜博主</span></div>
    <div style="display:flex;gap:8px"><input id="xs_q" value="${esc(S.x._q||'')}" placeholder="${_xsMode==='blogger'?'搜你喜欢的博主':'搜内容生成推文'}" style="flex:1;border:1px solid #2f3336;border-radius:18px;padding:8px 14px;background:#16181c;color:#e7e9ea;outline:none" onkeydown="if(event.key==='Enter')xDoSearch($('#xs_q').value)"><button class="xbtn" onclick="xDoSearch($('#xs_q').value)">搜索</button>${(list.length||bl.length)?'<button class="xbtn out" onclick="clearSearch()">清空</button>':''}</div></div>
    ${_xsMode==='blogger'?(bl.length?bl.map(userRow).join(''):'<div class="empty" style="padding:40px">搜索喜欢的博主，可关注/私信/看动态</div>'):(list.length?list.map(tweetCard).join(''):'<div class="empty" style="padding:40px">搜内容，生成相关推文～</div>')}`;}
function xDoSearch(q){q=(q||'').trim();if(!q)return;S.x._q=q;xlog('在X搜索了「'+q+'」');if(_xsMode==='blogger')genBloggers(q);else genNetTweets(q);}
function clearSearch(){const ids=S.x._results||[];S.x.tweets=S.x.tweets.filter(t=>ids.indexOf(t.id)<0);S.x._results=[];S.x._bloggers=[];S.x._q='';save();render();toast('已清空搜索');}
async function clearDiscover(){if(!await uiConfirm('清空发现里的网友推文？'))return;S.x.tweets=S.x.tweets.filter(t=>t.who!=='net');save();render();toast('已清空');}
async function genBloggers(q){aiLoad('正在搜索…');
  try{const rows=await aiGen([{role:'system',content:'你是X博主搜索。根据关键词给出5个相关博主。每行一个，严格用格式：博主名:::@英文id:::一句简介。不要别的话。'},{role:'user',content:'搜索博主：'+q}],{max:600,aux:true},looseLines);
    if(!rows){toast('搜索失败了，再试一次');return;}
    S.x._bloggers=rows.map(p=>{const nm=clean(p[0]);if(!nm)return null;xUser(nm,{handle:p[1],bio:p[2]||'',fans:Math.floor(Math.random()*99999)});return nm;}).filter(Boolean);save();render();
  }finally{aiDone();}}
function userRow(name){const u=S.x.users[name];if(!u)return '';const f=S.x.following.includes(name);
  return `<div class="xdmrow"><span onclick="go('xuser',{name:${jq(name)}})">${av(u.avatar,'sm')}</span><div class="meta" onclick="go('xuser',{name:${jq(name)}})"><div class="n" style="color:#e7e9ea">${esc(name)}</div><div class="s">${esc(u.bio||u.handle||'')}</div></div><button class="xbtn ${f?'out':''}" style="font-size:12px;padding:5px 12px" onclick="xFollowName(${jq(name)})">${f?'已关注':'关注'}</button></div>`;}
/* 用户主页 */
function renderXUser(name){const u=xUser(name);const f=S.x.following.includes(name);const ts=[...S.x.tweets].filter(t=>t.name===name).sort((a,b)=>b.time-a.time);
  return `<div class="xnav"><span class="l" onclick="back()">‹</span><span class="t">${esc(name)}</span><span class="r" onclick="genUserTweet(${jq(name)})">${svgIc('refresh',19,'#fff')}</span></div>
    <div class="xscroll"><div class="xprofh" style="${u.cover?'background:url('+u.cover+') center/cover':''}" onclick="changeUserCover(${jq(name)})"></div>
      <div style="padding:0 14px"><div style="margin-top:-30px">${av(u.avatar,'lg')}</div>
        <div style="font-size:19px;font-weight:700;color:#e7e9ea;margin-top:8px">${esc(name)}</div>
        <div style="color:#71767b;font-size:14px">${esc(u.handle||'')}</div>
        <div style="color:#e7e9ea;font-size:14px;margin:8px 0">${esc(u.bio||'')}</div>
        <div style="color:#71767b;font-size:14px"><b style="color:#e7e9ea">${u.following||0}</b> 关注　<b style="color:#e7e9ea">${u.fans||0}</b> 粉丝</div>
        <div style="display:flex;gap:8px;margin:12px 0;flex-wrap:wrap"><button class="xbtn ${f?'out':''}" onclick="xFollowName(${jq(name)})">${f?'已关注':'+ 关注'}</button>
          <button class="xbtn out" onclick="openDMWith(${jq(name)})">私信</button>
          <button class="xbtn out" onclick="editUserProfile(${jq(name)})">改资料</button>
          <button class="xbtn out" style="${S.x.blocked.includes(name)?'color:#1d9bf0':'color:#f4212e'}" onclick="xBlockName(${jq(name)})">${S.x.blocked.includes(name)?'解除拉黑':'拉黑'}</button></div></div>
      <div style="border-bottom:.5px solid #2f3336;color:#e7e9ea;padding:8px 14px;font-weight:700">推文</div>
      ${ts.length?ts.map(tweetCard).join(''):'<div class="empty" style="padding:30px">还没有推文，点右上角刷新生成一条ta的动态</div>'}</div>`;}
async function genUserTweet(name){const u=xUser(name);aiLoad('正在生成…');
  try{const isC=u.cid&&getC(u.cid);const _msgs=isC?[{role:'system',content:buildSystem(getC(u.cid))},{role:'user',content:'以你的身份发一条推特，一两句，别带方括号。'}]:[{role:'system',content:'你是X博主「'+name+'」'+(u.bio?'（'+u.bio+'）':'')+'，发一条符合你人设的推文，一两句。只输出推文内容。'}];
    const txt=await aiGen(_msgs,isC?{aux:true}:{max:200,aux:true},r=>{const t=cleanReply(r);return t&&t.trim()?t:null;});
    if(!txt){toast('生成失败了，再点一次');return;}
    S.x.tweets.unshift({id:uid(),who:u.cid||'net',name:name,handle:u.handle||'@user',avatar:u.avatar,text:txt,time:Date.now(),likes:[],lk:Math.floor(Math.random()*500),comments:[],rt:Math.floor(Math.random()*100)});save();render();
  }finally{aiDone();}}
function editUserProfile(name){const u=xUser(name);openModal(`<h3>编辑 ${esc(name)} 的资料</h3>
  <div class="field"><label>handle</label><input id="up_h" value="${esc(u.handle||'')}"></div>
  <div class="field"><label>简介</label><input id="up_b" value="${esc(u.bio||'')}"></div>
  <div class="two"><div class="field"><label>粉丝</label><input id="up_f" type="number" value="${u.fans||0}"></div><div class="field"><label>关注</label><input id="up_g" type="number" value="${u.following||0}"></div></div>
  <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="(function(){var u=xUser(${jq(name)});u.handle=$('#up_h').value.trim();u.bio=$('#up_b').value.trim();u.fans=+$('#up_f').value||0;u.following=+$('#up_g').value||0;save();closeModal();render();})()">保存</button></div>`);}
function openDMWith(name){const u=xUser(name);let d=S.x.dms.find(x=>x.name===name);if(!d){d={id:uid(),name,avatar:u.avatar,cid:u.cid||null,msgs:[]};S.x.dms.unshift(d);save();}go('xdm',{id:d.id});}
function changeUserCover(name){pickFile('image/*',async f=>{xUser(name).cover=await compress(f,900,.6);save();render();toast('背景已换');});}
/* 推文详情 */
function renderXTweet(id){const t=tw(id);if(!t)return '';
  return `<div class="xnav"><span class="l" onclick="back()">‹</span><span class="t">推文</span><span class="r" onclick="xRefreshComments('${id}')">${svgIc('refresh',19,'#fff')}</span></div>
    <div class="xscroll">
      <div style="padding:14px;border-bottom:.5px solid #2f3336"><div style="display:flex;gap:10px;align-items:center" onclick="xAuthor(${jq(t.name)})">${av(t.avatar,'sm')}<div><div class="nm" style="color:#e7e9ea;font-weight:700">${esc(t.name)}</div><div class="hd" style="font-size:13px;color:#71767b">${esc(t.handle||'')}</div></div></div>
        <div class="tx" style="color:#e7e9ea;font-size:18px;margin:10px 0;white-space:pre-wrap">${esc(t.text)}</div>
        ${t.images&&t.images.length?`<div style="display:grid;grid-template-columns:repeat(${Math.min(t.images.length,2)},1fr);gap:4px;margin:6px 0">${t.images.map(im=>`<img src="${im}" style="width:100%;border-radius:10px" onclick="viewImg('${im}')">`).join('')}</div>`:''}
        <div style="color:#71767b;font-size:13px">${new Date(t.time).toLocaleString('zh-CN')}</div>
        <div class="acts" style="margin-top:8px;color:#71767b"><span>${svgIc('refresh',14,'currentColor')} ${t.rt||0}</span><span class="${(t.likes||[]).includes(S.me.name)?'liked':''}" onclick="xLike('${id}')">${svgIc('heart',14,(t.likes||[]).includes(S.me.name)?'#f4245e':'currentColor')} ${(t.lk||0)+(t.likes||[]).length}</span></div></div>
      ${(t.comments||[]).map((cm,ci)=>`<div class="xcomment">${av(cm.avatar||'','sm')}<div style="flex:1"><div class="nm" style="font-size:13px;color:#e7e9ea;font-weight:700">${esc(cm.name)} ${cm.authorLiked?'<span style="color:#f91880;font-weight:400">· 作者赞过</span>':''}</div><div class="tx">${esc(cm.text)}</div><div style="font-size:12px;margin-top:3px"><span style="color:#1d9bf0;cursor:pointer" onclick="xReplyComment('${id}',${ci})">回复</span> <span style="color:#71767b;cursor:pointer;margin-left:10px" onclick="xAuthorLike('${id}',${ci})">${cm.authorLiked?'取消赞':'作者赞'}</span></div></div></div>`).join('')||'<div class="empty" style="padding:24px">还没有评论，点右上角刷新生成网友评论</div>'}
      <div style="height:70px"></div></div>
    <div class="inputbar"><textarea id="xc_in" rows="1" placeholder="发布你的回复…可@角色"></textarea><button class="send" onclick="xComment('${id}')">回复</button></div>`;}
function xAuthorLike(id,ci){const t=tw(id);t.comments[ci].authorLiked=!t.comments[ci].authorLiked;save();render();}
async function xRefreshComments(id){const t=tw(id);if(!t)return;aiLoad('正在生成评论…');const n=fanCount(4,9);
  const existing=(t.comments||[]).slice(-6).map(c=>c.name+'说"'+c.text+'"').join('；');
  try{const rows=await aiGen([{role:'system',content:'你是X评论区生成器。针对"'+t.name+'"的这条推，生成'+n+'条不同网友评论（吃瓜、共鸣、抬杠黑子都可；让其中1-2条@楼上某位接话，形成楼层互动）。'+(existing?'已有评论：'+existing+'，新评论可以接着这些聊。':'')+'每行一条，严格用格式：昵称:::@英文id:::评论内容。不要别的话。'},{role:'user',content:'推文："'+t.text+'"'}],{max:900,aux:true},looseLines);
    if(!rows){toast('生成失败了，再试一次');return;}
    rows.forEach(p=>{const nm=clean(p[0]);if(!nm)return;t.comments.push({name:nm,avatar:letterAv(p[1]||nm),text:p[2]||p[1]||''});xUser(nm,{handle:p[1]});});save();render();
  }finally{aiDone();}}
function xComment(id){const t=tw(id);const inp=$('#xc_in');const v=inp?inp.value.trim():'';if(!v)return;
  t.comments.push({name:S.me.name,avatar:S.me.avatar,text:v});xlog('在X评论了'+t.name+'的推文：「'+v.slice(0,16)+'」');save();render();
  // @到的角色或推文作者(若为角色)来回复
  const ats=S.contacts.filter(c=>!c.deleted&&!c.blocked&&v.includes(c.name));
  const author=t.who&&t.who!=='me'&&t.who!=='net'?getC(t.who):null;
  const targets=ats.length?ats:(author?[author]:[]);
  targets.forEach(c=>xCommentReply(t,c,v));}
async function xCommentReply(t,c,v){try{const r=await chatAPI([{role:'system',content:buildSystem(c)},{role:'user',content:S.me.name+'在X推文"'+t.text+'"下评论了你/或@了你："'+v+'"，回ta一句（口语，别带方括号）。'}],{aux:true});
  t.comments.push({name:c.remark||c.name,avatar:c.avatar,cid:c.id,text:cleanReply(r).slice(0,50)});save();if(cur().p==='xtweet')render();}catch(e){}}
function xReplyComment(id,ci){const t=tw(id);const cm=t.comments[ci];openModal(`<h3>回复 ${esc(cm.name)}</h3><div class="field"><input id="xrc" placeholder="回复 ${esc(cm.name)}…"></div>
  <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="doXReply('${id}',${ci})">回复</button></div>`);}
function doXReply(id,ci){const v=$('#xrc').value.trim();if(!v)return;const t=tw(id);const cm=t.comments[ci];
  t.comments.push({name:S.me.name,avatar:S.me.avatar,text:'回复 '+cm.name+'：'+v});save();closeModal();render();
  if(cm.cid&&getC(cm.cid))xCommentReply(t,getC(cm.cid),v);}
/* 私信 */
function xDMList(){const ds=S.x.dms||[];
  return `<div style="padding:8px 14px;text-align:right;background:#000;border-bottom:.5px solid #2f3336"><span style="float:left;color:#71767b;font-size:12px;line-height:30px">粉丝${S.x.profile.fans}·私信随粉丝量</span><button class="xbtn out" onclick="genNetDM()">＋ 刷新私信</button></div>
    ${ds.length?ds.map(d=>{const last=d.msgs[d.msgs.length-1];return `<div class="xdmrow"><span onclick="go('xdm',{id:'${d.id}'})">${av(d.avatar,'sm')}</span><div class="meta" onclick="go('xdm',{id:'${d.id}'})"><div class="n" style="color:#e7e9ea">${esc(d.name)}</div><div class="s">${last?esc((last.from==='me'?'我：':'')+last.text):''}</div></div><span onclick="S.x.dms=S.x.dms.filter(z=>z.id!=='${d.id}');save();render()" style="color:#fa5151;cursor:pointer;padding:0 6px">✕</span></div>`;}).join(''):'<div class="empty" style="padding:40px">还没有私信，点上面生成一条网友私信，或在推文里和人互动</div>'}`;}
async function genNetDM(){aiLoad('正在刷新私信…');const recent=S.x.tweets.filter(t=>t.who==='me').slice(0,2).map(t=>t.text).join('；');const n=fanCount(1,4);
  try{const rows=await aiGen([{role:'system',content:'你生成X网友私信。每行一条，严格用格式：网友名:::@英文id:::私信内容。不要别的话。'},{role:'user',content:'生成'+n+'个不同网友给"'+S.me.name+'"发来的私信开场。类型要杂（暧昧搭讪/真诚粉丝/抬杠黑子/合作邀约/普通网友），但别太多太杂。'+(recent?'结合ta最近发的推："'+recent+'"。':'')}],{max:500,aux:true},looseLines);
    if(!rows){toast('生成失败了，再试一次');return;}
    rows.forEach(p=>{const nm=clean(p[0]);if(!nm)return;xUser(nm,{handle:p[1]});S.x.dms.unshift({id:uid(),name:nm,avatar:letterAv(p[1]||nm),msgs:[{from:'them',text:p[2]||p[1]||'在吗',time:Date.now()}]});});save();render();
  }finally{aiDone();}}
function renderXDM(id){const d=S.x.dms.find(x=>x.id===id);if(!d)return '';
  return `<div class="xnav"><span class="l" onclick="back()">‹</span><span class="t">${esc(d.name)}</span><span class="r"></span></div>
    <div class="xscroll" id="xdmbox" style="padding:10px 14px">${d.msgs.map(m=>`<div class="xmsg ${m.from==='me'?'me':''}"><div class="xmwrap"><div class="b">${esc(m.text)}</div><div class="xmt">${m.time?hm(m.time):''}</div></div></div>`).join('')}</div>
    <div class="inputbar"><textarea id="xdm_in" rows="1" placeholder="发私信…"></textarea><button class="send" onclick="xSendDM('${id}')">发送</button></div>`;}
function xSendDM(id){const d=S.x.dms.find(x=>x.id===id);const inp=$('#xdm_in');const v=inp?inp.value.trim():'';if(!v)return;
  d.msgs.push({from:'me',text:v,time:Date.now()});xlog(hm()+'回复了网友'+d.name+'的私信：「'+v.slice(0,18)+'」');save();render();xDMReply(d);}
async function xDMReply(d){try{const c=d.cid?getC(d.cid):null;const sys=c?buildSystem(c):'你是X网友「'+d.name+'」，和'+S.me.name+'私信聊天，口语、简短、有个性。';
  const hist=d.msgs.slice(-10).map(m=>({role:m.from==='me'?'user':'assistant',content:m.text}));
  const r=await chatAPI([{role:'system',content:sys},...hist],{max:200,aux:true});
  d.msgs.push({from:'them',text:cleanReply(r),time:Date.now()});save();if(cur().p==='xdm')render();}catch(e){}}
/* 我的主页 */
function xProfile(){const p=S.x.profile;
  return `<div class="xprofh" style="${p.cover?'background:url('+p.cover+') center/cover':''}" onclick="changeXCover()"></div>
    <div style="padding:0 14px"><div style="margin-top:-30px;display:flex;justify-content:space-between;align-items:flex-end">${av(S.me.avatar,'lg')}<button class="xbtn out" onclick="editXProfile()">编辑资料</button></div>
      <div style="font-size:19px;font-weight:700;color:#e7e9ea;margin-top:8px">${esc(S.me.name)}</div>
      <div style="color:#71767b;font-size:14px">${esc(p.handle)}</div>
      <div style="color:#e7e9ea;font-size:14px;margin:8px 0">${esc(p.bio||'')}</div>
      <div style="color:#71767b;font-size:14px"><span onclick="xFollowingList()" style="cursor:pointer"><b style="color:#e7e9ea">${p.following}</b> <span style="text-decoration:underline">正在关注 ›</span></span>　<b style="color:#e7e9ea">${p.fans}</b> 关注者</div>
    </div>
    <div style="border-bottom:.5px solid #2f3336;margin:10px 0;color:#e7e9ea;padding:8px 14px;font-weight:700">我的推文</div>
    ${[...S.x.tweets].filter(t=>t.who==='me').sort((a,b)=>b.time-a.time).map(tweetCard).join('')||'<div class="empty" style="padding:30px">还没发过推</div>'}`;}
function editXProfile(){const p=S.x.profile;openModal(`<h3>编辑 X 资料</h3>
  <div class="field"><label>用户名 handle</label><input id="xp_h" value="${esc(p.handle)}"></div>
  <div class="field"><label>简介</label><input id="xp_b" value="${esc(p.bio||'')}"></div>
  <div class="two"><div class="field"><label>粉丝数</label><input id="xp_f" type="number" value="${p.fans}"></div><div class="field"><label>关注数</label><input id="xp_g" type="number" value="${p.following}"></div></div>
  <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="(function(){S.x.profile.handle=$('#xp_h').value.trim()||'@me';S.x.profile.bio=$('#xp_b').value.trim();S.x.profile.fans=+$('#xp_f').value||0;S.x.profile.following=+$('#xp_g').value||0;save();closeModal();render();})()">保存</button></div>`);}
function changeXCover(){pickFile('image/*',async f=>{S.x.profile.cover=await compress(f,900,.6);save();render();toast('背景已换');});}

/* ---------- 抖音 ---------- */
const DY_GRADS=['linear-gradient(135deg,#fe2c55,#7c1f3a)','linear-gradient(135deg,#25f4ee,#0b6b67)','linear-gradient(135deg,#845ef7,#2b1a5e)','linear-gradient(135deg,#ff922b,#7a3d05)','linear-gradient(135deg,#20c997,#0a4d3a)','linear-gradient(135deg,#f06595,#5e1a3a)','linear-gradient(135deg,#4dabf7,#103a5e)','linear-gradient(135deg,#ffd43b,#7a6308)'];
let dyTab='feed';let _dyMode='rec';let _dyNarr={};let _dyPaused={};
function dyNick(){return S.dy.profile.nick||S.me.name;}
function dyAvatar(){return S.dy.profile.avatar||S.me.avatar;}
function openDouyin(){dyTab='feed';go('dy');if(!S.dy.feed.length)dyGenFeed('',true);}
function dyVid(id){return S.dy.feed.find(v=>v.id===id)||S.dy.liked.find(v=>v.id===id)||(S.dy.mine||[]).find(v=>v.id===id);}
function dyModalOpen(){const m=$('#modal');return m&&m.classList.contains('show');}
function renderDouyin(){let body;
  if(dyTab==='feed')body=dyFeedView();else if(dyTab==='search')body=dySearchView();else if(dyTab==='dm')body=dyDMList();else body=dyProfile();
  const nav=dyTab==='feed'?'':`<div class="dynav"><span class="l" onclick="home()" style="cursor:pointer">‹</span><span style="font-weight:700">${dyTab==='search'?'搜索':dyTab==='dm'?'消息':'我'}</span><span class="r" style="width:14px"></span></div>`;
  return `${nav}<div style="flex:1;overflow:hidden;display:flex;flex-direction:column;position:relative">${body}${dyTab==='feed'?'<div class="xfab" style="bottom:60px;background:#fe2c55" onclick="dyCompose()">＋</div>':''}</div>
    <div class="dytab">${dytb('feed',svgIc('home',22),'首页')}${dytb('search',svgIc('search',22),'搜索')}${dytb('dm',svgIc('envelope',22),'消息')}${dytb('me',svgIc('user',22),'我')}</div>`;}
function dytb(k,i,t){return `<div class="t ${dyTab===k?'on':''}" onclick="dyTab='${k}';render()"><div class="i">${i}</div>${t}</div>`;}
function dyFeedView(){const list=_dyMode==='follow'?S.dy.feed.filter(v=>v.cid&&v.cid!=='me'&&S.dy.following.includes(v.cid)):S.dy.feed;
  const top=`<div style="position:absolute;top:8px;left:10px;z-index:7;color:#fff;font-size:22px;cursor:pointer;text-shadow:0 1px 4px rgba(0,0,0,.6)" onclick="home()">‹</div><div class="dytopt"><span class="${_dyMode==='follow'?'on':''}" onclick="_dyMode='follow';render()">关注</span><span class="${_dyMode==='rec'?'on':''}" onclick="_dyMode='rec';render()">推荐</span></div>`;
  if(!list.length){return `<div style="position:relative;flex:1;background:#000;color:#888;display:flex;align-items:center;justify-content:center;text-align:center;line-height:2;padding:20px">${top}${_dyMode==='follow'?'关注的人还没发视频～<br>去「我的关注」添加角色的抖音<br><br><button class="dybtn out" onclick="dyFollowList()">我的关注</button>':'还没有视频<br><button class="dybtn" onclick="dyGenFeed(\'\',true)">刷新推荐</button>'}</div>`;}
  const more=_dyMode==='rec'?`<div class="dyvideo" style="background:#000;color:#888;align-items:center;justify-content:center"><div style="text-align:center"><button class="dybtn" onclick="dyGenFeed('',false)">刷新更多</button></div></div>`:'';
  return `<div class="dyfeed" id="dyfeed">${top}${list.map(dyVideoCard).join('')}${more}</div>`;}
function dyVideoCard(v,i){const liked=!!v.liked;const lc=(v.lk||0)+(liked?1:0);const grad=v.grad||DY_GRADS[i%DY_GRADS.length];const paused=_dyPaused[v.id];
  const isChar=v.cid&&v.cid!=='me';const mine=v.cid==='me';const fol=isChar&&S.dy.following.includes(v.cid);
  return `<div class="dyvideo${paused?' paused':''}">
    <div class="dybg" style="background-image:${grad}"></div>
    <div class="dyemoji">${v.emoji||'🎬'}</div>
    <div class="dyplay">▶︎</div>
    <div onclick="dyTapVideo('${v.id}')" style="position:absolute;inset:0;z-index:2"></div>
    <div class="dyrail">
      <div class="ra" onclick="dyVideoAuthor('${v.id}')" style="margin-bottom:4px"><div style="position:relative">${av(v.avatar||'🎵','sm')}${isChar&&!fol?'<span style="position:absolute;bottom:-7px;left:50%;transform:translateX(-50%);width:18px;height:18px;border-radius:50%;background:#fe2c55;color:#fff;font-size:13px;line-height:18px;text-align:center">+</span>':''}</div></div>
      <div class="ra" onclick="dyLike('${v.id}')"><span class="ic">${svgIc('heart',26,liked?'#fe2c55':'#fff')}</span>${lc}</div>
      <div class="ra" onclick="dyComments('${v.id}')"><span class="ic">${svgIc('chat',26,'#fff')}</span>${(v.comments||[]).length}</div>
      <div class="ra" onclick="dyTapVideo('${v.id}')"><span class="ic">${svgIc('book',26,'#fff')}</span>简介</div>
      <div class="ra" onclick="dyFwd('${v.id}')"><span class="ic">${svgIc('forward',26,'#fff')}</span>转发</div>
      <div class="ra" style="margin-top:2px"><div class="dydisc">🎵</div></div>
    </div>
    <div class="dymeta">
      <div style="font-weight:700;font-size:16px;margin-bottom:5px;cursor:pointer" onclick="dyAuthorMenu('${v.id}')">@${esc(mine?dyNick():(v.author||'用户'))}${isChar?'<span style="font-size:11px;background:#fe2c55;border-radius:4px;padding:1px 5px;margin-left:6px">角色</span>':mine?'<span style="font-size:11px;background:#555;border-radius:4px;padding:1px 5px;margin-left:6px">我</span>':''} <span style="font-size:12px;opacity:.7">⌄</span></div>
      <div style="font-size:14px;line-height:1.5">${esc(v.desc||'')}</div>
      <div style="font-size:12px;color:#ddd;margin-top:6px">🎵 ${esc(v.music||'原创音乐')}</div>
    </div>
    <div class="dynarr" id="narr_${v.id}" onclick="dyTapVideo('${v.id}')" style="display:${_dyNarr[v.id]?'block':'none'}"><div style="font-weight:700;color:#fe2c55;margin-bottom:6px">📖 视频内容 · 旁白</div>${esc(v.narration||v.desc||'（这条还没有旁白描写）')}<div style="text-align:center;color:#777;margin-top:10px;font-size:12px">点这里收起</div></div></div>`;}
// 不整页重渲染，避免竖向 feed 滚动位置被重置
function dyTapVideo(id){const el=document.getElementById('narr_'+id);if(!el)return;const show=el.style.display==='none';el.style.display=show?'block':'none';_dyNarr[id]=show;}
function dyKeepScroll(fn){const f=$('#dyfeed');const st=f?f.scrollTop:0;fn();render();const g=$('#dyfeed');if(g)g.scrollTop=st;}
function dyVideoAuthor(id){const v=dyVid(id);if(!v)return;if(!(v.cid&&v.cid!=='me'))return toast('这是网友视频，点名字可以私信TA');
  if(!S.dy.following.includes(v.cid)){S.dy.following.push(v.cid);save();toast('已关注 @'+v.author);dyKeepScroll(()=>{});}}
function dyAuthorMenu(id){const v=dyVid(id);if(!v)return;const isChar=v.cid&&v.cid!=='me';const mine=v.cid==='me';const fol=isChar&&S.dy.following.includes(v.cid);
  openModal(`<h3>@${esc(mine?dyNick():v.author)}</h3>
    ${!mine?`<button class="btn g" style="margin-bottom:8px" onclick="dyDMAuthor('${id}')">私信${isChar?'TA':'博主'}</button>`:''}
    ${isChar?`<button class="btn g" style="margin-bottom:8px" onclick="closeModal();dyToggleFollow('${v.cid}')">${fol?'取消关注':'+ 关注'}</button>`:''}
    <button class="btn d" style="margin-bottom:8px" onclick="dyDelVideo('${id}')">删除这条视频</button>
    <button class="btn g" onclick="closeModal()">关闭</button>`);}
function dyToggleFollow(cid){const i=S.dy.following.indexOf(cid);if(i<0)S.dy.following.push(cid);else S.dy.following.splice(i,1);save();render();toast(i<0?'已关注':'已取关');}
async function dyDelVideo(id){if(!await uiConfirm('删除这条视频？'))return;S.dy.feed=S.dy.feed.filter(v=>v.id!==id);S.dy.liked=S.dy.liked.filter(v=>v.id!==id);S.dy.mine=(S.dy.mine||[]).filter(v=>v.id!==id);closeModal();render();toast('已删除');}
function dyDMAuthor(id){const v=dyVid(id);if(!v)return;closeModal();openDyDMName(v.author,(v.cid&&v.cid!=='me')?v.cid:null,v.avatar);}
function dyLike(id){const v=dyVid(id);if(!v)return;v.liked=!v.liked;
  if(v.liked){if(!S.dy.liked.find(x=>x.id===v.id))S.dy.liked.unshift(Object.assign({},v));}
  else S.dy.liked=S.dy.liked.filter(x=>x.id!==v.id);
  const fv=S.dy.feed.find(x=>x.id===id);if(fv)fv.liked=v.liked;
  const lv=S.dy.liked.find(x=>x.id===id);if(lv)lv.liked=v.liked;
  if(cur().p==='dy'&&dyTab==='feed')dyKeepScroll(save);else{save();render();}}
async function dyGenFeed(topic,replace){aiLoad('正在加载视频…');
  try{const arr=await aiGen([{role:'system',content:'你是抖音短视频内容生成器。生成5条不同的短视频信息，类型要杂（搞笑/萌宠/美食/风景/舞蹈/剧情/知识/情感都行）。只输出JSON数组，不要解释：[{"author":"博主昵称","handle":"@英文id","desc":"视频文案/标题(一句，可带#话题)","narration":"旁白：详细描写这条视频里到底是什么画面、发生了什么(2-4句，像在跟人讲这视频拍了啥)","music":"背景音乐名","emoji":"一个最能代表画面的emoji"}]'},{role:'user',content:topic?('围绕「'+topic+'」生成相关的短视频。'):'生成一批热门推荐短视频。'}],{max:1100,aux:true},parseArr);
    if(!arr||!Array.isArray(arr)||!arr.length){toast('加载失败了，再点一次');return;}
    const vids=arr.map((o,i)=>({id:uid(),author:clean(o.author)||'用户'+(10+Math.floor(Math.random()*89)),handle:o.handle||'@user',avatar:'🎵',cid:null,desc:o.desc||'',narration:o.narration||'',music:o.music||'原创音乐',emoji:(o.emoji||'🎬').slice(0,2),grad:DY_GRADS[Math.floor(Math.random()*DY_GRADS.length)],lk:Math.floor(Math.random()*90000),comments:[],ts:Date.now()}));
    if(replace)S.dy.feed=vids;else S.dy.feed=S.dy.feed.concat(vids);
    if(S.dy.feed.length>40)S.dy.feed=S.dy.feed.slice(-40);
    save();if(cur().p==='dy')render();const f=$('#dyfeed');if(replace&&f)f.scrollTop=0;
  }finally{aiDone();}}
function dySearchView(){const h=S.dy.history||[];
  return `<div style="padding:12px 14px;background:#000"><div style="display:flex;gap:8px"><input id="dy_q" placeholder="搜你想看的视频…" style="flex:1;border:none;border-radius:18px;padding:9px 14px;background:#1c1c1e;color:#eee;outline:none" onkeydown="if(event.key==='Enter')dyDoSearch($('#dy_q').value)"><button class="dybtn" onclick="dyDoSearch($('#dy_q').value)">搜索</button></div></div>
    <div style="flex:1;overflow-y:auto;background:#000;padding:14px">
      ${h.length?`<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><span style="color:#888;font-size:13px">搜索记录</span><span onclick="dyClearHistory()" style="color:#fe2c55;font-size:13px;cursor:pointer">🗑 清空</span></div>
      <div>${h.map((q,i)=>`<span class="dychip"><span onclick="dyDoSearch(${jq(q)})">${esc(q)}</span><span onclick="dyDelHistory(${i})" style="color:#666;margin-left:2px">✕</span></span>`).join('')}</div>`:'<div class="empty" style="padding:30px;color:#888">搜你想看的，比如「猫咪」「美食教程」「治愈风景」</div>'}
    </div>`;}
function dyDoSearch(q){q=(q||'').trim();if(!q)return;S.dy.history=S.dy.history||[];S.dy.history=S.dy.history.filter(x=>x!==q);S.dy.history.unshift(q);if(S.dy.history.length>20)S.dy.history=S.dy.history.slice(0,20);save();dyTab='feed';_dyMode='rec';dyGenFeed(q,true);}
async function dyClearHistory(){if(!await uiConfirm('清空全部搜索记录？'))return;S.dy.history=[];save();render();toast('已清空搜索记录');}
function dyDelHistory(i){S.dy.history.splice(i,1);save();render();}
function dyFwd(id){const v=dyVid(id);if(!v)return;const cs=S.contacts.filter(c=>!c.deleted);if(!cs.length){toast('先创建角色');return;}
  window._fwDy=v;if(cs.length===1)return doDyFwd(cs[0].id);
  openModal(`<h3>把视频转发给</h3>${cs.map(c=>`<div class="section"><div class="it" onclick="doDyFwd('${c.id}')">${esc(c.remark||c.name)}<span class="v">›</span></div></div>`).join('')}<button class="btn g" style="margin-top:8px" onclick="closeModal()">取消</button>`);}
function doDyFwd(cid){const v=window._fwDy;if(!v)return;pushMsg(cid,{role:'user',type:'dycard',author:v.cid==='me'?dyNick():v.author,desc:v.desc,narration:v.narration,emoji:v.emoji,mine:v.cid==='me',id:uid()});closeModal();toast('已转发到微信');scheduleReply(cid);}
/* 发抖音 */
function dyCompose(){openModal(`<h3>发抖音</h3>
  <div class="field"><label>文案 / 标题</label><input id="dyc_desc" placeholder="记录此刻…可带 #话题"></div>
  <div class="field"><label>画面旁白（这条视频拍了啥）</label><textarea id="dyc_narr" rows="2" placeholder="比如：在江边跳了段舞，夕阳特别美"></textarea></div>
  <div class="two"><div class="field"><label>封面 emoji</label><input id="dyc_emoji" value="🎬" maxlength="4"></div><div class="field"><label>配乐</label><input id="dyc_music" placeholder="原创音乐"></div></div>
  <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="doDyPost()">发布</button></div>`);}
function doDyPost(){const desc=($('#dyc_desc').value||'').trim();const narr=($('#dyc_narr').value||'').trim();if(!desc&&!narr){toast('写点东西吧');return;}
  const v={id:uid(),author:dyNick(),handle:'@'+dyNick().replace(/\s/g,''),avatar:dyAvatar(),cid:'me',desc,narration:narr,music:($('#dyc_music').value||'').trim()||'原创音乐',emoji:(($('#dyc_emoji').value||'🎬').trim()||'🎬').slice(0,4),grad:DY_GRADS[Math.floor(Math.random()*DY_GRADS.length)],lk:Math.floor(Math.random()*60),comments:[],ts:Date.now()};
  S.dy.feed.unshift(v);S.dy.mine=S.dy.mine||[];S.dy.mine.unshift(v);save();closeModal();dyTab='feed';_dyMode='rec';render();const f=$('#dyfeed');if(f)f.scrollTop=0;toast('已发布 🎬');
  dyGenCommentsCore(v,{net:3,chars:2,mine:true}).then(()=>{if(cur().p==='dy')dyKeepScroll(()=>{});});}
/* 评论 */
function dyComments(id){const v=dyVid(id);if(!v)return;v.comments=v.comments||[];
  openModal(`<h3>评论（${v.comments.length}）</h3>
    <div style="max-height:48vh;overflow:auto">${v.comments.length?v.comments.map((cm,ci)=>`<div style="display:flex;gap:8px;padding:8px 2px;border-bottom:.5px solid #eee">${av(cm.avatar||'💬','sm')}<div style="flex:1"><div style="font-size:13px;font-weight:600">${esc(cm.name)}${cm.cid?' <span style="color:#fe2c55;font-weight:400">·角色</span>':cm.me?' <span style="color:#888;font-weight:400">·我</span>':''}</div><div style="font-size:13px;color:#444;margin-top:2px">${esc(cm.text)}</div></div><span onclick="dyDelComment('${id}',${ci})" style="color:#ccc;cursor:pointer;padding:0 4px">✕</span></div>`).join(''):'<div class="empty" style="padding:20px">还没有评论，点下面生成网友评论，或自己评一条</div>'}</div>
    <div class="field" style="margin-top:10px"><input id="dycm_in" placeholder="写评论…可 @角色名"></div>
    <div class="btns"><button class="dybtn out" onclick="dyGenComments('${id}')">生成网友评论</button><button class="btn p" onclick="dyPostComment('${id}')">发评论</button></div>
    <button class="btn g" style="margin-top:8px" onclick="closeModal()">关闭</button>`);}
function dyDelComment(id,ci){const v=dyVid(id);if(!v||!v.comments)return;v.comments.splice(ci,1);save();dyComments(id);}
function dyPostComment(id){const v=dyVid(id);if(!v)return;const inp=$('#dycm_in');const t=inp?inp.value.trim():'';if(!t)return;v.comments=v.comments||[];
  v.comments.push({name:dyNick(),avatar:dyAvatar(),me:true,text:t});save();
  // @到的角色 / 自己视频则关注的角色 来回话
  const ats=S.contacts.filter(c=>!c.deleted&&!c.blocked&&t.includes(c.name));
  ats.slice(0,2).forEach(c=>dyCharReplyComment(v,c,t));
  dyComments(id);}
async function dyCharReplyComment(v,c,t){try{const r=await chatAPI([{role:'system',content:buildSystem(c)},{role:'user',content:S.me.name+'在抖音视频"'+(v.desc||'')+'"下评论/@了你："'+t+'"，回ta一句（口语，别带方括号）。'}],{max:120,aux:true});
  v.comments.push({name:c.remark||c.name,avatar:c.avatar,cid:c.id,text:cleanReply(r).slice(0,50)});save();if(dyModalOpen())dyComments(v.id);}catch(e){}}
function dyGenComments(id){const v=dyVid(id);if(!v)return;aiLoad('正在生成评论…');dyGenCommentsCore(v,{net:6,chars:2,mine:v.cid==='me'}).then(()=>{if(dyModalOpen())dyComments(id);}).finally(aiDone);}
async function dyGenCommentsCore(v,opts){opts=opts||{};v.comments=v.comments||[];
  try{const r=await chatAPI([{role:'system',content:'你是抖音评论区生成器。针对一条短视频生成'+(opts.net||5)+'条不同网友的简短评论（搞笑/共鸣/夸赞/玩梗/抬杠都行，符合抖音风格，'+(opts.mine?'这是个漂亮女生发的，可以有夸她好看、搭讪的':'')+'）。每行一条，格式：昵称:::评论内容。不要别的话。'},{role:'user',content:'视频文案："'+(v.desc||'')+'"，画面："'+(v.narration||'')+'"'}],{max:700,aux:true});
    (r||'').split('\n').map(l=>l.trim()).filter(Boolean).forEach(l=>{const p=l.replace(/^[\d.、\-\s]+/,'').split(/:::|：：：|\|\||：|:/);const nm=clean(p[0]);if(!nm||/^http/.test(nm))return;const tx=(p.slice(1).join('：')||p[0]||'').trim();if(tx)v.comments.push({name:nm,avatar:letterAv(nm),text:tx.slice(0,60)});});save();if(dyModalOpen())dyComments(v.id);
  }catch(e){}
  // 关注的角色（及恋人）也来评论
  let cs=S.contacts.filter(c=>!c.deleted&&!c.blocked&&S.dy.following.includes(c.id));
  if(opts.mine&&S.couple&&S.couple.cid){const lover=getC(S.couple.cid);if(lover&&!lover.blocked&&!cs.find(x=>x.id===lover.id))cs.unshift(lover);}
  for(const c of cs.slice(0,opts.chars||2)){try{const rr=await chatAPI([{role:'system',content:buildSystem(c)},{role:'user',content:'你在抖音刷到'+(opts.mine?S.me.name+'（你恋人）':'一个人')+'发的视频，文案："'+(v.desc||'')+'"，画面："'+(v.narration||'')+'"。以你的身份评论一句'+(opts.mine?'（可以宠溺/吃醋/占有欲，毕竟是你对象发的）':'')+'（口语，别带方括号）。'}],{max:120,aux:true});
    v.comments.push({name:c.remark||c.name,avatar:c.avatar,cid:c.id,text:cleanReply(rr).slice(0,50)});save();if(dyModalOpen())dyComments(v.id);}catch(e){}}}
/* 关注 */
function dyFollowList(){const fl=S.dy.following.map(getC).filter(Boolean);
  openModal(`<h3>我的关注（${fl.length}）</h3><div style="max-height:60vh;overflow:auto">
    ${fl.length?fl.map(c=>`<div class="section"><div class="it">${av(c.avatar,'sm')}<div class="meta" style="flex:1"><div class="n">${esc(c.remark||c.name)}</div><div class="s">${esc(c.signature||'')}</div></div><button class="minibtn" onclick="dyGenContactVideo('${c.id}')">看TA视频</button> <button class="minibtn" onclick="dyUnfollow('${c.id}')">取关</button></div></div>`).join(''):'<div class="empty">还没关注谁</div>'}
  </div><button class="btn p" style="margin-top:8px" onclick="closeModal();dyAddFollow()">＋ 添加角色的抖音</button><button class="btn g" style="margin-top:8px" onclick="closeModal()">关闭</button>`);}
function dyAddFollow(){const cs=S.contacts.filter(c=>!c.deleted&&!S.dy.following.includes(c.id));
  openModal(`<h3>添加角色抖音</h3>${cs.length?cs.map(c=>`<div class="section"><div class="it" onclick="dyDoFollow('${c.id}')">${esc(c.remark||c.name)}<span class="v">＋ 关注</span></div></div>`).join(''):'<div class="empty">没有可添加的角色了</div>'}<button class="btn g" style="margin-top:8px" onclick="closeModal()">取消</button>`);}
function dyDoFollow(cid){if(!S.dy.following.includes(cid))S.dy.following.push(cid);save();closeModal();toast('已关注，去刷TA的视频吧');dyGenContactVideo(cid);}
function dyUnfollow(cid){S.dy.following=S.dy.following.filter(x=>x!==cid);save();closeModal();render();}
async function dyGenContactVideo(cid){const c=getC(cid);if(!c)return;if(!S.dy.following.includes(cid))S.dy.following.push(cid);closeModal();aiLoad('正在生成…');
  try{const o=await aiGen([{role:'system',content:buildSystem(c)},{role:'user',content:'你在抖音发了一条短视频。只输出JSON：{"desc":"视频文案(一句，可带#话题)","narration":"旁白：这条视频里你拍了什么画面、在做什么(2-4句)","music":"配乐名","emoji":"代表画面的emoji"}'}],{max:400,aux:true},parseObj);
    if(!o||!o.desc){toast('生成失败了，再点一次');return;}
    S.dy.feed.unshift({id:uid(),author:c.remark||c.name,handle:'@'+(c.name||'').replace(/\s/g,''),avatar:c.avatar,cid:cid,desc:o.desc||'',narration:o.narration||'',music:o.music||'原创音乐',emoji:(o.emoji||'🎬').slice(0,2),grad:DY_GRADS[Math.floor(Math.random()*DY_GRADS.length)],lk:Math.floor(Math.random()*5000),comments:[],ts:Date.now()});
    save();dyTab='feed';_dyMode='follow';if(cur().p==='dy')render();else go('dy');const f=$('#dyfeed');if(f)f.scrollTop=0;
  }finally{aiDone();}}
/* 私信 */
function dyDMList(){const ds=S.dy.dms||[];
  return `<div style="padding:10px 14px;display:flex;gap:8px;justify-content:flex-end;background:#000;border-bottom:.5px solid #222"><button class="dybtn out" onclick="dyGenDMs()">刷新私信</button><button class="dybtn out" onclick="dyDMPick()">＋ 私信角色</button></div>
    <div style="flex:1;overflow-y:auto;background:#000">${ds.length?ds.map(d=>{const last=d.msgs[d.msgs.length-1];return `<div class="xdmrow"><span onclick="go('dydm',{id:'${d.id}'})">${av(d.avatar,'sm')}</span><div class="meta" onclick="go('dydm',{id:'${d.id}'})"><div class="n" style="color:#eee">${esc(d.name)}${d.cid?'':' <span style="font-size:11px;color:#888">网友</span>'}</div><div class="s">${last?esc((last.from==='me'?'我：':'')+last.text):''}</div></div><span onclick="S.dy.dms=S.dy.dms.filter(z=>z.id!=='${d.id}');save();render()" style="color:#fa5151;cursor:pointer;padding:0 6px">✕</span></div>`;}).join(''):'<div class="empty" style="padding:40px">还没有私信～点「刷新私信」看看有没有人私信你，或「私信角色」主动找人</div>'}</div>`;}
function dyDMPick(){const cs=S.contacts.filter(c=>!c.deleted);if(!cs.length){toast('先创建角色');return;}
  openModal(`<h3>私信谁</h3>${cs.map(c=>`<div class="section"><div class="it" onclick="openDyDM('${c.id}')">${esc(c.remark||c.name)}<span class="v">›</span></div></div>`).join('')}<button class="btn g" style="margin-top:8px" onclick="closeModal()">取消</button>`);}
function openDyDM(cid){const c=getC(cid);if(!c)return;closeModal();openDyDMName(c.remark||c.name,cid,c.avatar);}
function openDyDMName(name,cid,avatar){let d=cid?S.dy.dms.find(x=>x.cid===cid):S.dy.dms.find(x=>!x.cid&&x.name===name);if(!d){d={id:uid(),cid:cid||null,name,avatar:avatar||'🎵',msgs:[]};S.dy.dms.unshift(d);save();}go('dydm',{id:d.id});}
async function dyGenDMs(){aiLoad('正在刷新私信…');const recent=(S.dy.mine||[]).slice(0,3).map(v=>v.desc).filter(Boolean).join('；')||(S.dy.history||[]).slice(0,3).join('、');
  try{const rows=await aiGen([{role:'system',content:'你生成抖音陌生网友私信。生成3条不同网友（看了'+S.me.name+'视频来的）发来的私信开场，要暧昧、会撩、夸她好看、想加微信想约她那种（目的是让她男朋友看到会吃醋），但别露骨下流。每行一条，格式：网友名:::私信内容。不要别的话。'},{role:'user',content:(recent?'她最近发的/搜的："'+recent+'"，可以结合。':'')+'生成撩人的私信开场。'}],{max:500,aux:true},(r)=>{const out=(r||'').split('\n').map(l=>l.trim()).filter(Boolean).map(l=>{const p=l.replace(/^[\d.、\-\s]+/,'').split(/:::|：：：|\|\||：|:/);const nm=clean(p[0]);if(!nm||/^http/.test(nm))return null;return {name:nm,text:(p.slice(1).join('：')||'在吗美女').trim().slice(0,80)};}).filter(Boolean);return out.length?out:null;});
    if(!rows){toast('刷新失败了，再试一次');return;}
    rows.forEach(x=>S.dy.dms.unshift({id:uid(),cid:null,name:x.name,avatar:letterAv(x.name),msgs:[{from:'them',text:x.text,time:Date.now()}]}));
    save();render();toast('有'+rows.length+'条新私信👀');
  }finally{aiDone();}}
function renderDyDM(id){const d=S.dy.dms.find(x=>x.id===id);if(!d)return '';
  return `<div class="dynav"><span class="l" onclick="back()" style="cursor:pointer">‹</span><span style="font-weight:700">${esc(d.name)}</span><span class="r" onclick="dyClearDM('${id}')" style="cursor:pointer;color:#fa9bb5;font-size:13px">清空</span></div>
    <div class="xscroll" id="dydmbox" style="padding:10px 14px;background:#111">${d.msgs.map((m,mi)=>`<div class="xmsg ${m.from==='me'?'me':''}"><div class="xmwrap"><div class="b" onclick="dyDelDMMsg('${id}',${mi})" title="点删除这条">${esc(m.text)}</div><div class="xmt">${m.time?hm(m.time):''}</div></div></div>`).join('')||'<div class="empty" style="padding:30px">抖音私信，发条消息打个招呼吧</div>'}</div>
    <div class="inputbar"><textarea id="dydm_in" rows="1" placeholder="发私信…"></textarea><button class="send" onclick="dySendDM('${id}')">发送</button></div>`;}
async function dyClearDM(id){const d=S.dy.dms.find(x=>x.id===id);if(!d)return;if(!await uiConfirm('清空和「'+d.name+'」的全部私信记录？'))return;d.msgs=[];save();render();toast('已清空');}
async function dyDelDMMsg(id,mi){const d=S.dy.dms.find(x=>x.id===id);if(!d)return;if(!await uiConfirm('删除这条私信？'))return;d.msgs.splice(mi,1);save();render();}
function dySendDM(id){const d=S.dy.dms.find(x=>x.id===id);const inp=$('#dydm_in');const v=inp?inp.value.trim():'';if(!v)return;
  d.msgs.push({from:'me',text:v,time:Date.now()});save();render();dyDMReply(d);}
async function dyDMReply(d){try{const hist=d.msgs.slice(-10).map(m=>({role:m.from==='me'?'user':'assistant',content:m.text}));let sys;
  const c=d.cid?getC(d.cid):null;
  if(c)sys=buildSystem(c)+'\n\n# 场景\n现在在【抖音私信】里和'+S.me.name+'聊天，口语、简短自然，别带方括号动作。';
  else sys='你是抖音上的陌生网友/小博主「'+d.name+'」，因为看了'+S.me.name+'的视频来私信她，自来熟、会撩、想加她微信想约她，但不下流。口语、简短、有网感，别带方括号。';
  const r=await chatAPI([{role:'system',content:sys},...hist],{max:200,aux:true});
    d.msgs.push({from:'them',text:cleanReply(r),time:Date.now()});save();if(cur().p==='dydm')render();}catch(e){}}
/* 我的主页 */
function dyProfile(){const liked=S.dy.liked||[];const mine=S.dy.mine||[];
  const grid=arr=>`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:2px;padding:0 2px">${arr.map(v=>`<div onclick="dyOpenLiked('${v.id}')" style="position:relative;aspect-ratio:3/4;background:${v.grad||DY_GRADS[0]};border-radius:4px;display:flex;align-items:center;justify-content:center;font-size:34px;cursor:pointer"><span>${v.emoji||'🎬'}</span><span style="position:absolute;left:4px;bottom:3px;font-size:10px;color:#fff">❤️${(v.lk||0)+(v.liked?1:0)}</span></div>`).join('')}</div>`;
  return `<div style="flex:1;overflow-y:auto;background:#000;color:#eee">
    <div style="text-align:center;padding:20px 14px">
      <div onclick="changeDyAvatar()" style="cursor:pointer;display:inline-block">${av(dyAvatar(),'lg')}</div>
      <div style="font-size:19px;font-weight:700;margin-top:8px">${esc(dyNick())}</div>
      <div style="color:#888;font-size:13px;margin-top:4px">${esc(S.dy.profile.bio||'')}</div>
      <div style="margin-top:10px;display:flex;justify-content:center;gap:8px;flex-wrap:wrap"><button class="dybtn" onclick="dyCompose()">＋ 发抖音</button><button class="dybtn out" onclick="editDyProfile()">编辑资料</button><button class="dybtn out" onclick="dyFollowList()">关注 ${S.dy.following.length}</button></div>
    </div>
    <div style="border-top:.5px solid #222;padding:12px 14px;font-weight:700">🎬 我的作品（${mine.length}）</div>
    ${mine.length?grid(mine):'<div class="empty" style="padding:24px;color:#888">还没发过视频～点上面「＋ 发抖音」</div>'}
    <div style="border-top:.5px solid #222;padding:12px 14px;font-weight:700;margin-top:6px;display:flex;align-items:center;gap:6px">${svgIc('heart',15,'#f4245e')} 我的喜欢（${liked.length}）</div>
    ${liked.length?grid(liked):'<div class="empty" style="padding:24px;color:#888">还没点赞过视频～点赞的会出现在这里</div>'}
    <div style="height:16px"></div>`;}
function dyOpenLiked(id){const v=dyVid(id);if(!v)return;const isMineVid=v.cid==='me';
  openModal(`<h3>${esc(v.emoji||'🎬')} @${esc(isMineVid?dyNick():v.author)}</h3><div style="font-size:14px;line-height:1.6;color:#333">${esc(v.desc||'')}</div>
    <div style="background:#f4f4f6;border-radius:10px;padding:10px;margin-top:10px;font-size:13px;line-height:1.7;color:#555"><b>📖 旁白：</b>${esc(v.narration||'（无）')}</div>
    <div class="btns" style="margin-top:12px;flex-wrap:wrap"><button class="dybtn out" onclick="closeModal();dyComments('${id}')">评论 ${(v.comments||[]).length}</button><button class="dybtn out" onclick="closeModal();dyFwd('${id}')">↗️ 转发给角色</button>${isMineVid?`<button class="btn d" onclick="dyDelVideo('${id}')">删除</button>`:`<button class="btn d" onclick="dyLike('${id}');closeModal()">取消点赞</button>`}<button class="btn g" onclick="closeModal()">关闭</button></div>`);}
function changeDyAvatar(){pickFile('image/*',async f=>{S.dy.profile.avatar=await compress(f,300,.8);save();render();toast('头像已换 🎨');});}
function editDyProfile(){const p=S.dy.profile;openModal(`<h3>编辑抖音资料</h3>
  <div class="field"><label>昵称</label><input id="dyp_n" value="${esc(p.nick||S.me.name)}"></div>
  <div class="field"><label>简介</label><input id="dyp_b" value="${esc(p.bio||'')}"></div>
  <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="(function(){S.dy.profile.nick=$('#dyp_n').value.trim();S.dy.profile.bio=$('#dyp_b').value.trim();save();closeModal();render();})()">保存</button></div>`);}

/* ---------- 任务便签（他给我布置每日任务）---------- */
let _taskBusy=false;
function taskRelationAllowed(c){return !!(c&&isLover(c));}
function taskC(){const ok=x=>!!(x&&!x.deleted&&!x.blocked&&!x.taskOff&&taskRelationAllowed(x)),cc=S.couple&&getC(S.couple.cid);return ok(cc)?cc:(S.contacts.find(ok)||null);}
function taskDailyCount(c){return Math.max(1,Math.min(8,+((c&&c.taskN)||3)));}
function tasksToday(c){const t=c&&c.tasks;if(!t||t.date!==todayStr())return null;
  const cap=taskDailyCount(c),old=Array.isArray(t.list)?t.list:[],clean=old.filter(x=>x&&!x.extra).slice(0,cap);
  if(clean.length!==old.length){t.list=clean;save();}
  return t;}
function _taskNorm(s){return (''+s).replace(/[\s，。、！!？?.~…：:；;「」『』""''（）()]/g,'');}
// 判断 text 是否和 list 里已有任务重复：一模一样 / 子串 / 共享强关键字(检讨等) / 关键字高度重合
const _TASK_KW=['检讨','保证书','小作文','作文','情书','彩虹屁','道歉信','认错书'];
function taskDup(list,text){const nt=_taskNorm(text);if(!nt)return true;const setT=new Set(nt);
  const kwT=_TASK_KW.filter(k=>nt.includes(k));
  return (list||[]).some(x=>{const nx=_taskNorm(x.text);if(!nx)return false;
    if(nx===nt)return true;
    if(Math.min(nx.length,nt.length)>=3&&(nx.includes(nt)||nt.includes(nx)))return true;
    if(kwT.some(k=>nx.includes(k)))return true;/* 都是"写检讨/作文/保证书"这类同义任务 */
    const setX=new Set(nx);let inter=0;setT.forEach(ch=>{if(setX.has(ch))inter++;});
    const shorter=Math.min(setT.size,setX.size);
    return shorter>=3&&inter/shorter>=0.8;/* 短任务的字几乎都在另一条里→重复 */});}
function taskVerifyLabel(x){return {steps:'我走够了',essay:'写好交给ta',moment:'我发朋友圈了',tweet:'我发推了',douyin:'我发抖音了',real:'完成了',truth:'老实回答ta'}[x.verify]||'完成';}
function postedSince(kind,since){since=since||0;
  if(kind==='moment')return S.moments.some(p=>p.authorId==='me'&&(p.time||0)>since);
  if(kind==='tweet')return (S.x&&S.x.tweets||[]).some(t=>t.who==='me'&&(t.time||0)>since);
  if(kind==='douyin')return (S.dy&&S.dy.mine||[]).some(v=>(v.ts||0)>since);
  return false;}
function renderTasks(){const c=taskC();
  if(!c){const off=S.contacts.some(x=>!x.deleted&&!x.blocked&&x.taskOff);return `<div class="nav"><span class="l" onclick="home()">‹</span><span class="t">任务便签</span><span class="r"></span></div><div class="scroll" style="background:#000"><div class="empty" style="padding:50px 24px;line-height:2">${off?'已关闭布置任务的角色不会再给你安排任务。':'还没有恋人角色～<br>先创建一个角色（最好在情侣空间绑定），ta就能给你布置任务啦'}</div></div>`;}
  checkTaskPenalty(c);const t=tasksToday(c);const n=taskDailyCount(c);
  let body;
  if(!t){body=`<div style="margin:14px;padding:20px;border-radius:16px;background:linear-gradient(145deg,#f59e0b,#b45309);color:#fff;text-align:center">
      <div style="font-size:15px">${esc(c.remark||c.name)} 还没布置今天的任务</div>
      <div style="font-size:12px;opacity:.9;margin:6px 0 14px">每天打开自动收到 · 当天23:59前完成<br>全部完成有奖励🎁，没完成会被记仇、线下受罚哦</div>
      <button class="btn" style="background:#fff;color:#b45309;font-weight:700" ${_taskBusy?'disabled':''} onclick="genTasks()">${_taskBusy?'ta在安排…':'📋 让ta布置今天的任务'}</button></div>
    <div class="section" style="margin:12px"><div class="it"><span>每天任务条数</span><span class="v"><input id="tk_n" type="number" min="1" max="8" value="${n}" style="width:46px;text-align:center;border:1px solid #38383a;border-radius:6px;padding:4px;background:#2c2c2e;color:#eee"> <button class="minibtn" onclick="(function(){var v=Math.max(1,Math.min(8,+$('#tk_n').value||3));taskC().taskN=v;save();toast('每天'+v+'条');})()">存</button></span></div>
      <div class="it"><span>每天布置时间</span><span class="v"><input id="tk_time" type="time" value="${c.taskTime||'09:00'}" style="border:1px solid #38383a;border-radius:6px;padding:4px;background:#2c2c2e;color:#eee"> <button class="minibtn" onclick="(function(){taskC().taskTime=$('#tk_time').value||'09:00';save();toast('每天'+taskC().taskTime+'布置');})()">存</button></span></div>
      <div class="hint" style="padding:0 14px">到这个点之后、你打开 North 就会收到当天任务（不会再凌晨发）。也能随时点上面的按钮手动让ta布置。</div></div>`;}
  else{const done=t.list.filter(x=>x.done).length,total=t.list.length,all=total&&done===total;
    body=`<div style="margin:14px;padding:16px;border-radius:16px;background:linear-gradient(145deg,${all?'#19a463,#0c6b3f':'#f59e0b,#b45309'});color:#fff;text-align:center">
      <div style="font-size:14px">今天的任务 · ${esc(c.remark||c.name)} 布置</div>
      <div style="font-size:30px;font-weight:700;margin:4px 0">${done}/${total}</div>
      <div style="font-size:12px;opacity:.95">${all?'全部完成啦！等ta的奖励🎁':'今天23:59前完成，全做完有奖励～'}</div></div>
      ${t.list.map((x,i)=>`<div class="section" style="margin:10px 12px"><div style="padding:12px 14px">
        <div style="display:flex;justify-content:space-between;align-items:center"><span class="tag">${x.truth?'真心话':(x.kind==='real'?'现实':'手机')}</span>${x.done?'<span style="color:#19a463;font-size:13px">已完成</span>':''}</div>
        <div style="margin:8px 0;font-size:15px;line-height:1.5;${x.done?'color:#888;text-decoration:line-through':'color:#eee'}">${esc(x.text)}</div>
        ${x.done?'':`<button class="btn p" onclick="completeTask('${x.id}')">${taskVerifyLabel(x)}</button>`}
      </div></div>`).join('')}
      <div class="hint" style="padding:6px 16px">手机任务会真的验证（作文要交给ta看、发布类要真发了、步数要够），别糊弄~ 现实任务靠你自觉，骗ta的话线下要罚的</div>`;}
  return `<div class="nav"><span class="l" onclick="home()">‹</span><span class="t">任务便签</span><span class="r"></span></div>
    <div class="scroll" style="background:#000">${body}<div style="height:20px"></div></div>`;}
async function genTasks(){const c=taskC();if(!c){toast('没有可布置任务的角色');return;}if(c.taskOff){toast('这个角色已关闭布置任务');return;}if(tasksToday(c)){toast('今天的任务ta已经布置过啦');return;}if(_taskBusy)return;
  checkTaskPenalty(c);_taskBusy=true;render();toast('ta在琢磨今天怎么安排你…');
  const n=taskDailyCount(c),normalN=Math.max(0,n-1);
  const hist=(c.taskHist||[]).map(s=>({text:s}));// 最近几天布置过的任务，用来防止重复
  const avoidTxt=hist.length?'\n· 【最近这些任务你已经布置过了，今天务必换着花样来，别再重复、也别换汤不换药地重复同类】：'+hist.map(h=>h.text).join('；'):'';
  try{const allowed='essay（写小作文/检讨/彩虹屁/想你的话/保证书，target填字数上限如100）、moment（发一条朋友圈）、tweet（发一条推特X）、douyin（发一条抖音）、real（现实里的小事或暧昧亲密小任务，靠她自觉打卡，比如：喝杯水、好好吃饭、敷面膜、早点睡、给你拍张自拍、睡前跟你撒娇道晚安、对着镜头说想你、穿你喜欢的小裙子拍给你、乖乖只想你一个、今天不准跟别的男生聊天等）';
    const _tm=[{role:'system',content:buildSystem(c)},{role:'user',content:'[系统：现在你来给'+S.me.name+'布置今天总共恰好 '+n+' 条小任务。你是ta的恋人/掌控者，按你的人设、此刻心情、ta最近的表现来布置。\n· 任务一定要【有趣、有创意、好玩】，别死板、别像打卡清单、别每天千篇一律——可以整点花活、玩梗、设小情境。'+avoidTxt+'\n· 多来点【暧昧、撩人、亲密】的，而且要以【Dom的姿态】来布置：命令式、强势、掌控欲拉满，把ta当你的小sub来调教，语气笃定带点危险又宠溺，要ta乖乖服从听话。可以大胆放得开、带点涩，越让ta脸红心跳、心甘情愿被你拿捏越好（保持是两个相爱的人之间有掌控有宠爱的情趣，不用拘谨）。\n· 现实任务一定要轻松，别累人：绝对不要罚跑步/暴走/喝很多杯水那种。\n大部分任务要是【在手机上就能完成的】(essay/moment/tweet/douyin)，可以有一两条现实任务(real)。每条必须从这些可验证类型里选一个：'+allowed+'。\n· 这 '+n+' 条里必须有且只有一条 verify 为 truth 的任务，内容是你【今天最想问'+S.me.name+'的一个真心话问题】（一句问句就好，可以暧昧、走心或是你好奇/在意的事），target填0、kind填real。真心话算在总数里，除此之外只能再给 '+normalN+' 条，绝不能额外追加。\n只输出JSON数组、不要任何解释：[{"text":"任务描述(用你的第一人称口吻，强势Dom的命令语气，像在调教/撩/宠你的小sub，可以霸道也可以俏皮有梗)","kind":"app或real","verify":"类型代码","target":数字(没有填0)}]'}];
    let arr=await aiGen(_tm,{max:760},parseArr);
    if(!arr||!arr.length)arr=await aiGen(_tm,{max:760,aux:true},parseArr);/* 主模型不行就用副模型兜底 */
    if(!arr||!Array.isArray(arr)||!arr.length)throw 0;
    let truthQ='';
    const list=[];for(const o of arr){const text=(o.text||'').toString().slice(0,140);if(!text)continue;
      if(o.verify==='truth'){if(!truthQ)truthQ=text;continue;}/* 真心话算在每日总数里 */
      if(list.length>=normalN)continue;if(taskDup(list,text)||taskDup(hist,text))continue;/* 跳过重复/最近布置过的 */
      list.push({id:uid(),text,kind:o.kind==='real'?'real':'app',verify:['essay','moment','tweet','douyin','real'].indexOf(o.verify)>=0?o.verify:'real',target:+o.target||0,done:false});}
    const fallback=[
      {text:'睡前认真来跟我说一句只属于今天的晚安。',kind:'real',verify:'real',target:0},
      {text:'写三句今天为什么喜欢我，别敷衍。',kind:'app',verify:'essay',target:80},
      {text:'拍下你现在手边最喜欢的东西给我看。',kind:'real',verify:'real',target:0},
      {text:'发一条只有我能看懂的朋友圈。',kind:'app',verify:'moment',target:0},
      {text:'挑一个时刻主动来跟我撒一次娇。',kind:'real',verify:'real',target:0},
      {text:'写一小段今天最想让我夸你的地方。',kind:'app',verify:'essay',target:100},
      {text:'今天找一件让自己开心的小事，做完告诉我。',kind:'real',verify:'real',target:0},
      {text:'认真想一句只想对我说的话，今晚交给我。',kind:'app',verify:'essay',target:80}
    ];
    for(const f of fallback){if(list.length>=normalN)break;if(taskDup(list,f.text)||taskDup(hist,f.text))continue;list.push({id:uid(),...f,done:false});}
    for(const f of fallback){if(list.length>=normalN)break;if(taskDup(list,f.text))continue;list.push({id:uid(),...f,done:false});}
    if(list.length!==normalN)throw 0;
    list.push({id:uid(),text:truthQ||'今天，你最想跟我说、却一直没说出口的一句话是什么？',kind:'truth',verify:'truth',target:0,done:false,truth:true});// 固定的"他想问我的真心话"
    c.taskHist=[...list.map(x=>x.text),...(c.taskHist||[])].slice(0,30);// 记下今天布置的，往后几天别重复
    c.tasks={date:todayStr(),assignTs:Date.now(),list,rewarded:false,penalized:false};save();_taskBusy=false;render();toast('任务来咯📋');
    if(!c.blocked)scheduleReply(c.id,'[系统：你刚在'+S.me.name+'手机的任务便签里给ta布置了今天的任务，跟ta说一声、催ta【今天23:59之前】完成、说说不完成的后果，一两句，符合你人设。别逐条复述任务。]');
  }catch(e){_taskBusy=false;render();toast('没布置成功，再点一次');}}
async function completeTask(id){const c=taskC();const t=tasksToday(c);if(!t)return;const x=t.list.find(z=>z.id===id);if(!x||x.done)return;
  if(x.verify==='truth'){openTruth(id);return;}
  if(x.verify==='essay'){openEssay(id);return;}
  if(x.verify==='steps'){if(!await uiConfirm('完成这条了吗？（步数任务已取消，点确定即可完成）'))return;}
  if(x.verify==='moment'&&!postedSince('moment',t.assignTs)){toast('布置任务后还没发朋友圈哦，发一条再来点完成');return;}
  if(x.verify==='tweet'&&!postedSince('tweet',t.assignTs)){toast('布置任务后还没发推哦，发一条再来');return;}
  if(x.verify==='douyin'&&!postedSince('douyin',t.assignTs)){toast('布置任务后还没发抖音哦，去发一条');return;}
  if(x.verify==='real'&&!await uiConfirm('确定真的完成了这条现实任务吗？\n骗ta的话…线下见面要受罚的哦')){return;}
  finishTask(c,x);}
function finishTask(c,x,proof){x.done=true;x.doneTs=Date.now();save();render();toast('完成啦 ✅');
  if(!c.blocked)scheduleReply(c.id,'[系统：'+S.me.name+'完成了你今天布置的任务「'+x.text+'」'+(proof?'，ta把内容发到你们聊天里了，先看一眼':'')+'。简短回应一句（夸ta/调侃/继续端着都行，符合你人设）。]');
  checkAllDone(c);}
function checkAllDone(c){const t=tasksToday(c);if(!t||t.rewarded)return;if(t.list.length&&t.list.every(x=>x.done)){t.rewarded=true;save();
    if(!c.blocked)scheduleReply(c.id,'[系统：'+S.me.name+'把你今天布置的 '+t.list.length+' 条任务【全部完成】了！按说好的要奖励ta——用单独一行 [送礼|礼物名|价格] 送ta一个礼物，并夸夸ta、表示满意。]');}}
function openEssay(id){const c=taskC();const t=tasksToday(c);const x=t&&t.list.find(z=>z.id===id);if(!x)return;const max=x.target||100;
  openModal(`<h3>交作业</h3><div class="hint">${esc(x.text)}<br>（${max}字以内，至少10字，认真写，ta会看的~）</div>
    <div class="field"><textarea id="essay_t" rows="5" placeholder="在这里写…" oninput="var e=$('#essay_c');if(e)e.textContent=this.value.trim().length+'/'+${max}"></textarea><div id="essay_c" style="text-align:right;font-size:12px;color:#999">0/${max}</div></div>
    <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="submitEssay('${id}',${max})">交给ta</button></div>`);}
function submitEssay(id,max){const ta=$('#essay_t');const v=(ta?ta.value:'').trim();if(v.length<10){toast('至少写10个字啦，别糊弄~');return;}if(v.length>max){toast('超字数了，'+max+'字以内');return;}
  const c=taskC();const t=tasksToday(c);const x=t&&t.list.find(z=>z.id===id);if(!x)return;
  pushMsg(c.id,{role:'user',type:'text',content:'【作业·'+x.text+'】\n'+v,id:uid()});closeModal();finishTask(c,x,v);}
function openTruth(id){const c=taskC();const t=tasksToday(c);const x=t&&t.list.find(z=>z.id===id);if(!x)return;
  openModal(`<h3>真心话</h3><div class="hint" style="color:#ddd;font-size:14px;line-height:1.6">ta想问你：<br><b style="color:#ff8fab">${esc(x.text)}</b><br><span style="color:#999">老实回答ta哦，会发到你们的聊天里～</span></div>
    <div class="field"><textarea id="truth_t" rows="4" placeholder="如实回答…"></textarea></div>
    <div class="btns"><button class="btn g" onclick="closeModal()">先不答</button><button class="btn p" onclick="submitTruth('${id}')">告诉ta</button></div>`);}
function submitTruth(id){const ta=$('#truth_t');const v=(ta?ta.value:'').trim();if(v.length<2){toast('好歹答一句嘛~');return;}
  const c=taskC();const t=tasksToday(c);const x=t&&t.list.find(z=>z.id===id);if(!x)return;
  pushMsg(c.id,{role:'user',type:'text',content:'【真心话·'+x.text+'】\n'+v,id:uid()});closeModal();finishTask(c,x,v);}
function checkTaskPenalty(c){const t=c&&c.tasks;if(!t||t.date===todayStr()||t.penalized)return;
  const undone=t.list.filter(x=>!x.done);t.penalized=true;
  if(undone.length){grudgesOf(c).unshift({id:uid(),text:t.date+' 没完成我布置的任务（差'+undone.length+'条：'+undone.map(x=>x.text).join('、').slice(0,36)+'）',done:false,ts:Date.now()});
    behaviorRecord('task',t.date+' 有 '+undone.length+' 条任务没完成：'+undone.map(x=>x.text).join('、').slice(0,50),'task',{force:true});
    if(!c.blocked)scheduleReply(c.id,'[系统：'+t.date+'你给'+S.me.name+'布置的任务，ta有 '+undone.length+' 条没完成。你不太高兴，已经记到你的小本本上了，冷淡地说一句、并威胁线下见面要罚ta（怎么罚你自己定，符合人设），一两句。]');}
  save();}

/* ---------- 微信主界面 ---------- */
function renderWeChat(){
  if(S.wxLogin){if(Date.now()>=S.wxLogin.until)setTimeout(wxLogout,0);else{if(!_wxLoginTimer)wxLoginStartTimer();return wxLockedScreen();}}
  let body='';
  if(wxTab==='chats')body=wxChats();
  else if(wxTab==='contacts')body=wxContacts();
  else if(wxTab==='moments')body=wxMoments();
  else if(wxTab==='me')body=wxMe();
  const titles={chats:'微信',contacts:'通讯录',moments:'朋友圈',me:'我'};
  const showAdd=wxTab==='chats'||wxTab==='contacts'||wxTab==='moments';
  return `<div class="nav"><span class="l" onclick="home()">‹</span><span class="t">${titles[wxTab]}</span><span class="r" onclick="${wxTab==='chats'?'chatAddMenu()':wxTab==='contacts'?'editContact()':wxTab==='moments'?'momentTools()':''}">${showAdd?'＋':''}</span></div>
    <div class="scroll" style="background:${S.me.wxTheme==='white'?'#ededed':'#000'}">${body}</div>
    <div class="tabbar">
      ${tb('chats',svgIc('chat',23),'微信')}${tb('contacts',svgIc('user',23),'通讯录')}${tb('moments',svgIc('camera',23),'朋友圈')}${tb('me',svgIc('cat',23),'我')}
    </div>`;
}
function tb(k,i,t){return `<div class="tb ${wxTab===k?'on':''}" onclick="wxTab='${k}';render()"><div class="i">${i}</div>${t}</div>`;}
function openWxSearch(){go('wxsearch');setTimeout(()=>{const i=$('#wxs_in');if(i)i.focus();},80);}
function renderWxSearch(){
  return `<div class="nav"><span class="l" onclick="back()">‹</span><span class="t">搜索聊天记录</span><span class="r"></span></div>
    <div style="padding:8px 12px;background:#1c1c1e"><input id="wxs_in" placeholder="🔍 搜你和角色们的聊天" oninput="wxSearchRun(this.value)" style="width:100%;box-sizing:border-box;border:none;border-radius:8px;padding:9px 12px;background:#2c2c2e;color:#eee;font-size:14px"></div>
    <div class="scroll" id="wxs_res" style="background:#000"><div class="empty" style="padding:34px 24px;color:#888;line-height:1.8">输入关键词<br>搜你和所有角色的聊天记录</div></div>`;}
function wxHi(t,q){const lt=t.toLowerCase();const i=lt.indexOf(q);if(i<0)return esc(t.slice(0,42))+(t.length>42?'…':'');const s=Math.max(0,i-10);return (s>0?'…':'')+esc(t.slice(s,i))+'<b style="color:#07c160">'+esc(t.slice(i,i+q.length))+'</b>'+esc(t.slice(i+q.length,i+q.length+26))+(t.length>i+q.length+26?'…':'');}
function wxSearchRun(q){const box=$('#wxs_res');if(!box)return;q=(q||'').trim().toLowerCase();
  if(!q){box.innerHTML='<div class="empty" style="padding:34px 24px;color:#888;line-height:1.8">输入关键词<br>搜你和所有角色的聊天记录</div>';return;}
  const hits=[];S.contacts.filter(c=>!c.deleted).forEach(c=>{const arr=msgs(c.id);for(let i=arr.length-1;i>=0;i--){const m=arr[i];if(!m||m.type==='sys')continue;let t='';if(m.type==='text')t=m.content||'';else if(m.type==='voice')t=m.content||'';else continue;if(t&&t.toLowerCase().indexOf(q)>=0)hits.push({c,m,t});}});
  hits.sort((a,b)=>(b.m.time||0)-(a.m.time||0));
  const pf=/^sp[a-z0-9]{4,12}$/i.test(q)?`<div class="list"><div class="row" onclick="phoneFriendSearchFromWx('${esc(q)}')"><div class="avatar sm" style="background:#6574ff">${svgIc('users',21,'#fff')}</div><div class="meta"><div class="n">搜索小手机ID</div><div class="s">查找 ${esc(q.toUpperCase())} 并申请添加</div></div><span class="v">›</span></div></div>`:'';
  box.innerHTML=pf+(hits.length?('<div style="padding:8px 14px 2px;color:#888;font-size:12px">找到 '+hits.length+' 条</div>'+hits.slice(0,80).map(h=>`<div class="row" onclick="openChat('${h.c.id}')">${av(h.c.avatar)}<div class="meta"><div class="n">${esc(h.c.remark||h.c.name)}<span style="color:#666;font-weight:400;font-size:11px;float:right">${h.m.time?hm(h.m.time):''}</span></div><div class="s">${h.m.role==='user'?'<span style="color:#888">我：</span>':''}${wxHi(h.t,q)}</div></div></div>`).join('')):('<div class="empty" style="padding:34px 24px;color:#888">没找到包含「'+esc(q)+'」的聊天</div>'));}

function renderPhoneFriends(){const p=phoneFriendState();phoneFriendMaybeSync(false);const incoming=pfReqs('incoming'),outgoing=pfReqs('outgoing'),search=p.search||{};
  const found=(search.items||[]).map(x=>{const id=(''+(x.phone_id||x.id||'')).toUpperCase();const already=id===p.id||phoneFriendById(id);return `<div class="row">${av(x.avatar||'🙂','sm')}<div class="meta"><div class="n">${esc(x.display_name||'小手机用户')}</div><div class="s">小手机ID：${esc(id)}</div></div>${already?'<span class="pfsoft">已是好友</span>':`<button class="minibtn" style="background:#07c160;color:#fff" onclick="phoneFriendRequest('${id}')">添加</button>`}</div>`;}).join('');
  return `<div class="nav"><span class="l" onclick="back()">‹</span><span class="t">小手机好友</span><span class="r" onclick="phoneFriendSync(false,true)">${svgIc('refresh',20,'#ccc')}</span></div>
  <div class="scroll" style="background:${S.me.wxTheme==='white'?'#ededed':'#000'}">
    <div class="section" style="margin:12px">
      <div style="padding:13px 14px 6px;color:#9ec5fe;font-weight:700">我的小手机ID</div>
      <div class="it"><span style="font-size:22px;font-weight:800;letter-spacing:1px">${esc(p.id)}</span><button class="minibtn" onclick="copyPhoneFriendId()">复制</button></div>
      <div class="it"><span>允许别人通过ID搜到我</span><span class="sw ${p.allowSearch!==false?'on':''}" onclick="phoneFriendToggleSearch()"></span></div>
      ${p._repairNote?`<div class="hint" style="color:#9ec5fe">${esc(p._repairNote)}</div>`:''}${p.lastError?`<div class="hint" style="color:#e8a85b">${esc(p.lastError)}</div>`:''}
    </div>
    <div class="section" style="margin:12px">
      <div style="padding:12px 14px 4px;color:#cdd;font-weight:700">添加好友</div>
      <div style="display:flex;gap:8px;padding:6px 14px 12px"><input id="pf_search" value="${esc(search.q||'')}" placeholder="输入对方小手机ID，如 SPXXXXXX" style="flex:1;border:1px solid #38383a;border-radius:9px;padding:9px;background:#2c2c2e;color:#eee;text-transform:uppercase">${(search.q||(search.items&&search.items.length))?'<button class="minibtn" onclick="phoneFriendSearchClear()">清空</button>':''}<button class="send" onclick="phoneFriendSearch()">搜索</button></div>
      ${search.busy?'<div class="empty" style="padding:14px;color:#888">搜索中…</div>':search.err?`<div class="hint" style="color:#e8a85b">${esc(search.err)}</div>`:(found||((search.q||'')?'<div class="empty" style="padding:14px;color:#888">没搜到这个ID</div>':''))}
    </div>
    ${incoming.length?`<div class="section" style="margin:12px"><div style="padding:12px 14px 4px;color:#ffb6d0;font-weight:700">新的申请</div>${incoming.map(r=>`<div class="it">${av(r.from_avatar||'🙂','sm')}<span style="flex:1">${esc(r.from_name||r.from_id)}</span><button class="minibtn" style="background:#07c160;color:#fff" onclick="phoneFriendRespond('${r.id}',true)">通过</button><button class="minibtn" onclick="phoneFriendRespond('${r.id}',false)">忽略</button></div>`).join('')}</div>`:''}
    ${outgoing.length?`<div class="section" style="margin:12px"><div style="padding:12px 14px 4px;color:#aaa;font-weight:700">已发送申请</div>${outgoing.map(r=>`<div class="it"><span>${esc(r.to_name||r.to_id)}</span><span class="v">等待通过</span></div>`).join('')}</div>`:''}
    <div class="section" style="margin:12px">
      <div class="it" onclick="phoneFriendCreateGroupModal()"><span style="display:inline-flex;align-items:center;gap:8px">${svgIc('users',18,'#c3c6d2')}新建小手机群</span><span class="v">›</span></div>
    </div>
    <div class="list">${pfGroupRowsHTML()}${pfFriendRowsHTML()||'<div class="empty" style="padding:24px;color:#888">还没有小手机好友<br>让对方把小手机ID发给你，或复制你的ID给对方</div>'}</div>
    <div style="height:30px"></div>
  </div>`;}
function renderPhoneFriendChat(id){const p=phoneFriendState();id=(''+id).toUpperCase();const f=phoneFriendById(id)||{phone_id:id,display_name:id,avatar:'🙂'};const arr=phoneFriendChatMessages(id);
  let body='';arr.forEach((m,i)=>{
    const prev=i?arr[i-1]:null;if(!prev||m.time-prev.time>300000)body+=`<div class="tstamp"><span>${hm(m.time)}</span></div>`;
    if(m.recalled){body+=pfRecalledRow();return;}
    const me=m.from===p.id,rs=me?pfReadStatus(m,'friend',id):'',rec=me?`<span class="pfrecall" onclick="event.stopPropagation();phoneFriendRecallMessage('${m.id}','friend','${id}')">撤回</span>`:'';
    body+=`<div class="msg ${me?'me':'them'}"><span>${me?av(S.me.avatar):pfAvatarHTML(f)}</span><div class="col">${pfBubblePart(m,me)}<div class="msgt">${rec}${rs?`<span style="margin-right:8px;color:#8d8d96">${rs}</span>`:''}${hm(m.time)}</div></div></div>`;
  });
  const gag=S.couple&&S.couple.gags&&S.couple.gags[pfGagKey(id)];
  return `<div class="nav"><span class="l" onclick="back()">‹</span><span class="t">${esc(pfFriendDisplayName(f))}</span><span class="r" onclick="phoneFriendManage('${id}')">⋯</span></div>
    <div class="chatbg" id="pfchatbg">${body||'<div class="empty" style="padding:40px;color:#888">你们已经是小手机好友了</div>'}</div>
    ${pfPanelHTML(id)}
    ${gag?`<div class="inputbar" style="justify-content:center;color:#fa9bb5;font-size:13px;padding:16px;text-align:center">🔇 ta把你和「${esc(pfFriendDisplayName(f))}」的聊天锁了，<span onclick="openCouple()" style="color:#ff6fa5;text-decoration:underline;cursor:pointer">去情侣空间查看</span></div>`:`<div class="inputbar"><span class="plus" style="background:transparent;box-shadow:none;color:#aaa" onclick="document.getElementById('pfpanel').classList.toggle('show')">＋</span><textarea id="pf_input" rows="1" placeholder="发消息…" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendPhoneFriend('${id}')}"></textarea><button class="send" onclick="sendPhoneFriend('${id}')" ${_pfSendBusy[id]?'disabled':''}>发送</button></div>`}`;}
function renderPhoneFriendGroup(gid){const g=pfGroupById(gid)||{name:'小手机群聊',members:[]};const p=phoneFriendState(),arr=pfGroupMessages(gid);
  let body='';arr.forEach((m,i)=>{
    const prev=i?arr[i-1]:null;if(!prev||m.time-prev.time>300000)body+=`<div class="tstamp"><span>${hm(m.time)}</span></div>`;
    if(m.recalled){body+=pfRecalledRow();return;}
    const pl=pfMsgPayload(m);if(pl&&pl.type==='pat'){body+=pfPatRow(m);return;}
    const me=m.from===p.id,sid=me?'me':(''+m.from).toUpperCase(),bs=pfGroupBubbleCfg(gid,sid),ac=bs&&bs.avatar==='round'?'av-round':'',ff=phoneFriendById(m.from),rs=me?pfReadStatus(m,'group',gid):'',rec=me?`<span class="pfrecall" onclick="event.stopPropagation();phoneFriendRecallMessage('${m.id}','group','${gid}')">撤回</span>`:'',at=me?'':`onpointerdown="pfAtStart(event,'${gid}','${m.from}')" onpointerup="pfGroupAvatarTap(event,'${gid}','${m.from}')" onpointercancel="pfAtEnd()" onpointerleave="pfAtEnd()" ondblclick="pfGroupAvatarDouble(event,'${gid}','${m.from}')" title="双击拍一拍，长按@"`;
    body+=`<div class="msg ${me?'me':'them'}"><span ${at}>${me?av(S.me.avatar,ac):pfAvatarHTML(ff||{phone_id:m.from,display_name:pfNameById(m.from)},ac)}</span><div class="col">${me?'':`<div style="font-size:11px;color:#888;margin:0 0 2px 4px">${esc(pfNameById(m.from)||'成员')}</div>`}${pfBubblePart(m,me,bs)}<div class="msgt">${rec}${rs?`<span style="margin-right:8px;color:#8d8d96">${rs}</span>`:''}${hm(m.time)}</div></div></div>`;
  });
  const gag=S.couple&&S.couple.gags&&S.couple.gags[pfgGagKey(gid)];
  return `<div class="nav"><span class="l" onclick="back()">‹</span><span class="t">${esc(pfGroupDisplayName(g))}</span><span class="r" onclick="phoneFriendGroupManage('${gid}')">⋯</span></div>
    <div class="chatbg" id="pfgroupbg">${body||'<div class="empty" style="padding:40px;color:#888">群聊已创建</div>'}</div>
    ${pfGroupPanelHTML(gid)}
    ${gag?`<div class="inputbar" style="justify-content:center;color:#fa9bb5;font-size:13px;padding:16px;text-align:center">🔇 ta把「${esc(pfGroupDisplayName(g))}」锁了，<span onclick="openCouple()" style="color:#ff6fa5;text-decoration:underline;cursor:pointer">去情侣空间查看</span></div>`:`<div class="inputbar"><span class="plus" style="background:transparent;box-shadow:none;color:#aaa" onclick="document.getElementById('pfgpanel').classList.toggle('show')">＋</span><textarea id="pfg_input" rows="1" placeholder="发群消息…" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendPhoneFriendGroup('${gid}')}"></textarea><button class="send" onclick="sendPhoneFriendGroup('${gid}')">发送</button></div>`}`;}

function wxChats(){
  const list=[...S.contacts].filter(c=>!c.deleted&&(isMain()||addedHere(c)||msgs(c.id).length)).sort((a,b)=>{
    if(a.pinned!==b.pinned)return a.pinned?-1:1;
    return (lastMsg(b.id)?.time||0)-(lastMsg(a.id)?.time||0);});
  const groups=isMain()?(S.groups||[]):[];
  const banner=isMain()?'':`<div style="padding:8px 12px;background:#3a2d4a;color:#d6c2f0;font-size:12px;text-align:center;display:flex;align-items:center;justify-content:center;gap:6px">${svgIc('idcard',14,'#d6c2f0')}当前身份：${esc(S.me.name)}（在「我」里可切换/搜微信号加人）</div>`;
  const searchbar=`<div onclick="openWxSearch()" style="margin:8px 12px;padding:8px 12px;background:${S.me.wxTheme==='white'?'#fff':'#1c1c1e'};border-radius:9px;color:#999;font-size:13px;display:flex;align-items:center;gap:6px;cursor:pointer">${svgIc('search',15,'#999')} 搜索聊天记录</div>`;
  const pfBlock=isMain()?(pfGroupRowsHTML()+pfFriendRowsHTML()):'';
  const roleRow=c=>{const lm=lastMsg(c.id);return `<div class="row ${c.pinned?'pin':''}" onclick="openChat('${c.id}')">${av(c.avatar)}
      <div class="meta"><div class="n">${esc(c.remark||c.name)} ${c.blocked?'<span class=tag>已拉黑</span>':''}</div>
      <div class="s">${lm?esc(previewOf(lm)):'打个招呼吧～'}</div></div>
      <div style="text-align:right"><div class="meta time">${lm?hm(lm.time):''}</div>${c.pinned?'<div style="font-size:10px;color:#ccc">置顶</div>':''}</div></div>`;};
  let html=banner+searchbar+'<div class="list">'+list.filter(c=>c.pinned).map(roleRow).join('')+pfBlock;
  groups.forEach(g=>{const lm=g.msgs[g.msgs.length-1];html+=`<div class="row" onclick="go('group',{id:'${g.id}'})">${g.avatar?av(g.avatar):'<div class="avatar" style="background:#7c6cc0">👥</div>'}<div class="meta"><div class="n">${esc(g.name)}(${g.members.length+1})</div><div class="s">${lm?esc(gpreview(lm,g)):'群聊已创建'}</div></div><div style="text-align:right"><div class="meta time">${lm?hm(lm.time):''}</div></div></div>`;});
  if(!list.length&&!groups.length&&!pfBlock)return banner+'<div class="empty">'+(isMain()?'欢迎来到 North～<br>右上角 ＋ 新建你的第一个角色就能开聊<br><br><button class="btn p" style="max-width:220px;margin:14px auto 0" onclick="showManual()">使用说明书</button>':'这个身份还没加谁～<br>去「通讯录」搜微信号加人')+'</div>';
  html+=list.filter(c=>!c.pinned).map(roleRow).join('');
  return html+'</div>';
}
function gpreview(m,g){const nm=gnm(g,m.senderId);return nm+'：'+gmText(m);}
function gmText(m){return m.type==='text'?m.content:m.type==='transfer'?'[转账]':m.type==='redpacket'?'[红包]':'[消息]';}
/* ===== 群聊 ===== */
function showManual(){openModal(`<h3>North · 使用说明书</h3>
  <div style="font-size:13.5px;line-height:1.95;color:#e6e6e6;max-height:62vh;overflow:auto;text-align:left">
    欢迎来玩～North 是一个能和你自己创建的角色用「微信」聊天的小手机。角色、聊天和设置主要保存在当前浏览器；开启真人好友或云同步时，对应内容会连接云端。<br><br>
    <b>① 先填接口（必做一次）</b><br>
    回主屏幕进「设置」，在「聊天模型」里填上你的 <b>API Key</b>（地址和模型名一般已经填好，不会就用默认的）。识图想用别的模型可以单独填。<br><br>
    <b>② 新建你的角色</b><br>
    进「微信」，点右上角 <b>＋ → 新建角色</b>。填好名字、头像、<b>人设</b>（越详细越像）、怎么称呼你、关系等，保存。<br><br>
    <b>③ 开始聊天</b><br>
    点进角色就能发消息，像真的微信一样。可以发文字、图片、语音、转账、发起语音/视频通话。<br><br>
    <b>④ 更多玩法</b><br>
    · 主屏幕第二页有：音乐一起听、云程、规则怪谈、惊悚抉择小游戏。<br>
    · 朋友圈、抖音、相册、备忘录、记账等小应用都能用。<br>
    · 绑定「情侣空间」后，恋人角色会解锁更多专属互动。<br>
    · 在「我」里可以改自己的资料、切换身份、导出/导入备份。<br><br>
    <b>⑤ API Key 常见报错（看数字就行）</b><br>
    · <b>400</b>：请求格式或模型名不兼容。先检查模型名有没有写错。<br>
    · <b>401</b>：密钥无效、过期或复制时带了空格。重新复制 Key。<br>
    · <b>402</b>：账户余额/点数不足，需要充值。<br>
    · <b>403</b>：密钥没有模型权限，或平台限制了地区/IP。<br>
    · <b>404</b>：<b>接口地址或模型名不存在</b>。地址通常要以 <b>/v1</b> 结尾，并确认平台真的提供这个模型。<br>
    · <b>408 / 超时</b>：网络或模型太慢，稍后重试或换模型。<br>
    · <b>429</b>：请求太频繁、并发受限或额度达到上限，等一会儿再试。<br>
    · <b>500</b>：平台服务端内部错误，不是你手机坏了。<br>
    · <b>501</b>：<b>这个接口没有实现当前功能</b>；常见于路径不对，或渠道不支持这个模型、生图/语音接口。<br>
    · <b>502 / 503 / 504</b>：上游故障、拥堵或超时，稍后重试或换线路。<br>
    · <b>Failed to fetch / Network / CORS</b>：网络没连上，或平台不允许网页直接调用。先确认网址能打开，再问平台是否支持网页跨域。<br><br>
    <b>⑥ 安卓黑屏 / 一直刷新不出来</b><br>
    1. 先等 10 秒，启动失败会出现中文修复页。<br>
    2. 点<b>「修复页面缓存后重开」</b>，这不会删除角色、聊天或密钥。<br>
    3. 仍不行：更新手机的 <b>Chrome</b> 和 <b>Android System WebView</b>，再用 Chrome 打开小手机网址。<br>
    4. 不要直接点“清除网站数据/清除存储”，那会删本机记录；能进入时先在「我」里导出备份。<br><br>
    <b>小提示</b>：换设备或清除网站数据可能会丢本机记录，记得偶尔在「我」里<b>导出备份</b>存好。玩得开心。
  </div>
  <div class="btns" style="margin-top:14px"><button class="btn p" onclick="closeModal()">开始玩吧</button></div>`);}
function maybeFirstRun(){try{if(!gateOK())return;if(localStorage.getItem('yibei_manual_seen'))return;
    const noContacts=!(S.contacts||[]).filter(c=>!c.deleted).length;
    const noKey=!(S.settings&&S.settings.chat&&S.settings.chat.key);
    if(noContacts&&noKey){localStorage.setItem('yibei_manual_seen','1');showManual();}}catch(e){}}
function showGate(){if(gateOK())return;let el=document.getElementById('gate');
  if(!el){el=document.createElement('div');el.id='gate';el.className='gate';document.body.appendChild(el);}
  el.innerHTML='<div class="glogo">'+svgIc('lock',30,'#fff')+'</div><h2>North</h2><p>请输入邀请码开始<br>（找邀请你的人要，一个码只能用一次）</p><input id="gateInp" inputmode="text" placeholder="邀请码" autocomplete="off"><button id="gateBtn">进入</button><div class="gerr" id="gateErr"></div>';
  const inp=document.getElementById('gateInp'),err=document.getElementById('gateErr'),btn=document.getElementById('gateBtn');
  const unlock=()=>{try{localStorage.setItem('yibei_unlocked',String(SHARE_EPOCH));}catch(e){}const g=document.getElementById('gate');if(g)g.remove();render();setTimeout(maybeFirstRun,400);};
  let _busy=false;
  const tryIn=async()=>{if(_busy)return;const v=(inp.value||'').trim();if(!v){err.textContent='请输入邀请码';inp.focus();return;}
    if(SHARE_PW&&v===SHARE_PW){unlock();return;}
    _busy=true;btn.disabled=true;btn.textContent='验证中…';err.textContent='';
    const res=await redeemInvite(v);
    _busy=false;btn.disabled=false;btn.textContent='进入';
    if(res.ok){unlock();}else{err.textContent=res.err||'邀请码无效或已被使用；换浏览器/清缓存需要新的未使用邀请码';inp.value='';inp.focus();}};
  btn.onclick=tryIn;
  inp.onkeydown=e=>{if(e.key==='Enter')tryIn();};
  setTimeout(()=>inp.focus(),100);}
function chatAddMenu(){openModal(`<h3>＋</h3>
  <button class="btn p" style="margin-bottom:8px" onclick="closeModal();editContact()">新建角色</button>
  <button class="btn g" onclick="closeModal();createGroup()">发起群聊</button>
  <button class="btn g" style="margin-top:8px" onclick="closeModal();showManual()">使用说明书</button>
  <button class="btn g" style="margin-top:8px" onclick="closeModal()">取消</button>`);}
function createGroup(){const cs=S.contacts.filter(c=>!c.deleted);if(cs.length<1){toast('先创建角色');return;}
  window._gsel=[];openModal(`<h3>发起群聊</h3><div class="hint">选要拉进群的角色（可多选）</div>
    <div id="gpick">${cs.map(c=>`<div class="section"><div class="it" onclick="gtoggle('${c.id}',this)">${esc(c.remark||c.name)}<span class="v" id="gp_${c.id}">＋</span></div></div>`).join('')}</div>
    <div class="field"><label>群名称</label><input id="g_name" placeholder="例如：我的后宫团"></div>
    <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="doCreateGroup()">创建</button></div>`);}
function gtoggle(id){const i=window._gsel.indexOf(id);if(i<0)window._gsel.push(id);else window._gsel.splice(i,1);const e=$('#gp_'+id);if(e)e.textContent=i<0?'✓':'＋';}
function doCreateGroup(){if(!window._gsel||!window._gsel.length){toast('至少选一个角色');return;}
  const nm=($('#g_name').value||'').trim()||(window._gsel.map(id=>getC(id).name).slice(0,3).join('、')+'的群');
  const g={id:'g'+uid(),name:nm,members:window._gsel.slice(),msgs:[]};S.groups.unshift(g);save();closeModal();go('group',{id:g.id});}
function renderGroup(id){const g=S.groups.find(x=>x.id===id);if(!g)return '';
  if(S.wxLogin){if(Date.now()>=S.wxLogin.until)setTimeout(wxLogout,0);else{if(!_wxLoginTimer)wxLoginStartTimer();return wxLockedScreen();}}
  g.msgs.forEach(m=>{if(!m.id)m.id=uid();});
  let body='';g.msgs.forEach((m,i)=>{if(i===0||m.time-g.msgs[i-1].time>300000)body+=`<div class="tstamp"><span>${hm(m.time)}</span></div>`;body+=gbubble(g,m);});
  const sel=_gmsel&&_gmsel.id===id;
  const panel=`<div class="panel" id="gpanel"><div class="pgrid">
      <div class="it" onclick="document.getElementById('gpanel').classList.remove('show');groupSendCard('${id}','redpacket')"><div class="b">${svgIc('redpacket',26,'#e6e6ee')}</div><span>红包</span></div>
      <div class="it" onclick="document.getElementById('gpanel').classList.remove('show');groupSendCard('${id}','transfer')"><div class="b">${svgIc('money',26,'#e6e6ee')}</div><span>转账</span></div>
      <div class="it" onclick="document.getElementById('gpanel').classList.remove('show');groupAt('${id}')"><div class="b" style="font-size:24px;color:#e6e6ee">@</div><span>提到谁</span></div>
      <div class="it" onclick="enterGSelect('${id}')"><div class="b">${svgIc('forward',26,'#e6e6ee')}</div><span>多选转发</span></div>
    </div></div>`;
  const inbar=sel
    ?`<div class="inputbar"><button class="btn g" style="flex:1" onclick="exitGSelect()">取消</button><button class="btn d" style="flex:1" onclick="gDelSelected('${id}')">删除(<span id="gfwdcnt">${_gmsel.ids.length}</span>)</button><button class="btn p" style="flex:1" onclick="gForwardSelected('${id}')">转发</button></div>`
    :`<div class="inputbar"><span class="plus" style="background:transparent;box-shadow:none;color:#aaa" onclick="document.getElementById('gpanel').classList.toggle('show')">＋</span>
      <textarea id="ginput" rows="1" placeholder="群里说点啥…"></textarea>
      <button class="send" onclick="sendGroup('${id}')">发送</button></div>`;
  return `<div class="nav"><span class="l" onclick="back()">‹</span><span class="t">${esc(g.name)}(${g.members.length+1})</span><span class="r" onclick="groupInfo('${id}')">⋯</span></div>
    <div class="chatbg" id="chatbg">${body}</div>
    ${panel}
    ${inbar}`;}
function gMsgMenu(gid,mid){const g=S.groups.find(x=>x.id===gid);if(!g)return;const m=g.msgs.find(x=>x.id===mid);if(!m||m.type==='sys')return;const me=m.senderId==='me';
  openModal(`<h3>消息操作</h3>
   <button class="btn g" style="margin-bottom:8px" onclick="gForwardOne('${gid}','${mid}')">↗️ 转发</button>
   ${me?`<button class="btn d" style="margin-bottom:8px" onclick="gRecallMsg('${gid}','${mid}')">↩️ 撤回</button>`:''}
   <button class="btn d" style="margin-bottom:8px" onclick="gDelOne('${gid}','${mid}')">删除这条</button>
   <button class="btn p" style="margin-bottom:8px" onclick="closeModal();enterGSelect('${gid}')">多选</button>
   <button class="btn g" onclick="closeModal()">取消</button>`);}
function gDelOne(gid,mid){const g=S.groups.find(x=>x.id===gid);if(!g)return;g.msgs=g.msgs.filter(m=>m.id!==mid);save();closeModal();render();toast('已删除');}
function gRecallMsg(gid,mid){const g=S.groups.find(x=>x.id===gid);if(!g)return;const i=g.msgs.findIndex(m=>m.id===mid);if(i<0)return;const me=g.msgs[i].senderId==='me';g.msgs[i]={senderId:'me',role:'user',type:'sys',content:(me?'你':'对方')+'撤回了一条消息',time:g.msgs[i].time,id:mid};save();closeModal();render();}
function enterGSelect(id){_gmsel={id,ids:[]};const p=document.getElementById('gpanel');if(p)p.classList.remove('show');try{closeModal();}catch(e){}render();}
function exitGSelect(){_gmsel=null;render();}
function gToggleSel(mid){if(!_gmsel)return;const i=_gmsel.ids.indexOf(mid);if(i<0)_gmsel.ids.push(mid);else _gmsel.ids.splice(i,1);render();}
async function gDelSelected(id){if(!_gmsel||!_gmsel.ids.length){toast('先选几条');return;}if(!await uiConfirm('删除选中的 '+_gmsel.ids.length+' 条？'))return;const g=S.groups.find(x=>x.id===id);if(g)g.msgs=g.msgs.filter(m=>_gmsel.ids.indexOf(m.id)<0);_gmsel=null;save();render();toast('已删除');}
function gForwardOne(gid,mid){closeModal();_gfwd={gid,ids:[mid]};pickTarget(gDoForward);}
function gForwardSelected(id){if(!_gmsel||!_gmsel.ids.length){toast('先选几条');return;}_gfwd={gid:id,ids:_gmsel.ids.slice()};pickTarget(gDoForward);}
function gDoForward(toId){if(!_gfwd)return;const g=S.groups.find(x=>x.id===_gfwd.gid);const c=getC(toId);if(!g||!c){_gfwd=null;return;}
  const picked=g.msgs.filter(m=>_gfwd.ids.indexOf(m.id)>=0&&m.type!=='sys');
  const lines=picked.map(m=>({who:m.senderId==='me'?S.me.name:(getC(m.senderId)?getC(m.senderId).name:'?'),text:gmText(m)}));
  if(!lines.length){toast('没有可转发的内容');_gfwd=null;return;}
  msgs(toId).push({role:'user',type:'chatlog',title:'群聊「'+g.name+'」的聊天记录',lines,time:Date.now(),id:uid()});
  _gfwd=null;_gmsel=null;save();toast('已转发给 '+(c.remark||c.name));openChat(toId);scheduleReply(toId);}
function groupSendCard(id,type){const g=S.groups.find(x=>x.id===id);if(!g){closeModal();return;}
  const v=prompt(type==='redpacket'?'发个群红包，金额：':'转账金额：',type==='redpacket'?'5.20':'13.14');if(v==null){closeModal();return;}
  const amt=Math.max(0,+v||0);if(!amt){toast('金额填错了');return;}
  if(amt>S.me.balance){toast('余额不够哦💸');return;}
  const note=(prompt('附言（可空）：',type==='redpacket'?'恭喜发财，大吉大利':'给你～')||'').trim();
  addBill('out',amt,'群里'+(type==='redpacket'?'发红包':'转账'));
  g.msgs.push({senderId:'me',role:'user',type,amount:amt,note,time:Date.now(),id:uid(),received:false});save();closeModal();render();
  toast((type==='redpacket'?'🧧 红包':'💸 转账')+'已发出 ¥'+amt.toFixed(2));aiGroupReply(id,'');}
async function clearGroupMsgs(id){const g=S.groups.find(x=>x.id===id);if(!g)return;if(!await uiConfirm('清空这个群的全部聊天记录？'))return;g.msgs=[];save();closeModal();render();toast('已清空群聊');}
function gPat(gid,sid){if(sid==='me')return;const g=S.groups.find(x=>x.id===gid);const c=getC(sid);if(!g||!c)return;
  g.msgs.push({senderId:'me',role:'user',type:'sys',content:'你拍了拍「'+(c.remark||c.name)+'」',time:Date.now(),id:uid()});save();render();aiGroupReply(gid,c.name);}
function groupRels(id){const g=S.groups.find(x=>x.id===id);if(!g)return;g.rels=g.rels||[];_grelGid=id;
  const people=[['me',S.me.name]].concat(g.members.map(cid=>{const c=getC(cid);return c?[cid,(c.remark||c.name)]:null;}).filter(Boolean));
  const opt=()=>people.map(p=>`<option value="${p[0]}">${esc(p[1])}</option>`).join('');
  const chips=()=>people.map(p=>`<span class="minibtn" onclick="grelChip('${p[0]}')" style="margin:2px;background:${_grelPick.indexOf(p[0])>=0?'#19a463':'#2c2c2e'};color:${_grelPick.indexOf(p[0])>=0?'#fff':'#ccc'}">${esc(p[1])}</span>`).join('');
  const arrow={'1v1':'↔','1vN':'→','Nv1':'→'};
  const relRows=g.rels.length?g.rels.map((r,i)=>{const aN=Array.isArray(r.a)?r.a.map(grelName).join('、'):grelName(r.a);const bN=Array.isArray(r.b)?r.b.map(grelName).join('、'):grelName(r.b);
    return `<div class="section" style="margin-bottom:6px"><div class="it" onclick="(function(){var d=document.getElementById('reld_${i}');if(d)d.style.display=d.style.display==='none'?'block':'none';})()"><span style="flex:1;font-size:14px">${esc(aN)} ${arrow[r.mode]||'↔'} ${esc(bN)} <span style="color:#19a463;font-size:12px;background:rgba(25,164,99,.18);border-radius:6px;padding:1px 7px">${esc(r.rel||'')}</span></span><span class="v">⌄</span></div><div id="reld_${i}" style="display:none;padding:6px 14px 10px;font-size:12px;color:#999">${r.story?esc(r.story)+'<br>':''}<span onclick="grelDel('${id}',${i})" style="color:#fa5151;cursor:pointer">🗑 删除这条关系</span></div></div>`;}).join(''):'<div class="hint" style="padding:6px 0">还没设关系，下面加一条～</div>';
  let picker;
  if(_grelMode==='1v1')picker=`<div class="two"><div class="field"><select id="grel_a" style="width:100%;border:1px solid #38383a;border-radius:8px;padding:8px;background:#2c2c2e;color:#eee">${opt()}</select></div><div class="field"><select id="grel_b" style="width:100%;border:1px solid #38383a;border-radius:8px;padding:8px;background:#2c2c2e;color:#eee">${opt()}</select></div></div>`;
  else if(_grelMode==='1vN')picker=`<div class="field"><label>谁</label><select id="grel_a" style="width:100%;border:1px solid #38383a;border-radius:8px;padding:8px;background:#2c2c2e;color:#eee">${opt()}</select></div><div class="field"><label>对这些人（点选可多选）</label><div>${chips()}</div></div>`;
  else picker=`<div class="field"><label>这些人（点选可多选）</label><div>${chips()}</div></div><div class="field"><label>对谁</label><select id="grel_b" style="width:100%;border:1px solid #38383a;border-radius:8px;padding:8px;background:#2c2c2e;color:#eee">${opt()}</select></div>`;
  openModal(`<h3>群关系网</h3><div class="hint">关系网每次 AI 回复前必读，帮 AI 理解群内人物关系。直接选人物，不用手写名字。</div>
   ${relRows}
   <div class="section" style="margin-top:10px;padding:12px"><div style="font-weight:600;margin-bottom:8px">添加关系</div>
   <div style="display:flex;gap:6px;margin-bottom:10px">${[['1v1','单对单'],['1vN','1对多'],['Nv1','多对1']].map(m=>`<button class="minibtn" style="flex:1;background:${_grelMode===m[0]?'#19a463':'#2c2c2e'};color:${_grelMode===m[0]?'#fff':'#ccc'}" onclick="_grelMode='${m[0]}';_grelPick=[];groupRels('${id}')">${m[1]}</button>`).join('')}</div>
   ${picker}
   <div class="field"><input id="grel_rel" placeholder="关系（如：情侣、闺蜜、死对头、上司）"></div>
   <div class="field"><textarea id="grel_story" rows="2" placeholder="故事设定（选填，两人之间的背景故事）"></textarea></div>
   <button class="btn p" onclick="grelAdd('${id}')">＋ 添加关系</button></div>
   <button class="btn g" style="margin-top:8px" onclick="closeModal()">关闭</button>`);}
function grelChip(k){const i=_grelPick.indexOf(k);if(i<0)_grelPick.push(k);else _grelPick.splice(i,1);if(_grelGid)groupRels(_grelGid);}
function grelAdd(id){const g=S.groups.find(x=>x.id===id);if(!g)return;g.rels=g.rels||[];const rel=($('#grel_rel').value||'').trim();if(!rel){toast('填一下是什么关系');return;}const story=($('#grel_story').value||'').trim();let a,b;
  if(_grelMode==='1v1'){a=$('#grel_a').value;b=$('#grel_b').value;if(a===b){toast('选两个不同的人');return;}}
  else if(_grelMode==='1vN'){a=$('#grel_a').value;b=_grelPick.filter(x=>x!==a);if(!b.length){toast('给"多"的一方点选几个人');return;}}
  else{b=$('#grel_b').value;a=_grelPick.filter(x=>x!==b);if(!a.length){toast('给"多"的一方点选几个人');return;}}
  g.rels.push({mode:_grelMode,a,b,rel,story});_grelPick=[];save();groupRels(id);toast('已添加关系');}
function grelDel(id,i){const g=S.groups.find(x=>x.id===id);if(!g||!g.rels)return;g.rels.splice(i,1);save();groupRels(id);}
function gbubble(g,m){const me=m.senderId==='me';if(m.type==='sys')return `<div class="tstamp"><span>${esc(m.content)}</span></div>`;
  const c=me?null:getC(m.senderId),_gbl=groupBubbleLook(g,m.senderId),_gbi=groupBubbleIcon(g,m.senderId),_gav=groupBubbleAvatarClass(g,m.senderId);const av0=me?av(S.me.avatar,_gav):`<span onclick="event.stopPropagation();gPat('${g.id}','${m.senderId}')" style="cursor:pointer" title="拍一拍">${av(c?c.avatar:'🙂',_gav)}</span>`;const nm=me?'':`<div style="font-size:11px;color:#888;margin-bottom:2px">${esc(gnm(g,m.senderId))}</div>`;
  const q=m.q?`<div style="background:rgba(120,120,130,.2);border-left:2px solid #999;border-radius:5px;padding:3px 8px;margin-bottom:3px;font-size:11px;color:#999;max-width:210px;${me?'margin-left:auto':''}">${esc(m.q.who)}：${esc((m.q.text||'').slice(0,30))}</div>`:'';
  let inner;
  if(m.type==='transfer'||m.type==='redpacket'){const rp=m.type==='redpacket';const got=m.received;
    inner=`<div class="card"${me?'':` style="cursor:pointer" onclick="event.stopPropagation();gGrab('${g.id}','${m.id}')"`}><div class="cpay" style="background:${rp?(got?'#caa15a':'#f0a73b'):(got?'#7fae8f':'#36b06a')}"><div class="big">${svgIc(rp?'redpacket':'money',30,'#fff')}</div><div><div class="t1">¥${(+m.amount).toFixed(2)}</div><div class="t2">${esc(m.note||(rp?'恭喜发财':'给你转账'))}</div></div></div><div class="cfoot">${me?'已发出':(got?'已领取':(rp?'点击领取红包':'点击收款'))}</div></div>`;
  }else inner=`${q}<div class="bubble${_gbl.cls}"${_gbl.css?` style="${_gbl.css}"`:''}>${_gbi}${esc(m.content)}</div>`;
  const selecting=_gmsel&&_gmsel.id===g.id;
  const tick=selecting?`<span style="align-self:center;font-size:20px;margin:0 4px;color:${_gmsel.ids.includes(m.id)?'#07c160':'#666'}">${_gmsel.ids.includes(m.id)?'☑':'⚪'}</span>`:'';
  const click=selecting?`onclick="gToggleSel('${m.id}')"`:`onclick="gMsgMenu('${g.id}','${m.id}')"`;
  return `<div class="msg ${me?'me':'them'}" ${click} style="cursor:pointer">${selecting&&me?tick:''}${av0}<div class="col">${nm}${inner}<div class="msgt">${hm(m.time)}</div></div>${selecting&&!me?tick:''}</div>`;}
function gGrab(gid,mid){const g=S.groups.find(x=>x.id===gid);if(!g)return;const m=g.msgs.find(x=>x.id===mid);if(!m||m.received||(m.type!=='transfer'&&m.type!=='redpacket'))return;
  m.received=true;const nm=getC(m.senderId)?getC(m.senderId).name:'群友';addBill('in',+m.amount||0,nm+(m.type==='redpacket'?'的群红包':'的群转账'));save();render();toast('已领取 ¥'+(+m.amount).toFixed(2)+' 💰');}
function gNotify(g,c){if(cur().p==='group'&&cur().id===g.id)return;playDing();const lm=g.msgs[g.msgs.length-1],line=gnm(g,c.id)+'：'+(lm?gmText(lm):'');lockNotify(g.name,line,{avatar:g.avatar,icon:'users',target:{type:'group',id:g.id}});appNotify(g.name,line,{tag:'group-'+g.id,data:{type:'open',target:'group',id:g.id}});if(lockVisible())return;const b=$('#msgBanner');if(!b)return;
  b.innerHTML=`${g.avatar?av(g.avatar,'sm'):'<div class="avatar sm" style="background:#7c6cc0">👥</div>'}<div style="flex:1;min-width:0"><div class="bn">${esc(g.name)}</div><div class="bm">${esc(gnm(g,c.id)+'：'+(lm?gmText(lm):''))}</div></div>`;
  b.className='msgbanner show';b.onclick=()=>{b.className='msgbanner';go('group',{id:g.id});};clearTimeout(_bannerT);_bannerT=setTimeout(()=>{b.className='msgbanner';},4500);}
function sendGroup(id){const g=S.groups.find(x=>x.id===id);const ta=$('#ginput');const t=ta.value.trim();if(!t)return;ta.value='';ta.style.height='auto';
  g.msgs.push({senderId:'me',role:'user',type:'text',content:t,time:Date.now(),id:uid()});save();render();aiGroupReply(id,t);}
function groupAt(id){const g=S.groups.find(x=>x.id===id);openModal(`<h3>@ 谁</h3>${g.members.map(cid=>{const c=getC(cid);return c?`<div class="section"><div class="it" onclick="closeModal();var ta=$('#ginput');ta.value+='@${esc(c.name)} ';ta.focus()">${esc(c.name)}</div></div>`:'';}).join('')}<button class="btn g" style="margin-top:8px" onclick="closeModal()">关闭</button>`);}
// 群昵称：优先用群里设置的昵称，没有才用本名
function gnm(g,sid){const nk=g&&g.nicks&&g.nicks[sid];if(nk)return nk;if(sid==='me')return S.me.name;const c=getC(sid);return c?c.name:'?';}
function gName(m,g){return gnm(g,m.senderId);}
let _grelMode='1v1',_grelPick=[],_grelGid=null;
function grelName(k){return k==='me'?S.me.name:((getC(k)||{}).remark||(getC(k)||{}).name||'?');}
function relToText(r){const aN=Array.isArray(r.a)?r.a.map(grelName).join('、'):grelName(r.a);const bN=Array.isArray(r.b)?r.b.map(grelName).join('、'):grelName(r.b);return aN+(r.mode==='1v1'?' 和 ':' 对 ')+bN+' 是 '+r.rel+(r.story?'（背景：'+r.story+'）':'');}
function gContext(g,c,recent){const others=g.members.filter(x=>x!==c.id&&getC(x)).map(x=>gnm(g,x));
  recent=recent||g.msgs.slice(-14);
  const _myNick=(g.nicks&&g.nicks[c.id])||'';
  let s='\n\n# 你在群聊「'+g.name+'」里\n群里有：'+gnm(g,'me')+'(你们共同的恋人/主人)、'+others.join('、')+'。这是真实的多人群聊。'
   +(_myNick?'\n（你在这个群里的群昵称是「'+_myNick+'」，大家看到的你就是这个名字。）':'')
   +'\n- 你可以随心情【改自己在这个群里的群昵称】增加趣味：单独一行 [群昵称|新昵称]（比如改成搞怪的、或宣示主权的），改不改看你心情、别频繁乱改。这行不会被当成消息发出来。\n'
   +'- 你能看到上面【所有人】说的话，包括其他群友彼此之间的对话。要像真群聊那样：可以接群友的话、附和、拌嘴、调侃、起哄、吃醋——【不要每个人都只对着'+S.me.name+'说话】，不要和别人说一样的话、不要复读别人。\n'
   +'- 【绝对不要用 @某人】这种格式。想专门回应某一条消息，就在你那句话【前面单独占一行】写 [引用|序号]（序号见下面群记录），引用'+S.me.name+'的或别的群友的都行；不是每句都要引用，一次最多引用一两条。\n'
   +'- 【你引用谁、就是在对谁说话】：如果你 [引用] 的是【另一个群友】说的话，那你这句就是【冲着那个群友】说的——按你和ta的关系来（怼ta、附和ta、阴阳怪气、跟ta争风吃醋抢'+S.me.name+'都行），【不是】在对'+S.me.name+'说话，别把对群友说的话说得像在哄'+S.me.name+'。只有当你引用'+S.me.name+'、或者没引用谁时，才是在跟'+S.me.name+'说话。\n'
   +'- 像真人发微信，这次只回【1 到 2 条】短消息，每条单独占一行；可以只回一条，话不投机也可以就接一句，别凑数、别每个人都发一样多。\n'
   +'- 想发红包/转账（讨好'+S.me.name+'或跟群友斗富）就单独一行 [红包|金额|祝福语] 或 [转账|金额|说明]，金额自己定、别滥发。\n'
   +'- 口语、自然、有情绪，符合你的人设和心情值。';
  {let relTxt=(g.rels&&g.rels.length)?g.rels.map(relToText).join('\n'):'';if(g.relations)relTxt+=(relTxt?'\n':'')+g.relations;if(relTxt)s+='\n# 群里的人物关系（必读，严格按这些关系来理解谁跟谁、谁对谁是什么态度）\n'+relTxt;}
  s+='\n# 最近群聊记录（带序号，引用时用这个号）\n'+(recent.length?recent.map((m,i)=>'['+(i+1)+'] '+gName(m,g)+'：'+gmText(m)).join('\n'):'（还没人说话）');
  return s;}
// 把群回复解析成「一条条」的消息项（文字气泡 + 红包/转账卡片），文字条数封顶
function gParseReply(content,cap,recent,g){const out=[];let txt=0;let pq=null;
  splitBubbles(content).forEach(l=>{l=normTag(l);if(!l)return;
    let qm=l.match(/^\[\s*引用\s*[|｜:：]?\s*(\d{1,2})\s*\]$/);if(qm){const rm=recent&&recent[+qm[1]-1];if(rm)pq={who:gName(rm,g),text:(gmText(rm)||'').slice(0,30)};return;}
    let m=l.match(/^\[\s*转账\s*\|\s*([0-9.]+)\s*\|?\s*([^\]]*)\]$/);if(m){out.push({type:'transfer',amount:+m[1]||0,note:(m[2]||'').trim(),received:false});return;}
    m=l.match(/^\[\s*红包\s*\|\s*([0-9.]+)\s*\|?\s*([^\]]*)\]$/);if(m){out.push({type:'redpacket',amount:+m[1]||0,note:(m[2]||'').trim(),received:false});return;}
    if(LEAKRE.test(l))return;// 别把别的指令标签当消息发出来
    splitActions(l).forEach(p=>{if(txt>=cap)return;p=(p||'').replace(/^(@[^\s@]+\s*)+/,'').trim();if(!p||/^@\S+$/.test(p))return;/* 丢掉纯@xxx气泡 */const it={type:'text',content:p};if(pq){it.q=pq;pq=null;}out.push(it);txt++;});
  });
  return out;}
async function aiGroupReply(id,fromText){const g=S.groups.find(x=>x.id===id);if(!g)return;
  const allowed=(g.responders&&g.responders.length)?g.responders:g.members;
  const members=allowed.map(x=>getC(x)).filter(c=>c&&!c.deleted&&!c.blocked);if(!members.length)return;
  // 被@到的先回；选中的(没选=全部)每个人都至少回一条，其余顺序打乱
  const atd=members.filter(c=>fromText&&fromText.includes(c.name));
  const rest=members.filter(c=>atd.indexOf(c)<0).sort(()=>Math.random()-.5);
  const resp=[...atd,...rest];
  const cap=Math.max(1,+g.msgMax||2);const lo=Math.max(1,+g.msgMin||1);
  for(const c of resp){await sleep(500+Math.random()*750);
    try{const recent=g.msgs.slice(-14);const sys=buildSystem(c)+gContext(g,c,recent);
      const pcap=Math.max(1,Math.min(cap,lo+Math.floor(Math.random()*(cap-lo+1))));// 每人这轮回几条随机，更自然
      let content=await chatAPI([{role:'system',content:sys},{role:'user',content:'[轮到你在群里说话了。看看上面大家（包括其他群友互相）说了啥，自然接话——回'+S.me.name+'、或接群友的话拌嘴起哄都行。要专门回应某条就用 [引用|序号]，别@人、别跟别人说一样的话。只回 1 到 2 条短消息。]'}],{max:380});
      // 他改自己的群昵称
      content=content.replace(/[\[【]\s*群昵称\s*[\|｜:：]\s*([^\]】]{1,16})[\]】]/g,(mm,nn)=>{const nv=(nn||'').trim();if(nv){g.nicks=g.nicks||{};g.nicks[c.id]=nv;save();}return '';});
      let items=gParseReply(content,pcap,recent,g);
      if(!items.length)continue;// 没内容就这轮不吭声，更像真人
      let first=true;
      for(const it of items){
        if(!first)await sleep(420+Math.random()*560);first=false;
        it.senderId=c.id;it.role='assistant';it.time=Date.now();it.id=uid();g.msgs.push(it);save();
        if(S.settings.sound&&!c.muted)playDing();// 每条群消息都有提示音
        if(cur().p==='group'&&cur().id===id){const cb=$('#chatbg');if(cb){const stick=nearBottom(cb);cb.insertAdjacentHTML('beforeend',gbubble(g,it));if(stick)cb.scrollTop=cb.scrollHeight;}}
      }
      gNotify(g,c);
    }catch(e){}}}
function groupInfo(id){const g=S.groups.find(x=>x.id===id);const resp=g.responders||g.members.slice();
  openModal(`<h3>群设置</h3>
  <div class="field"><label>群头像</label><div class="avline">${g.avatar?av(g.avatar,'sm'):'<div class="avatar sm" style="background:#7c6cc0">👥</div>'}<button class="minibtn" onclick="gAvatar('${id}')">从相册选</button></div></div>
  <div class="field"><label>群名称</label><input id="gn" value="${esc(g.name)}"></div>
  <div class="field"><label>谁会回复（不选=全部都回）</label><div id="grsp">${g.members.map(cid=>{const c=getC(cid);return c?`<span class="minibtn" id="gr_${cid}" style="margin:2px;background:${resp.indexOf(cid)>=0?'#07c160':'#2c2c2e'};color:${resp.indexOf(cid)>=0?'#fff':'#ccc'}" onclick="gToggleResp('${id}','${cid}',this)">${esc(c.name)}</span>`:'';}).join('')}</div></div>
  <div class="two"><div class="field"><label>每人回复最少</label><input id="g_min" type="number" min="1" value="${g.msgMin||1}"></div><div class="field"><label>最多</label><input id="g_max" type="number" min="1" value="${g.msgMax||2}"></div></div>
  <div class="field"><label>群昵称（留空=用本名；角色也会自己改着玩）</label>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:5px"><span style="width:64px;flex:0 0 auto;font-size:13px;color:#bbb">${esc(S.me.name)}(我)</span><input id="gnick_me" value="${esc((g.nicks&&g.nicks.me)||'')}" placeholder="我的群昵称" style="flex:1"></div>
    ${g.members.map(cid=>{const c=getC(cid);return c?`<div style="display:flex;align-items:center;gap:8px;margin-bottom:5px"><span style="width:64px;flex:0 0 auto;font-size:13px;color:#bbb;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(c.name)}</span><input id="gnick_${cid}" value="${esc((g.nicks&&g.nicks[cid])||'')}" placeholder="ta的群昵称" style="flex:1"></div>`:'';}).join('')}
  </div>
  <button class="btn p" style="margin-bottom:8px;background:#7d688f" onclick="closeModal();groupBubbleList('${id}')">群聊气泡美化（每个人单独设置）</button>
  <button class="btn p" style="margin-bottom:8px;background:#19a463" onclick="closeModal();groupRels('${id}')">群关系网（结构化设置·谁和谁什么关系）</button>
  <div class="field"><label>补充关系（自由文字，选填）</label><textarea id="g_rel" rows="2" placeholder="也可以直接打一段，例如：两个人是死对头，都喜欢同一个人。">${esc(g.relations||'')}</textarea></div>
  <button class="btn p" style="margin-bottom:8px" onclick="saveGroup('${id}')">保存设置</button>
  <button class="btn g" style="margin-bottom:8px" onclick="g_addMember('${id}')">＋ 拉人进群</button>
  <button class="btn g" style="margin-bottom:8px" onclick="clearGroupMsgs('${id}')">清空群聊记录</button>
  <button class="btn d" onclick="askConfirm('解散群聊？',()=>{S.groups=S.groups.filter(x=>x.id!=='${id}');save();closeModal();back()},{danger:true})">解散群聊</button>
  <button class="btn g" style="margin-top:8px" onclick="closeModal()">关闭</button>`);}
function gToggleResp(gid,cid,el){const g=S.groups.find(x=>x.id===gid);g.responders=g.responders||g.members.slice();const i=g.responders.indexOf(cid);if(i>=0)g.responders.splice(i,1);else g.responders.push(cid);const on=g.responders.indexOf(cid)>=0;el.style.background=on?'#07c160':'#2c2c2e';el.style.color=on?'#fff':'#ccc';}
function gAvatar(id){pickFile('image/*',async f=>{const g=S.groups.find(x=>x.id===id);g.avatar=await compress(f,256,.8);save();groupInfo(id);});}
function saveGroup(id){const g=S.groups.find(x=>x.id===id);g.name=$('#gn').value.trim()||g.name;g.msgMin=Math.max(1,+$('#g_min').value||1);g.msgMax=Math.max(g.msgMin,+$('#g_max').value||2);g.relations=$('#g_rel').value.trim();
  g.nicks=g.nicks||{};{const mv=($('#gnick_me')||{}).value;if(mv!=null){const v=mv.trim().slice(0,16);if(v)g.nicks.me=v;else delete g.nicks.me;}g.members.forEach(cid=>{const el=$('#gnick_'+cid);if(el){const v=(el.value||'').trim().slice(0,16);if(v)g.nicks[cid]=v;else delete g.nicks[cid];}});}
  save();closeModal();render();toast('已保存');}
function g_addMember(id){const g=S.groups.find(x=>x.id===id);const avail=S.contacts.filter(c=>!c.deleted&&g.members.indexOf(c.id)<0);if(!avail.length){toast('没有可拉的角色了');return;}
  openModal(`<h3>拉人进群</h3>${avail.map(c=>`<div class="section"><div class="it" onclick="S.groups.find(x=>x.id==='${id}').members.push('${c.id}');S.groups.find(x=>x.id==='${id}').msgs.push({senderId:'me',type:'sys',content:'${esc(c.name)} 加入了群聊',time:Date.now(),id:uid()});save();closeModal();render()">${esc(c.remark||c.name)}<span class="v">＋</span></div></div>`).join('')}<button class="btn g" style="margin-top:8px" onclick="closeModal()">关闭</button>`);}
