      if((m=l.match(/^[\[【]\s*改备注\s*[\|｜:：]\s*([^\]】]{1,16})[\]】]$/))){const nv=m[1].trim();if(nv&&Date.now()-(c._remarkAt||0)>2.5*86400000){c.remark=nv;c._remarkAt=Date.now();wxLoginRecordAction(c,'remark','自己','把备注改成「'+nv+'」');S.wxLogin.did=S.wxLogin.did||[];S.wxLogin.did.push('你把自己的备注改成了「'+nv+'」');}return;}
