function applyAuxTags(content,c,id){try{consumeMomentCommands(content,c,{toast:false});const sp=(content.match(/(?:密码|password|密碼)\D{0,8}(\d{4})/i)||[])[1]||null;applyControlTags(content,c,id,sp);applyGrudgeTags(content,c);applyStarTags(content);}catch(e){}}
// 处理"上锁/禁言"控制指令：无论写在哪都强制生效，并从文本里抹掉（不显示、无系统提示）
function applyControlTags(content,c,id,statedPwd){
  if(!content||!(S.couple&&S.couple.cid===c.id))return content;
  _collarTagFired=false;
  // 他凭自己心意改手机密码：[改密码] 随机换 / [改密码|1234] 指定
  content=content.replace(/[\[【]\s*改密码\s*(?:[\|｜:：]\s*(\d{4}))?\s*[\]】]/g,(mm,nn)=>{const sp=getSpy(c);sp.pwd=(nn&&/^\d{4}$/.test(nn))?nn:String(1000+Math.floor(Math.random()*9000));if(typeof _spyUnlock!=='undefined')_spyUnlock[c.id]=false;save();return '';});
  content=content.replace(/[\[【]\s*登录微信\s*[\]】]/g,()=>{if(S.couple.wxLoginAuth&&!wxLoginActive()&&!(typeof _call!=='undefined'&&_call))setTimeout(()=>wxDoLogin(c.id),300);return '';});
  const gr=S.couple.grant||{},gauth=S.couple.gagAuth||[];let changed=false;const np=()=>statedPwd||genPwd();
  let out=content.replace(/[\[【]\s*(锁定|上锁|解锁|禁言|解禁|限时|加时)\s*[\|｜:：]\s*([^\]】]*)[\]】]/g,(mm,act,arg)=>{
    arg=(arg||'').replace(/[「」『』"'《》]/g,'').trim();changed=true;
    if(act==='锁定'||act==='上锁'){let keys=_appKeys(arg,Object.keys(LOCKABLE),k=>gr[k]);keys=[...new Set(keys)].filter(k=>!(S.couple.locks&&S.couple.locks[k]));if(keys.length){S.couple.locks=S.couple.locks||{};const pwd=np();keys.forEach(k=>S.couple.locks[k]={pwd,time:Date.now()});}}
    else if(act==='限时'){const parts=arg.split(/[\|｜、,，\s]+/).filter(Boolean);const mins=parseInt((parts.find(p=>/\d/.test(p))||'').replace(/[^\d]/g,''),10);const nmPart=parts.filter(p=>!/^\d+$/.test(p)).join('、');let keys=_appKeys(nmPart||arg,Object.keys(LOCKABLE),k=>gr[k]);keys=[...new Set(keys)];if(keys.length&&mins>0){S.couple.timeLimit=S.couple.timeLimit||{};keys.forEach(k=>S.couple.timeLimit[k]=mins);}}
    else if(act==='加时'){const parts=arg.split(/[\|｜、,，\s]+/).filter(Boolean);const mins=parseInt((parts.find(p=>/\d/.test(p))||'').replace(/[^\d]/g,''),10);const nmPart=parts.filter(p=>!/^\d+$/.test(p)).join('、');let keys=_appKeys(nmPart||arg,Object.keys(LOCKABLE),k=>gr[k]);keys=[...new Set(keys)];if(keys.length&&mins>0){const au=ensureUsage();keys.forEach(k=>{au.bonus[k]=(au.bonus[k]||0)+mins*60;if(S.couple.locks&&S.couple.locks[k]&&S.couple.locks[k].auto)delete S.couple.locks[k];});}}
    else if(act==='解锁'){if(S.couple.locks){let keys=_appKeys(arg,Object.keys(S.couple.locks),k=>S.couple.locks[k]);[...new Set(keys)].forEach(k=>delete S.couple.locks[k]);}}
    else if(act==='禁言'){const nm=arg.split(/[、,，\|]/)[0].trim();const tgt=gagFind(nm,true);if(tgt)gagSetKey(tgt.key,np());}
    else if(act==='解禁'){const nm=arg.split(/[、,，\|]/)[0].trim();const ts=gagLockedFromText(nm);if(ts.length)ts.forEach(t=>gagDelKey(t.key));else{const tgt=gagFind(nm,false);if(tgt)gagDelKey(tgt.key);}}
    return '';
  });
  out=out.replace(/[\[【]\s*(扣款|没收零花|扣光|清空零花|冻结亲属卡|解冻亲属卡)\s*[\|｜:：]?\s*([^\]】]*)[\]】]/g,(mm,act,arg)=>{changed=true;if(S.couple.walletAuth){const nm=(c.remark||c.name);
    if(act==='扣款'||act==='没收零花'){const amt=+(((arg||'').match(/[\d.]+/)||[0])[0])||0;const actual=Math.min(amt,Math.max(0,S.me.balance));if(actual>0)addBill('out',actual,'被'+nm+'扣的零花钱');}
    else if(act==='扣光'||act==='清空零花'){const actual=Math.max(0,S.me.balance);if(actual>0)addBill('out',actual,'被'+nm+'扣光了零花钱');}
    else if(act==='冻结亲属卡')S.couple.cardFrozen=true;
    else if(act==='解冻亲属卡')S.couple.cardFrozen=false;}
    return '';});
  out=out.replace(/[\[【]\s*(关小黑屋|关禁闭|禁闭|原谅)\s*[\|｜:：]?\s*([^\]】]*)[\]】]/g,(mm,act,arg)=>{changed=true;const reason=(arg||'').replace(/[「」『』"\x27]/g,'').trim();
    if(act==='原谅'){emotionAfterForgive(c);}
    else if(S.couple.jailAuth&&!(S.jail&&S.jail.active)){setTimeout(()=>enterJail(c.id,reason,false),600);}
    return '';});
  // 挂项圈/摘项圈（归属标记）
  out=out.replace(/[\[【]\s*(?:挂|换|改|戴|套|加|上)?项圈\s*[\|｜:：]\s*([^\]】]+)[\]】]/g,(mm,t)=>{changed=true;_collarTagFired=true;S.me.collar={text:(t||'').trim().slice(0,24),by:c.id,ts:Date.now()};return '';});
  out=out.replace(/[\[【]\s*(?:摘|取|解|去|卸|拿|下)项圈\s*[\]】]/g,()=>{changed=true;_collarTagFired=true;S.me.collar=null;return '';});
  // 替她发朋友圈（以她名义）
  out=out.replace(/[\[【]\s*替发朋友圈\s*[\|｜:：]\s*([^\]】]+)[\]】]/g,(mm,t)=>{changed=true;const tx=(t||'').trim().slice(0,140);if(tx){S.moments.unshift({id:uid(),authorId:'me',text:tx,images:[],time:Date.now(),likes:[],comments:[],acct:actId(),byTa:c.id});}return '';});
  // 出门报备审批：批准 / 驳回
  out=out.replace(/[\[【]\s*(批准|驳回)\s*[\|｜:：]?\s*([^\]】]*)[\]】]/g,(mm,act,arg)=>{const op=[...msgs(c.id)].reverse().find(x=>x.type==='outpass'&&x.status==='pending');if(!op)return '';changed=true;op.status=(act==='批准')?'approved':'rejected';op.reason=(arg||'').replace(/[「」『』"\x27]/g,'').trim();op.decTs=Date.now();return '';});
  _ctFired=changed;if(changed){save();if(cur().p==='wechat'||cur().p==='home'||cur().p==='chat'||cur().p==='couple')render();}
  return out;}
let _ctFired=false,_collarTagFired=false,_collarT={};
// 他用大白话改/换/取项圈时也能生效(光说不发指令的兜底)
async function maybeCollarIntent(reply,c){if(_collarTagFired)return;if(!c||c.blocked||!isMain()||!(S.couple&&S.couple.cid===c.id))return;
  let lu='';const _ms=msgs(c.id);for(let i=_ms.length-1;i>=0;i--){if(_ms[i].role==='user'&&_ms[i].type!=='sys'){lu=msgToText(_ms[i])||'';break;}}
  const ctx=(lu+'\n'+reply);if(!/项圈|印记|归属|标记/.test(ctx))return;
  const now=Date.now();if(now-(_collarT[c.id]||0)<6000)return;_collarT[c.id]=now;
  try{const r=await chatAPI([{role:'system',content:'下面是'+S.me.name+'和"'+(c.remark||c.name)+'"的对话。判断"'+(c.remark||c.name)+'"是否给'+S.me.name+'【设置/更改/取下了"项圈(归属印记)"】。\n· 设置或更改了→提取最终要显示的那几个字(简短、就是印记本身,别带引号/emoji/多余的话)。\n· 取下了→remove为true。\n· 只是普通聊天、没动项圈→set空字符串、remove为false。\n只输出JSON：{"set":"印记文字或空","remove":true或false}。例："现在是：主人的专属小狗"→{"set":"主人的专属小狗","remove":false}'},{role:'user',content:ctx}],{max:80,aux:true});
    const d=parseObj(r);if(!d)return;
    if(d.remove){if(S.me.collar){S.me.collar=null;save();if(cur().p==='wechat')render();}return;}
    const t=(''+(d.set||'')).replace(/[「」『』"'']/g,'').trim().slice(0,24);if(t){S.me.collar={text:t,by:c.id,ts:Date.now()};save();if(cur().p==='wechat')render();}
  }catch(e){}}
